// ---------- 第四问「我们目前的关系能量走向如何？我可以做什么来影响它？」· 由第一问 + 第二问成稿专题为走向／影响重框；非第三问迁移 ----------
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_0', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（愚者正位）想对你说：走向不是「没有路」那种误会式的死局，而是两人的劲还拧在「你们不敢一起跳」上，没一起认、也没一起动。 愚者站在悬崖边，手里攥着地图；最大的阻碍，是你们一直在等一个保证、一个名分、一张安全網，才肯牵手往下走。愚者说：阻碍是「不跳」本身——你们把「未知」当成敌人，却忘了未知才是关系唯一可能长大的地方。 你站在悬崖边，手里攥着一张地图。 你要影响走向，今天就卡这一格：把「不问结果」做到底，小不要紧，但要真。`,
  psychologyLayer: `【关系现状】你们的关系没有剧本，没有约定，甚至没有「下一步」。你以为这是问题，但愚者告诉你：这是礼物。你们还在悬崖边，还没跳，所以一切都有可能。\n\n【心理层面】你害怕「没有未来」，害怕「走错路」。但你不知道，你真正怕的是那个0——0是无限可能，也是「一无所有」。你怕跳下去之后，发现自己真的什么都抓不住。\n\n【根源层面】你从小就被教「要有计划」「要结果导向」，所以你把这段关系也当成了项目。但你忘了，爱不是工程，是探险。你不敢跳，是因为从来没人告诉你：摔了也没关系。

【走向与影响】你怕的是「跳下去没人接」。你希望先确认对方会接住你、关系有未来，才肯完全投入。愚者正位提醒你：你真正怕的，是把自己交给不确定。心理层面的突破，是接纳——阻碍往往是你心里那句「等再确定一点再说」；当你愿意承认「我怕的是跳」，而不是怪罪对方不给保证，阻碍就松动了。`,
  spiritLayer: `宇宙在告诉你：你们的关系處于「量子叠加态」——它同時是所有可能的关系。一旦你非要一个定义，愚者的魔法就消失了。宇宙在等你们先跳，再问「下面是哪里」。\n\n核心启示：你不是不敢面对真相，你是舍不得那个假装有未来的地方。

若问势头卡在哪，多半是「信任未知」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「不问结果」的小事：为这段关系做一件纯粹「因为想做」的事，不附带任何「那我们算什么」的追问。不逼答案，只让行动发生。

检查你的「行囊」：愚者问你——你包里装的，是对关系的渴望，还是对「摔下去」的恐惧？若阻碍是「不敢跳」，先看清：是你不敢，还是你以为对方不敢？`,
  masterSummary: `「信任未知」松一寸，走向就变一寸——别问它叫什么，问它让你成了谁。 第二问那句仍管用：你们之间最大的阻碍，往往不是对方不给答案，而是你们不敢一起跳进未知。愚者说：阻碍是『不跳』本身。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_0', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（愚者逆位）想对你说：走向被「假装要跳、脚下在逃」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 你们卡在悬崖边，一个说要跳、一个说再等等；或你们其中一人一直用「还没准备好」当借口，迟迟不落地。愚者逆位说：最大的阻碍，是「未完成的那一步」——不是没有路，是你们不敢承认自己还在躲。 你站在悬崖边，脚趾死死扣着泥土，不是不想跳，是回头看了一眼来路——那里有摔过的伤疤、被嘲笑的莽撞、被辜負的信任。 走向听行动。今天只兑现「停下来看清」——让对方看见你在动，而不是在讲。`,
  psychologyLayer: `【关系现状】你们的关系卡在一个「不敢开始也不敢结束」的地方。你反覆问自己「要不要繼续」，其实你心里知道，繼续也不会比现在好。\n\n【心理层面】你不敢跳，不是因为不够勇敢，是因为你在等一个「绝对安全」的保证。但你不知道，安全不是等来的，是自己长出来的。你怕再摔一次，是因为上一次没人扶你起来。\n\n【根源层面】你曾经不顧一切地跳过，摔得很重。从那以后，你把「谨慎」当成了护身符，以为只要不跳，就不会再疼。但你忘了，站着不动的人，也会被時间推着走。

【走向与影响】你怕的是「落地后发现选错」。愚者逆位提醒你：你真正怕的，可能是看清关系的真相。心理层面的突破，是问——阻碍是外在的「他不表态」，还是內在的「我不敢要」？先分清，再动。`,
  spiritLayer: `宇宙在告诉你：宇宙在等你自己解开最后一条绳子。它不会替你跳，但它会一直在崖底张开双臂。真正的勇气，是带着伤疤繼续跳。\n\n核心启示：你不是不敢爱，是太怕再失去曾经的自己。

能量没有散，是聚在「未完成的一步」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「停下来看清」的小事：不推进、不追问。只寫下一句——「这段关系里，我一直在逃的是_____。」检查你的「行囊」：愚者逆位问你——你逃的，是对方还是自己？`,
  masterSummary: `想动走势，先认「未完成的一步」这道结——旧世界不扔，新世界永远在门外等你。 对照第二问：你们之间最大的阻碍，往往是那一步『未完成的跳』。愚者逆位说：先看清你在逃什么。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_1', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（魔术师正位）想对你说：走向不是「没有工具」那种误会式的死局，而是两人的劲还拧在「你们没有一起用」上，没一起认、也没一起动。 魔术师桌上有权杖、宝剑、圣杯、钱币；最大的阻碍，是其中一人或两人只会用一两样——只会行动不会说、只会分析不会感受、只談未来不談当下。魔术师说：阻碍是「通道未开」；当四样法器一起动，天地之间的通道才打开。 你手里握着四样工具——权杖（激情）、圣杯（情感）、宝剑（理性）、星币（物质）。 今天用「用一样法器」替关系试温：你动了，场的流向才会跟着变。`,
  psychologyLayer: `【关系现状】你们的关系具备一切可能：吸引力、沟通、承诺、物质基礎。但你就是觉得差点什么。魔术师告诉你：差的是你开始动手。你一直在准备，从未真正开始。\n\n【心理层面】你一直用「分析」和「准备」来逃避行动，因为你怕出手之后发现结果不可控。你问自己「这段关系的本质是什么」，其实你真正想问的是：「如果我用尽全力，失败了怎麼办？」\n\n【根源层面】你从小就被夸「聰明」，所以你习惯了只用脑子活着，把心锁在柜子里。但你不知道，爱不是逻辑题，是实验题。不动手，永远不知道结果。

【走向与影响】你怕的是「说出来就破功」。你希望对方先变、先给、先开口。魔术师正位提醒你：你真正怕的，可能是自己先显化意图。心理层面的突破，是接纳——阻碍往往是「等对方先」；你们手里都有法器，谁先动，通道就谁先开。`,
  spiritLayer: `宇宙在告诉你：宇宙把所有的材料都放在你桌上了。它不替你組装的，因为只有你亲手拼出来的，才是你的。\n\n核心启示：你不是在等一个信号，你就是信号本身。

这条关系的走势，眼下还拴在「共同创造」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「用一样法器」的小事：选一样你很少用的——权杖=主动做一件事、宝剑=说一句真心话、圣杯=表达一次感受、钱币=为关系花一点心思。不逼对方回應，只让通道开一条。检查你的「行囊」：魔术师问你——你少用的，是哪一样？为什么？`,
  masterSummary: `势头绕在「共同创造」上——你手里一直有火，只是你忘了划火柴。 第二问早已点破：你们之间最大的阻碍，往往是四样法器没有一起用。魔术师说：谁先动，通道就谁先开。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_1', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（魔术师逆位）想对你说：走向被「通道堵住了」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 话说不出口、行动对不上、或你们一直在用错的工具——用爭吵要亲密、用沉默要理解。魔术师逆位说：最大的阻碍，是「创造的意图没有对齊」；不是没有爱，是表达爱的方式互相错过。 你桌上摆滿了工具，但你只用它们来分析、犹豫、咨询。 你能拧动的开关往往在细节：今天把「对齊」做实，比分析十句有用。`,
  psychologyLayer: `【关系现状】你们的关系停留在「可能性」阶段——可以这样，可以那样，但什么都没发生。你们聊过未来，但从来没为未来做过一件事。\n\n【心理层面】你害怕一旦开始，就证明自己不行。所以你宁愿停在「我本来可以」。你问自己「他是不是对的人」，其实你真正想问的是：「如果开始了，发现不是，我该怎麼面对？」\n\n【根源层面】你曾经试过，结果不好。那次之后，你就把「不开始就不会失败」当成了人生信条。但你忘了，爱不是考试，没有「弃考」选项。

【走向与影响】你怕的是「说清楚就没戲」。魔术师逆位提醒你：你真正怕的，可能是真相。心理层面的突破，是问——阻碍是「我们不会表达」，还是「我们不敢表达」？`,
  spiritLayer: `宇宙在告诉你：宇宙在等你喊出第一句咒語。真正的魔法师不是天生会变，是敢先举手。你不举手，永远不会有回應。\n\n核心启示：你缺的不是能力，是敢动手的勇气。

能量没有散，是聚在「意图未对齊」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「对齊」的小事：用一句话说出你「真正想从这段关系里得到的」——不指责对方，只说自己。检查你的「行囊」：魔术师逆位问你——你堵住的，是话还是恐惧？`,
  masterSummary: `想动走势，先认「意图未对齊」这道结——你一直等万事俱备，却不知道东風就是你自己。 对照第二问：你们之间最大的阻碍，往往是通道堵住、意图未对齊。魔术师逆位说：把法器摆正，再试一次。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_2', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（女祭司正位）想对你说：走向不是「没有答案」那种误会式的死局，而是两人的劲还拧在「你们没有靜下来听」上，没一起认、也没一起动。 女祭司膝上是无字的书；最大的阻碍，是你们一直在用头脑问「我们是什么」「他到底怎麼想」，却没有留時间给直觉、给沉默、给心里最早浮现的那句话。女祭司说：阻碍是「噪音太大」——分析、猜測、追问，蓋过了关系底下真正的声音。 我坐在黑白双柱之间，帷幕半掩，手里握着那卷被封印的律法书。 你若真想推动走势，就从「靜下来」开始——轻，但要真。`,
  psychologyLayer: `【关系现状】你们的关系有一种「沉默的默契」——有些话没说出来，但你们好像都知道。女祭司告诉你：这不是逃避，这是更深层的沟通。只是你还不习惯这种安靜。\n\n【心理层面】你害怕沉默，害怕不确定。你总想从对方嘴里听到「我爱你」「我保证」「我永远」。但你不知道，真正重要的东西，从来不用说出来。你问「这段关系的本质是什么」，其实你真正想问的是：「他到底怎麼想的？」\n\n【根源层面】你曾经被言語伤害过，所以你把「说出来」当成了安全。但有些人的爱，是藏在沉默里的。你越逼他说话，他越躲。不是不爱，是方式不同。

【走向与影响】你怕的是「靜下来会听见不想听的」。女祭司正位提醒你：你真正怕的，可能是面对心里早已知道、却不敢承认的事。心理层面的突破，是接纳——阻碍往往是「不愿靜」；当你们愿意一起闭嘴十分鐘，听听心里第一个念头，阻碍会自己浮出来。`,
  spiritLayer: `宇宙在告诉你：宇宙在教你「不用耳朵去听」。闭上眼，你能感觉到这段关系的溫度吗？能感觉到，就是真的。\n\n核心启示：你不知道的，才是真的。

这条关系的走势，眼下还拴在「未傾听的內在」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「靜下来」的小事：留十分鐘，不问对方、不查手机。只问自己：「我们之间，我最怕面对的是_____？」不逼答案，只听第一个冒出来的詞。检查你的「行囊」：女祭司问你——你不敢听的，是什么？`,
  masterSummary: `势头绕在「未傾听的內在」上——有些爱，说出来就错了。 第二问早已点破：你们之间最大的阻碍，往往在你们靜下来時才听得见。女祭司说：先靜，再问。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_2', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（女祭司逆位）想对你说：走向被「该靜的没靜、该说的没说」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 你们卡在表面和谐或冷戰里，直觉被壓抑、真话被吞回去。女祭司逆位说：最大的阻碍，是「內在的声音没有被自己听见」——你或对方心里早有答案，却不敢承认、不敢说出来，于是关系卡在「假装不知道」里。 你太吵了。 别等对方先示范。今天你先用「说出一句」给关系一个可跟的节拍。`,
  psychologyLayer: `【关系现状】你们的关系里充滿了「猜」——你猜他这句话什么意思，猜他那条朋友圈是谁发的，猜他是不是不爱了。你们之间隔着一层雾，你以为是雾，其实是你的焦慮。\n\n【心理层面】你害怕未知，所以拼命找「迹象」。你问「这段关系的本质是什么」，其实你真正想问的是：「他会不会走？」但你不敢直接问，所以你把它包装成无数个小问题。\n\n【根源层面】你曾经被突然抛弃过，所以你再也不敢信「自然」。你觉得只要不盯着，就会失去。但你不知道，盯着的人，也会把对方盯走。

【走向与影响】你怕的是「说出来就崩」。女祭司逆位提醒你：你真正怕的，可能是戳破假象。心理层面的突破，是问——阻碍是「我们不愿听」，还是「我们不敢说」？`,
  spiritLayer: `宇宙在告诉你：宇宙在等你放下放大镜。感情不是证据，是感觉。你越分析，它越散。\n\n核心启示：你听见的不是真相，是你怕的真相。

就走向而言，两人的气机还绕在「未说出的真相」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「说出一句」的小事：选一句你一直没说出口的、关于这段关系的真话，寫下来或对对方说。不逼回應，只让话被听见。检查你的「行囊」：女祭司逆位问你——你壓着的，是什么？`,
  masterSummary: `走向的纽子在「未说出的真相」——你一直在猜他，却从来没问过自己：我为什么这麼怕？ 要推动它，记着第二问那句：你们之间最大的阻碍，往往是没被听见的內在声音。女祭司逆位说：先听见自己，再说出来。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_3', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（皇后正位）想对你说：走向不是「没有爱」那种误会式的死局，而是两人的劲还拧在「没有滋养的空间」上，没一起认、也没一起动。 皇后坐在繁花中；最大的阻碍，是你们其中一人或两人「给不出」或「接不住」——要麼付出到枯竭、要麼不敢接受被爱；要麼用控制代替滋养、要麼用討好代替真实。皇后说：阻碍是「土壤不够肥」；关系需要两个人都能先滿自己的杯，再溢出给对方。 我坐在花园里，脚下是麦穗，头顶是葡萄藤，怀里抱着一枚溫热的金币。 把力气花在看得见的一步：今天只做「先滿自己的杯」，做完就停。`,
  psychologyLayer: `【关系现状】你们的关系有一种「自然生长的丰盛」。不用刻意经营，它自己就在变好。像一棵树，陽光和水都有了，它自己会长。你不需要做什么，只需要在。\n\n【心理层面】你害怕「不做任何事」，因为你觉得不做事就等于不努力。但你不知道，有些关系，越努力越糟。你问「这段关系的本质是什么」，其实你真正想问的是：「我什么都不做，它还会在吗？」\n\n【根源层面】你从小就被教育「要努力才能得到」，所以你习惯性地在关系里也「幹活」。但女皇告诉你：真爱不是靠努力換来的，是靠「在」換来的。

【走向与影响】你怕的是「不付出就不被爱」。皇后正位提醒你：你真正怕的，可能是自己的匱乏。心理层面的突破，是接纳——阻碍往往是「一方一直在给、一方一直在收」，或两人都没學会先滋养自己。`,
  spiritLayer: `宇宙在告诉你：宇宙在教你「存在本身就是价值」。你不是要成为什么，你本来就是。你在这段关系里，就是最大的貢獻。\n\n核心启示：你什么也不用做，你只要在，就够了。

这条关系的走势，眼下还拴在「滋养的平衡」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「先滿自己的杯」的小事：做一件纯粹为自己滋养的事——不为对方、不为关系。再问自己：这段关系里，我给的是丰盛还是掏空？检查你的「行囊」：皇后问你——你缺的，是对方的回报，还是自己的自爱？`,
  masterSummary: `势头绕在「滋养的平衡」上——爱不是种出来的，是它自己长出来的。 第二问早已点破：你们之间最大的阻碍，往往是滋养的空间不够——先滿自己的杯，阻碍才松动。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_3', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（皇后逆位）想对你说：走向被「滋养变成了控制或依賴」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 要麼用付出綁住对方、要麼用索取掏空对方；要麼觉得自己给得太多没被看见、要麼不敢要。皇后逆位说：最大的阻碍，是「爱的流动卡住了」——不是没有爱，是爱没有以健康的方式交換；一方或双方卡在「不给就没安全感」或「要了就怕掉价」。 你的花园枯了。 影响走向不靠喊话，靠落地。今天完成「松手」，再谈别的。`,
  psychologyLayer: `【关系现状】你们的关系里，你一直在「给」。给情绪价值，给時间，给包容，给原諒。你把自己活成了一个补给站，却从没问过自己：谁来补给站补给？\n\n【心理层面】你以为给得多，就会被爱得多。但女皇逆位告诉你：你给出去的，有多少是别人要的？有多少是你为了「被需要」硬塞的？你问「这段关系的本质是什么」，其实你真正想问的是：「我这麼付出，他怎麼还不滿足？」\n\n【根源层面】你从小就被教「付出才有回报」，所以你用付出来換爱。但你不知道，有些人是不回收的。

【走向与影响】你怕的是「不控制就失去」。皇后逆位提醒你：你真正怕的，可能是关系失控。心理层面的突破，是问——阻碍是「我们不会滋养」，还是「我们在用付出換控制」？`,
  spiritLayer: `宇宙在告诉你：宇宙在等你停下来。先把自己这块地耕好，再想怎麼给别人。\n\n核心启示：你不是不被爱，是你一直没爱过自己。

这条关系的走势，眼下还拴在「流动失衡」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「松手」的小事：选一件你习惯「用付出綁住」的事，今天少做一点，让对方有空间。检查你的「行囊」：皇后逆位问你——你给的，是爱还是控制？`,
  masterSummary: `势头绕在「流动失衡」上——你一直往外给，却忘了自己早就空了。 第二问早已点破：你们之间最大的阻碍，往往是爱没有健康地流动。皇后逆位说：滋养不是控制。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_4', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（皇帝正位）想对你说：走向不是「没有结構」那种误会式的死局，而是两人的劲还拧在「结構太硬或太松」上，没一起认、也没一起动。 皇帝坐鎮宝座；最大的阻碍，是其中一人过度主导、訂规矩、不听对方，或反过来两人都不敢定界線、不敢負责，关系变成没人掌舵。皇帝说：阻碍是「秩序与彈性的失衡」——要麼权威壓死了柔软，要麼没有权威所以一盤散沙。 我坐在石座上，手里握着权杖，身后是绵延的山脉。 影响走向不靠喊话，靠落地。今天完成「一起訂一条」，再谈别的。`,
  psychologyLayer: `【关系现状】你们的关系里，有一个人（可能是你）在扮演「定规矩的人」。谁主动、谁妥協、谁負责未来——这些问题背后，其实是权力的角力。皇帝说：这段关系的本质，是「秩序」。但秩序是谁定的？\n\n【心理层面】你害怕混亂，所以你要掌控。你以为掌控了节奏，就掌控了关系。但你不知道，你掌控的只是表面。你问「这段关系的本质是什么」，其实你真正想问的是：「我能不能相信他会留下？」\n\n【根源层面】你从小就被教「要堅強」「要負责」，所以你习惯了当那个「扛事的人」。但在关系里，扛事和控事是两回事。你以为你在保护，其实你在防御。

【走向与影响】你怕的是「一软就亂」或「一硬就散」。皇帝正位提醒你：你真正怕的，可能是失控或不被尊重。心理层面的突破，是接纳——阻碍往往是「谁来定规矩」的角力；关系需要结構，但结構要两人一起訂。`,
  spiritLayer: `宇宙在告诉你：宇宙在教你「真正的力量是敢放手」。你握得越紧，对方越想逃。真正的皇帝，不是控制一切，是让一切有秩序地流动。\n\n核心启示：你不是在保护关系，你是在保护那个怕失控的自己。

能量没有散，是聚在「责任与界線」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「一起訂一条」的小事：和对方談一条「我们都同意的界線或规則」——不逼多，只訂一条。检查你的「行囊」：皇帝问你——你爭的，是秩序还是控制权？`,
  masterSummary: `想动走势，先认「责任与界線」这道结——真正的王，不是坐在王座上的人，是敢从王座上走下来的人。 对照第二问：你们之间最大的阻碍，往往是秩序与彈性的失衡。皇帝说：结構要两人一起訂。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_4', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（皇帝逆位）想对你说：走向被「专制或逃避责任」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 要麼一方用权威壓人、听不进意见，要麼两人都不敢做决定、不敢承诺，关系卡在「谁也不肯先表态」。皇帝逆位说：最大的阻碍，是「权威的错用或弃用」——不是没有爱，是爱被权力遊戲或逃避綁架了。 王座倒了，权杖滾在一边。 把力气花在看得见的一步：今天只做「让一步或担一步」，做完就停。`,
  psychologyLayer: `【关系现状】你们的关系里，没人愿意「说了算」。要麼互相推诿，要麼一起逃避。该谁主动？该谁妥協？该谁规划未来？没人接招。这段关系的本质，是「权力的真空」。\n\n【心理层面】你害怕承担责任，因为承担意味着「如果搞砸了，就是我的错」。所以你宁愿不表态、不承诺、不规划。你问「这段关系的本质是什么」，其实你真正想问的是：「如果我先认真，他会不会笑我？」\n\n【根源层面】你曾经试过当「負责的那个人」，结果被指责、被抛弃。从那以后，你就把「不表态」当成了护身符。但你不知道，不表态也是一种表态——表态的是「我不在乎」。

【走向与影响】你怕的是「让步就输」或「表态就負责」。皇帝逆位提醒你：你真正怕的，可能是失去主导或背上责任。心理层面的突破，是问——阻碍是「我们太強硬」，还是「我们不敢担当」？`,
  spiritLayer: `宇宙在告诉你：宇宙在等你接过那根权杖。不是要你控制对方，是要你为自己的选择負责。关系里可以没有皇帝，但不能没有人愿意先站出来。\n\n核心启示：你不是没有立场，你只是怕立场会让你失去他。

就走向而言，两人的气机还绕在「权威的错用」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「让一步或担一步」的小事：选一件你习惯「我说了算」或「我不表态」的事，今天反过来做一次。检查你的「行囊」：皇帝逆位问你——你抓紧的，是权力还是恐惧？`,
  masterSummary: `走向的纽子在「权威的错用」——你以为不表态就安全，其实不表态的人，最先出局。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是权威的错用或弃用。皇帝逆位说：该傾听時傾听，该决斷時决斷。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_5', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（教皇正位）想对你说：走向不是「没有傳統或共識」那种误会式的死局，而是两人的劲还拧在「被教条或外界声音綁架」上，没一起认、也没一起动。 教皇手持权杖与经书；最大的阻碍，是你们其中一人或两人太在意「别人怎麼看」「應该怎样」「正常情侶该怎样」，用外在标准取代了两人之间的真实节奏。教皇说：阻碍是「标准答案」——当关系活在外人眼光或社会剧本里，你们自己的声音就听不见了。 我站在祭坛前，手里拿着经书，脚下跪着寻求指引的人。 别等对方先示范。今天你先用「问自己」给关系一个可跟的节拍。`,
  psychologyLayer: `【关系现状】你们的关系符合某种「标准」——门当戶对、父母认可、周圍人羡慕。但你就是觉得差点什么。教皇告诉你：标准是别人的，感受是自己的。你问「这段关系的本质是什么」，其实你真正想问的是：「我们这样，算对吗？」\n\n【心理层面】你害怕「选错」，所以你需要外界不斷确认。闺蜜说好你就安心，父母皱眉你就动摇。你以为你在找答案，其实你在找背书。但你不知道，真正的答案从来不在别人嘴里。\n\n【根源层面】你从小就被教「要听话」「要选对」。所以你习惯了让别人替你选。但在感情里，没有「对」的选项，只有「你的」选项。

【走向与影响】你怕的是「不符合期待」。教皇正位提醒你：你真正怕的，可能是被評判。心理层面的突破，是接纳——阻碍往往是「我们在演别人眼中的我们」；当你们愿意问「我们要什么」而不是「别人觉得该怎样」，阻碍就松动了。`,
  spiritLayer: `宇宙在告诉你：宇宙不会替你选。它只会把两个人放在你面前，然后问你：你选谁？你选了，就是对的。\n\n核心启示：这段关系的本质，不是「对不对」，是「是不是你的」。

就走向而言，两人的气机还绕在「外在标准」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「问自己」的小事：寫下一句——「这段关系里，我一直因为『别人会怎麼看』而没做的是_____。」不逼立刻改，只让觉察发生。检查你的「行囊」：教皇问你——你守的，是共識还是别人的剧本？`,
  masterSummary: `走向的纽子在「外在标准」——别人给的是祝福，你给的才是答案。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是被『應该怎样』綁架。教皇说：寫你们自己的经。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_5', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（教皇逆位）想对你说：走向被「僵化的教条或反叛教条」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 要麼一方用「傳統」「應该」壓人，要麼两人刻意不談未来、不给承诺，用「我们不一样」当借口逃避深度。教皇逆位说：最大的阻碍，是「没有找到屬于你们两人的共識」——不是要跟别人一样，但也不能用叛逆代替真话。 经书合上了。 你若真想推动走势，就从「我们的规則」开始——轻，但要真。`,
  psychologyLayer: `【关系现状】你们的关系不符合任何「标准」——年齡差、距離、身份、性别、过往。周圍的人不看好，你自己也动摇。你问「这段关系的本质是什么」，其实你真正想问的是：「我们这样，可以吗？」\n\n【心理层面】你太在乎「别人怎麼看」了。你怕选错了，会成为笑话。所以你一直在等一个权威——父母点头、朋友认可、占卜说好——才敢投入。但你不知道，等来的永远是别人的答案，不是你的。\n\n【根源层面】你从小就被教「要合群」「要正常」。所以你习惯了用别人的标准量自己。但在爱情里，没有标准答案。你越翻经书，越找不到自己的名字。

【走向与影响】你怕的是「被綁住」或「不被认可」。教皇逆位提醒你：你真正怕的，可能是承诺或孤单。心理层面的突破，是问——阻碍是「我们太在意外界」，还是「我们不敢建立自己的规則」？`,
  spiritLayer: `宇宙在告诉你：宇宙给你的不是经书，是一张白纸。上面寫什么，你自己定。别人寫的，都是别人的故事。\n\n核心启示：你不需要任何人批准，你只需要自己签字。

若问势头卡在哪，多半是「共識未成」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「我们的规則」的小事：和对方说一句——「我希望我们之间可以_____。」不逼对方同意，只让需求被听见。检查你的「行囊」：教皇逆位问你——你反叛的，是教条还是亲密？`,
  masterSummary: `「共識未成」松一寸，走向就变一寸——你的名字，不在别人的经书里。在你自己的第一页。 第二问那句仍管用：你们之间最大的阻碍，往往是没有屬于两人的共識。教皇逆位说：不必跟别人一样，但要说真话。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_6', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（恋人正位）想对你说：走向不是「没有爱」那种误会式的死局，而是两人的劲还拧在「没有选同一条路」上，没一起认、也没一起动。 恋人牌中天使在雲端、男女在生命树下；最大的阻碍，是价值觀或人生方向没有对齊——一个要安定、一个要自由；一个要婚姻、一个还不想定；或你们迟迟不敢在十字路口做「我们一起走」的选择。恋人说：阻碍是「未完成的选择」；不是不爱，是还没选同一条路。 你站在两条路中间，左边是熟悉，右边是未知。 你能拧动的开关往往在细节：今天把「说出你的路」做实，比分析十句有用。`,
  psychologyLayer: `【关系现状】你们的关系處于一种「神圣的两难」——你爱他，但你也在爱自己。你怕选了爱情就丟了自我，选了自我就没了爱情。恋人告诉你：这不是选择题，是镜子。你在他身上看到的，是你自己还没活出来的部分。\n\n【心理层面】你怕选错。你怕选了之后，发现另一边更好。但你不知道，真正让你痛苦的，不是错的选择，是选了之后一直回头看。你问「这段关系的本质是什么」，其实你真正想问的是：「我能不能既要又要？」\n\n【根源层面】你从小就被教育「要有最优解」，所以你连爱情也想算出个最优选。但恋人牌告诉你：爱不是答案，是问题。它逼你面对那个最真实的自己。

【走向与影响】你怕的是「选错人」或「对方不选我」。恋人正位提醒你：你真正怕的，可能是承诺或拒绝。心理层面的突破，是接纳——阻碍往往是「我们不敢談要什么」；当你们愿意在生命树下说出各自的路，对齊或分开都会清晰。`,
  spiritLayer: `宇宙在等你做一件事：选一个人，然后选完之后，把另一个选项徹底忘掉。这才是选择的代价，也是选择的礼物。\n\n核心启示：你怕的不是选错，是选了之后，再也怪不了别人。

这条关系的走势，眼下还拴在「选择与对齊」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「说出你的路」的小事：寫下一句或对对方说——「在这段关系里，我最不可妥協的是_____。」不逼对方立刻对齊，只让选择被看见。检查你的「行囊」：恋人问你——你不敢选的，是什么？`,
  masterSummary: `势头绕在「选择与对齊」上——真正的选择不是选左边还是右边，是敢对自己说：「我选的就是我。」 第二问早已点破：你们之间最大的阻碍，往往是没有选同一条路。恋人说：在十字路口停下来，看清再走。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_6', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（恋人逆位）想对你说：走向被「选错了或不敢选」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 要麼价值觀从头就没对齊、要麼其中一人或两人不敢在关系里做明确选择，用曖昧或拖延代替「要或不要」。恋人逆位说：最大的阻碍，是「未对齊的选择」——不是没有吸引力，是吸引力没有化成同一方向的脚步。 你们背对背站着，不是不爱，是你们都怕转过来之后，看到对方眼睛里的自己。 今天用「对齊或放手」替关系试温：你动了，场的流向才会跟着变。`,
  psychologyLayer: `【关系现状】你们的关系卡在「曖昧」或「矛盾」里——谁都不肯先开口，谁都不肯先承诺。你等他主动，他等你确认。你们把時间耗在了「谁先」上，而不是「我们」上。\n\n【心理层面】你怕的不是他不爱你，是怕你付出了真心之后，发现他不配。所以你用犹豫当护身符，把选择权推给他。你问「这段关系的本质是什么」，其实你真正想问的是：「我能不能不用負责地拥有他？」\n\n【根源层面】你曾经选错过，被伤过。那次之后，你发誓再也不主动。但你忘了，不选，也是一种选——你选了永远站在原地。

【走向与影响】你怕的是「选了就要負责」。恋人逆位提醒你：你真正怕的，可能是承诺。心理层面的突破，是问——阻碍是「我们要的不一样」，还是「我们不敢说要什么」？`,
  spiritLayer: `宇宙在等你举手。爱不是等来的，是选来的。你一直不选，爱就一直在门口站着，風里雨里，等你开门。\n\n核心启示：你不是在等对的人，你是在等一个不用你选的人。

这条关系的走势，眼下还拴在「选择未完成」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「对齊或放手」的小事：问自己——「我们要的，是不是同一条路？」若不知道，就和对方談一次。检查你的「行囊」：恋人逆位问你——你卡住的，是爱还是怕选错？`,
  masterSummary: `势头绕在「选择未完成」上——爱从来不是等来的，是你选了之后，它才来的。 第二问早已点破：你们之间最大的阻碍，往往是未对齊的选择。恋人逆位说：不选，時间一样在走。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_7', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（戰車正位）想对你说：走向不是「没有方向」那种误会式的死局，而是两人的劲还拧在「两匹馬往不同方向拉」上，没一起认、也没一起动。 戰車上的人要前进，但黑白两獸一左一右；最大的阻碍，是你们的意志没有合一——一个想冲、一个想停；一个要结果、一个要过程；或外在壓力、第三者、家庭反对在把你们往两边拉。戰車说：阻碍是「方向未統一」；不先馴服內在的拉扯，关系的車动不了。 你驾着戰車，两匹馬一黑一白，拼命往前跑。 走向听行动。今天只兑现「同向」——让对方看见你在动，而不是在讲。`,
  psychologyLayer: `【关系现状】你们的关系在「冲刺」。可能是热恋期，也可能是矛盾期。总之，你们都在用力，都想快点到某个地方。但戰車问你：你们这麼急，是要去哪？\n\n【心理层面】你怕输。你怕这场关系你输了，就证明你不行。所以你拼命控制、拼命表现、拼命让一切「按计划走」。但你不知道，爱不是比赛，没有输赢。你问「这段关系的本质是什么」，其实你真正想问的是：「我能不能赢？」\n\n【根源层面】你从小就被拿来和别人比。比成绩、比听话、比谁更被喜欢。你把这种競爭模式带进了爱情里，以为只要赢了，就能被爱。但戰車告诉你：赢了的人，也可能是一个人站在终点。

【走向与影响】你怕的是「一让步就输」。戰車正位提醒你：你真正怕的，可能是失去主导。心理层面的突破，是接纳——阻碍往往是「谁的目标优先」；关系需要两人往同一个方向使力。`,
  spiritLayer: `宇宙在教你學会「停下来」。冲得再快，如果方向错了，也只是在错上加码。你要看的不是速度，是方向。\n\n核心启示：你冲的不是终点，是怕停。

这条关系的走势，眼下还拴在「意志合一」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「同向」的小事：和对方说一句——「我们这段关系，接下来最想一起达成的是_____。」不逼立刻做，只让方向对齊。检查你的「行囊」：戰車问你——你拉的是关系，还是自己的目标？`,
  masterSummary: `势头绕在「意志合一」上——真正的勝利不是你到了哪，是你敢停下来，看看他在不在。 第二问早已点破：你们之间最大的阻碍，往往是两匹馬往不同方向拉。戰車说：先同向，再前进。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_7', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（戰車逆位）想对你说：走向被「車翻了或卡住了」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 要麼強推导致冲突、要麼逃避导致停滯；要麼外在壓力把你们壓垮、要麼內在矛盾让你们动彈不得。戰車逆位说：最大的阻碍，是「用错力或不用力」——不是没有爱，是前进的方式伤了彼此或卡住了。 戰車翻了，馬跑了，你摔在地上，一身泥。 你要影响走向，今天就卡这一格：把「停下来对齊」做到底，小不要紧，但要真。`,
  psychologyLayer: `【关系现状】你们的关系「失控了」。可能吵架了，可能冷暴力，可能有一方想撤了。你觉得一切都亂了，但戰車逆位问你：那些你以为控住的日子，是真的控住了吗？\n\n【心理层面】你怕失控，因为你从小到大都在控——控成绩、控形象、控别人的看法。你把这段关系也当成了又一个要控的项目。但你现在发现，你控不了。你问「这段关系的本质是什么」，其实你真正想问的是：「为什么我控不住了？」\n\n【根源层面】你曾经因为失控受过伤，所以你再也不相信「自然」。你觉得只有抓在手里才是安全的。但你不知道，抓得太紧的东西，也会被你抓死。

【走向与影响】你怕的是「一停就散」或「一冲就崩」。戰車逆位提醒你：你真正怕的，可能是失控。心理层面的突破，是问——阻碍是「我们太冲」，还是「我们不敢冲」？`,
  spiritLayer: `宇宙在让你學会「放手」。控不住的，本来就不是你的。能走的，就让它走。留下的，才是你的。\n\n核心启示：你怕的不是失去他，是失去控制之后，发现自己什么也不是。

能量没有散，是聚在「前进的方式」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「停下来对齊」的小事：不逼进度，只和对方談一次——「我们卡在哪里？」检查你的「行囊」：戰車逆位问你——你推的，是关系还是自己的焦慮？`,
  masterSummary: `想动走势，先认「前进的方式」这道结——真正的自由，不是想控就能控，是控不住的時候，还能笑。 对照第二问：你们之间最大的阻碍，往往是前进的方式错了。戰車逆位说：先停下来对齊，再动。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_8', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（力量正位）想对你说：走向不是「没有爱」那种误会式的死局，而是两人的劲还拧在「用错了力」上，没一起认、也没一起动。 力量牌中女子馴獅，用柔而非用蠻；最大的阻碍，是你们其中一人或两人用控制、爭吵、冷戰、指责去要亲密，而不是用耐心、接纳、傾听去化解恐惧。力量说：阻碍是「蠻力取代了溫柔」——关系需要的是馴服內在的獸，不是打败对方。 你蹲在獅子面前，手轻轻撫着它的头。 你要影响走向，今天就卡这一格：把「用柔」做到底，小不要紧，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里有「野獸」——可能是他的脾气、你的敏感、你们之间的某道坎。你们一直想制服对方，或者制服自己。但力量牌告诉你：你不需要制服，你只需要伸手摸一摸。\n\n【心理层面】你怕那头野獸。你怕它失控、怕它伤人、怕它把一切都毀了。但你不知道，它也是你的一部分。你问「这段关系的本质是什么」，其实你真正想问的是：「我怎麼才能让它听话？」\n\n【根源层面】你从小就被教「要控制情绪」，所以你把所有「不该有」的念头都关在籠子里。但籠子关久了，野獸会瘋。它咬的不是别人，是你自己。

【走向与影响】你怕的是「一软就被吃定」。力量正位提醒你：你真正怕的，可能是脆弱。心理层面的突破，是接纳——阻碍往往是「我们用硬的方式要软的结果」；溫柔不是弱，是另一种強。`,
  spiritLayer: `宇宙在教你「溫柔的力量」。真正的勇气，不是壓住憤怒，是承认你害怕。当你敢说「我疼」，獅子就趴下了。\n\n核心启示：你以为是獅子太強，其实是你忘了，你手里一直有馴獸师的鞭子——叫「溫柔地承认我怕了」。

就走向而言，两人的气机还绕在「力的品质」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「用柔」的小事：选一件你习惯「硬碰硬」的事，今天用一句溫柔的话或一个接纳的姿态代替。检查你的「行囊」：力量问你——你用的，是蠻力还是勇气？`,
  masterSummary: `走向的纽子在「力的品质」——真正的力量不是按住那头獅子，是你敢在它吼叫的時候，还站在它面前。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是用蠻力要亲密。力量说：馴服內在的獸，用柔不用硬。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_8', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（力量逆位）想对你说：走向被「失控或壓抑」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 要麼情绪爆发、占有慾、不安全感把关系撕扯；要麼不敢表达需求、一味討好，壓抑到某天崩潰。力量逆位说：最大的阻碍，是「內在的獸没有被馴服」——不是没有爱，是恐惧与本能跑在爱前面。 獅子掙脫了你的手，或者你被它壓倒了。 走向听行动。今天只兑现「接纳恐惧」——让对方看见你在动，而不是在讲。`,
  psychologyLayer: `【关系现状】你们的关系里充滿「失控的情绪」——憤怒、恐惧、猜疑。你以为这是对方的问题，但力量逆位问你：你对自己的情绪，是不是也这麼陌生？\n\n【心理层面】你每次发脾气，是真的因为现在这件事，还是因为小時候那个不敢哭的孩子，终于找到机会爆发了？你罵他的那些话，有多少是罵给你自己听的？\n\n【根源层面】你从没被教会怎麼處理情绪。你只被教会「不准哭」「不許怕」「不要生气」。所以你把这些都壓着，壓到壓不住了，就全倒进关系里。

【走向与影响】你怕的是「露出獸就没人爱」。力量逆位提醒你：你真正怕的，可能是被看见脆弱。心理层面的突破，是问——阻碍是「我们太壓抑」，还是「我们太失控」？`,
  spiritLayer: `宇宙在等你承认：你也是个人。人会怕，会软，会需要人抱。你不是超人，你只是一个需要被接住的人。\n\n核心启示：你以为是獅子太強，其实是你太久没餵它了。

能量没有散，是聚在「內在的獸」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「接纳恐惧」的小事：寫下一句——「这段关系里，我最怕被看见的是_____。」不逼解决，只让恐惧被承认。检查你的「行囊」：力量逆位问你——你壓着的，是什么獸？`,
  masterSummary: `想动走势，先认「內在的獸」这道结——真正的力量不是永远不倒下，是倒了之后，还愿意起来。 对照第二问：你们之间最大的阻碍，往往是內在的獸未被馴服。力量逆位说：先接纳，再馴服。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_9', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（隱者正位）想对你说：走向不是「没有答案」那种误会式的死局，而是两人的劲还拧在「没有独處与內省」上，没一起认、也没一起动。 隱者持燈独行；最大的阻碍，是你们没有留時间给自己——没有先问「我要什么」「我为什么在这段关系里」，就一直在反應对方、反應外界。隱者说：阻碍是「噪音蓋过了內在的燈」；不先独自点燈，两人在一起也只是两團黑影。 你一个人提着燈，走在雪地里。 今天用「独處十分鐘」替关系试温：你动了，场的流向才会跟着变。`,
  psychologyLayer: `【关系现状】你们的关系需要「空间」。不是冷淡，是各自有各自的雪地要踩。你想24小時黏着，但隱士说：你先走好自己的路，他才会向你走来。\n\n【心理层面】你怕孤独。你怕一个人走，怕他不来。但你不知道，独處不是没人陪，是你能和自己待着。你问「这段关系的本质是什么」，其实你真正想问的是：「我能靠他多久？」\n\n【根源层面】你从小就被陪惯了。有人幫你寫作業，有人陪你吃飯，有人告诉你该怎麼做。你从来没真正一个人走过。所以现在你怕，怕一放手，就真的没人了。

【走向与影响】你怕的是「靜下来会发现不爱」。隱者正位提醒你：你真正怕的，可能是面对自己。心理层面的突破，是接纳——阻碍往往是「我们不敢独處」；当你们愿意各自先点亮自己的燈，再照见彼此，阻碍会清晰。`,
  spiritLayer: `宇宙在教你「孤独的功課」。不是让你永远一个人，是让你學会：当你一个人的時候，你还知道你是谁。\n\n核心启示：你不是怕他不来，你是怕自己根本不会走。

这条关系的走势，眼下还拴在「內省」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「独處十分鐘」的小事：不找对方、不查手机。只问自己：「这段关系里，我最需要的是_____？」检查你的「行囊」：隱者问你——你逃的，是独處还是答案？`,
  masterSummary: `势头绕在「內省」上——真正的陪伴，是两个会独處的人，在路口遇见。 第二问早已点破：你们之间最大的阻碍，往往是没有先独自点燈。隱者说：先內省，再照见彼此。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_9', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（隱者逆位）想对你说：走向被「逃避內省或孤绝」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 要麼不敢面对「这段关系到底適不適合我」、用忙碌或对方填滿空白；要麼过度退縮、冷戰、不沟通，用「我需要空间」当牆。隱者逆位说：最大的阻碍，是「该点燈時不点燈」——不是没有答案，是你们不敢一个人靜下来看。 你把自己藏起来了。 你能拧动的开关往往在细节：今天把「点燈」做实，比分析十句有用。`,
  psychologyLayer: `【关系现状】你们的关系里有一块「禁區」——是你不想談的话题、不想面对的现实、不想承认的真相。你以为躲过去就没事了，但隱士逆位说：你看不见的地方，才是问题的根。\n\n【心理层面】你怕看清，因为看清之后，就不能装傻了。你问「这段关系的本质是什么」，其实你真正想问的是：「能不能就这样混下去，别逼我？」\n\n【根源层面】你曾经在某个地方摔过，那次摔得太狠，所以你再也不敢低头看。你把眼睛蒙起来，以为看不见就不疼。但你没蒙眼睛，你蒙的是心。

【走向与影响】你怕的是「看清就不爱了」。隱者逆位提醒你：你真正怕的，可能是真相。心理层面的突破，是问——阻碍是「我们不愿独處」，还是「我们不敢面对独處時浮现的答案」？`,
  spiritLayer: `宇宙在等你把燈撿起来。它没滅，只是倒了。你把它扶起来，就能看见——他其实一直在等你。\n\n核心启示：你不是怕他走，你是怕他走了之后，你终于要一个人面对自己。

能量没有散，是聚在「未內省」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「点燈」的小事：设定十分鐘，只許想「这段关系对我意味着什么」。不逼结論，只记住第一个冒出来的念头。检查你的「行囊」：隱者逆位问你——你逃的，是什么？`,
  masterSummary: `想动走势，先认「未內省」这道结——真正的黑暗不是没燈，是你闭着眼，还騙自己说已经走了。 对照第二问：你们之间最大的阻碍，往往是不敢一个人点燈。隱者逆位说：你逃的，可能就是答案。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_10', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（命運之輪正位）想对你说：走向不是「没有緣分」那种误会式的死局，而是两人的劲还拧在「不愿接受輪会转」上，没一起认、也没一起动。 命運之輪转动，有時在上、有時在下；最大的阻碍，是你们其中一人或两人无法接受「关系有高有低」——低的時候就恐慌、指责、或想逃，不肯一起待在輪上等它再转上来。命運之輪说：阻碍是「对变化的抗拒」；当你们愿意相信「我们还在同一个輪上」，阻碍就从「怕掉下去」变成「一起转」。 轮子在转。 把力气花在看得见的一步：今天只做「信輪」，做完就停。`,
  psychologyLayer: `【关系现状】你们的关系像是「命中注定」。相遇的方式、心动的瞬间、那些不可思议的巧合——都让你觉得这不是偶然。但命运之轮问你：如果这是注定，那你现在为什么还在问「本质是什么」？\n\n【心理层面】你怕「不是命」。你怕这段关系只是一场普通的相遇，怕它经不起「注定」两个字。所以你拼命找证据，找那些「一定是天意」的细节。你问「这段关系的本质是什么」，其实你真正想问的是：「它是命吗？它扛得起我的期待吗？」\n\n【根源层面】你从小就被「缘分」的故事养大。你相信这世上一定有个人是专门为你准备的。所以当这个人出现的时候，你不敢松手，因为怕松了就再也没了。但你不知道，真正的缘分不是「唯一」，是「就是」。

【走向与影响】你怕的是「輪转下去就没了」。命運之輪正位提醒你：你真正怕的，可能是无常。心理层面的突破，是接纳——阻碍往往是「我们不接受关系有低谷」；輪会转，但你们可以一起转。`,
  spiritLayer: `宇宙在轮子上看着你。它想告诉你：命不是「注定」，是「来了」。你接不接，是你的选择。轮子会继续转，但你会不会掉下来，看你敢不敢站稳。\n\n核心启示：你怕的不是不是命，你怕是，却发现不过如此。

就走向而言，两人的气机还绕在「周期」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「信輪」的小事：当你焦慮关系在变，停下来说一句（对自己或对方）：「我们还在同一个輪上。」检查你的「行囊」：命運之輪问你——你怕的，是掉下去还是对方先跳車？`,
  masterSummary: `走向的纽子在「周期」——真正的注定不是轮子带你到哪，是你到哪之后，还想留下。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是对輪转的抗拒。命運之輪说：一起待在輪上，不因一時的下就跳車。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_10', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（命運之輪逆位）想对你说：走向被「輪卡住了或逆转」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 关系陷入重复的爭吵、同样的課题一再出现、或你们感觉「怎麼努力都在原地」。命運之輪逆位说：最大的阻碍，是「周期未完成」——不是没有爱，是旧的模式、旧的伤还没被消化，輪就转不动。 轮子卡住了。 影响走向不靠喊话，靠落地。今天完成「辨識重复」，再谈别的。`,
  psychologyLayer: `【关系现状】你们的关系卡在某个地方——可能是瓶颈期，可能是他犹豫了，可能是你们谁都不想先动。你觉得只要再努力一点，就能回到从前。但命运之轮告诉你：回不去的。轮子只能往前转。\n\n【心理层面】你怕「就这了」。你怕这段关系的上限已经到顶了，再也不会变好了。你问「这段关系的本质是什么」，其实你真正想问的是：「能不能变回刚认识那样？」\n\n【根源层面】你曾经经历过一次「卡住」的事情。那次你等了很久，等到最后没等来，你告诉自己「下次不这样了」。但这次你又卡住了，你还是选择等。因为你不知道除了等，还能做什么。

【走向与影响】你怕的是「再转也一样」。命運之輪逆位提醒你：你真正怕的，可能是重复。心理层面的突破，是问——阻碍是「外在時机不对」，还是「我们內在的旧課题没解」？`,
  spiritLayer: `宇宙在等你推的不是轮子，是你自己的腿。你站起来了，轮子才会动。它不是死锁，是你一直坐着不敢动。\n\n核心启示：你不是在等轮子动，是在等自己敢动。

这条关系的走势，眼下还拴在「未完成的周期」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「辨識重复」的小事：寫下一句——「我们之间一再发生的模式是_____。」不逼立刻改，只让模式被看见。检查你的「行囊」：命運之輪逆位问你——你卡住的，是对方还是自己的旧伤？`,
  masterSummary: `势头绕在「未完成的周期」上——真正的卡住不是你推不动轮子，是你不敢从轮子上跳下来。 第二问早已点破：你们之间最大的阻碍，往往是輪卡住了。命運之輪逆位说：消化旧課题，輪才会再转。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_11', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（正义正位）想对你说：走向不是「没有道理」那种误会式的死局，而是两人的劲还拧在「没有公平与誠实」上，没一起认、也没一起动。 正义持剑与天平；最大的阻碍，是其中一人或两人没有说真话、没有对等付出、或一方一直委屈求全、一方視为理所当然。正义说：阻碍是「失衡与未说清的真相」——关系需要公平与誠实，否則再爱也会被耗尽。 我坐在这里，手里拿着剑，天平悬在空中。 影响走向不靠喊话，靠落地。今天完成「说一句真话」，再谈别的。`,
  psychologyLayer: `【关系现状】你们的关系里有一杆秤。你一直在称：他回消息快不快，他记不记得纪念日，他是不是偏袒他的家人。你以为你在算账，其实你是在找一个「我值不值得」的答案。\n\n【心理层面】你怕自己「亏了」。你怕付出了这么多，最后什么都没落着。所以你开始记账，记下每一笔你的好、他的坏。但你不知道，记着记着，你忘了自己为什么进来。你问「这段关系的本质是什么」，其实你真正想问的是：「我能不能不亏？」\n\n【根源层面】你从小就被教育「公平」，你也一直在等那个对你公平的人。但没人告诉你，爱不是交易。你越算，越算不清。因为感情里的账，不是加减法，是心算。

【走向与影响】你怕的是「算清楚就没爱了」。正义正位提醒你：你真正怕的，可能是冲突或失去。心理层面的突破，是接纳——阻碍往往是「我们不敢談公平」；当你们愿意把天平拿出来，不指责地談，阻碍会现形。`,
  spiritLayer: `宇宙在等你放下那把秤。你一直称他称自己，称来称去，称的不是关系，是你的不甘。真正的公平，不是他欠你多少，是你敢不敢不再算了。\n\n核心启示：你怕的不是他对不起你，是你怕算了半天，发现自己不值得。

能量没有散，是聚在「公平与真相」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「说一句真话」的小事：选一件你一直没说出口的、关于「我觉得不公平」的事，用不指责的方式说出来。检查你的「行囊」：正义问你——你壓着的，是委屈还是恐惧？`,
  masterSummary: `想动走势，先认「公平与真相」这道结——真正的公平，不是天平两头一样重，是你愿意把天平收起来。 对照第二问：你们之间最大的阻碍，往往是公平与誠实未到位。正义说：真正的爱经得起天平。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_11', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（正义逆位）想对你说：走向被「不公或自欺」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 要麼一方长期犧牲、一方无感；要麼两人都在用「我已经很公平」逃避真正的对談。正义逆位说：最大的阻碍，是「天平歪了却没人承认」——不是没有爱，是爱被不公平或謊言綁架了。 剑歪了，天平斜了。 把力气花在看得见的一步：今天只做「承认」，做完就停。`,
  psychologyLayer: `【关系现状】你们的关系里充满了「双标」。他做的事，你生气；你做的事，你觉得可以原谅。你有一套标准对他，一套标准对自己。但这两套标准，从来不一样。正义逆位问你：你对别人那么狠，对自己这么软，这公平吗？\n\n【心理层面】你怕的不是他错，是你怕承认之后，你也要改。你问「这段关系的本质是什么」，其实你真正想问的是：「能不能只让他改，我不用？」\n\n【根源层面】你从小就是那个「懂事」的孩子。你太会体谅别人了，体谅到忘了体谅自己。所以现在，你在关系里继续体谅他，委屈自己。你觉得这是善良，但正义逆位说：这是你在逃。逃那个「我也该被公平对待」的自己。

【走向与影响】你怕的是「攤开就崩」。正义逆位提醒你：你真正怕的，可能是面对失衡。心理层面的突破，是问——阻碍是「我们不敢談公平」，还是「我们在自欺」？`,
  spiritLayer: `宇宙在等你对你自己公平一次。不是对他狠，是对自己软一点。你允许他晚回消息，也允许自己没回；你允许他忘你生日，也允许自己今天不想理他。\n\n核心启示：你一直说世界不公，其实是你对自己最不公。

这条关系的走势，眼下还拴在「未面对的公平」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「承认」的小事：对自己承认一句——「这段关系里，我觉得不公平的是_____。」不逼对方改，只让自己先看见。检查你的「行囊」：正义逆位问你——你不敢談的，是什么？`,
  masterSummary: `势头绕在「未面对的公平」上——真正的正义不是他该怎么样，是你该不该一直这样。 第二问早已点破：你们之间最大的阻碍，往往是天平歪了却没人承认。正义逆位说：先承认，才能調。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_12', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（倒吊人正位）想对你说：走向不是「没有付出」那种误会式的死局，而是两人的劲还拧在「没有換角度看」上，没一起认、也没一起动。 倒吊人头下脚上；最大的阻碍，是你们一直用同一套逻辑、同一种「谁对谁错」在爭——没有停下来问「若反过来看呢？」「若这是他／她的恐惧呢？」倒吊人说：阻碍是「視角卡死了」；当你们愿意暫時放下「我是对的」，关系才有空间。。 我被吊着，脚在上，头在下，世界在我眼里是倒过来的。 别等对方先示范。今天你先用「換角度」给关系一个可跟的节拍。`,
  psychologyLayer: `【关系现状】你们的关系卡在「等」里——等他改变、等时机成熟、等一个结果。你觉得自己被吊着，动弹不得。但倒吊人问你：如果动不了，能不能先换个角度看看？\n\n【心理层面】你怕的不是等，是等了之后发现等不到。你问「这段关系的本质是什么」，其实你真正想问的是：「我还要等多久？」但倒吊人说：你问错了。你应该问的是：「在等的时候，我能不能先换个姿势？」\n\n【根源层面】你从小就被教「坚持到底」。所以你不肯放手，你觉得放了就输了。但你不知道，有些时候，放下来不是输，是换一条腿站着。

【走向与影响】你怕的是「換角度就等于认错」。倒吊人正位提醒你：你真正怕的，可能是输。心理层面的突破，是接纳——阻碍往往是「我们不肯換視角」；暫停不是认输，是为了看得更清楚。`,
  spiritLayer: `宇宙在教你「暂停的智慧」。你看不见未来，是因为你现在这个角度，只看见过去。等有一天你换过来，你会发现，那些你以为白等的日子，都是风景。\n\n核心启示：你不是被吊着，你是不敢下来。

若问势头卡在哪，多半是「視角」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「換角度」的小事：选一件你们常爭的事，试着用对方的立场想一遍——「若我是他／她，我可能会觉得_____。」不逼自己认错，只让視角多一个。检查你的「行囊」：倒吊人问你——你卡住的，是对错还是自尊？`,
  masterSummary: `「視角」松一寸，走向就变一寸——真正的自由不是下来，是在吊着的时候还能换腿。 第二问那句仍管用：你们之间最大的阻碍，往往是視角卡死了。倒吊人说：換个角度看，阻碍有時就松了。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_12', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（倒吊人逆位）想对你说：走向被「该停没停或该放没放」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 要麼一直犧牲、等待、「再忍一下」，没有为自己设界線；要麼不肯換角度、死守「我是对的」，关系卡在僵局。倒吊人逆位说：最大的阻碍，是「停頓的错用或弃用」——不是没有爱，是你们没有用「暫停」換取清明。 你还在挣扎。 你若真想推动走势，就从「停或动」开始——轻，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里充满了「无效努力」。你试过沟通、试过忍让、试过放弃、试过挽回——但什么都没变。你觉得是自己做得还不够，但倒吊人问你：你有没有想过，问题可能不是你不努力，是你努力的方向本来就是反的。\n\n【心理层面】你怕停下来。你怕一停，就真的结束了。所以你宁愿做着无用功，也不敢承认：也许，什么都不做才是对的。你问「这段关系的本质是什么」，其实你真正想问的是：「我能不能不努力，它还能好？」\n\n【根源层面】你从小就被教「只要努力就有回报」。所以你把这句话带进了感情。但你忘了，感情不是种地，你浇水施肥，不一定结果。它可能只是想让你学会等。

【走向与影响】你怕的是「一动就全盤皆输」。倒吊人逆位提醒你：你真正怕的，可能是改变。心理层面的突破，是问——阻碍是「我们不肯停」，还是「我们停太久了」？`,
  spiritLayer: `宇宙在等你把绳子解开。它不是绑着你的，是你自己缠上去的。你一直在翻，一直翻，翻到晕了，也没发现，绳子早就松了。\n\n核心启示：你不是在解决问题，你是在解决「不想面对」的自己。

若问势头卡在哪，多半是「未換的視角」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「停或动」的小事：若你一直在忍，设一个界線；若你一直在爭，试着換对方角度想一次。检查你的「行囊」：倒吊人逆位问你——你停的，是智慧还是逃避？`,
  masterSummary: `「未換的視角」松一寸，走向就变一寸——真正的暂停不是等别人动，是等自己停下来。 第二问那句仍管用：你们之间最大的阻碍，往往是该停没停或该換没換。倒吊人逆位说：停頓是为了清明。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_13', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（死神正位）想对你说：走向不是「没有未来」那种误会式的死局，而是两人的劲还拧在「没有结束旧的」上，没一起认、也没一起动。 死神騎馬前来，终结与重生一體；最大的阻碍，是你们其中一人或两人紧抓着「过去的模式、旧的承诺、曾经的伤害」不放——不愿让某种关系形式死掉，新的就长不出来。死神说：阻碍是「该死未死」；关系需要某种结束，才能有新的开始。 我是黎明前最黑的那段夜。 你能拧动的开关往往在细节：今天把「放手一样」做实，比分析十句有用。`,
  psychologyLayer: `【关系现状】你们的关系正在「结束」。可能已经分了，可能正在分，可能名存实亡。你一直在想办法救，但死神告诉你：有些东西，不救才能活。你让尸体躺着，新人才进得来。\n\n【心理层面】你怕的不是结束，是结束之后，就什么都没了。你怕空的那块地方，再也填不上。你问「这段关系的本质是什么」，其实你真正想问的是：「能不能别让它走？」\n\n【根源层面】你曾经失去过。那次你疼了很久，所以你发誓再也不想体验那种空。但你不知道，你现在抓着不放的，不是爱，是那个害怕再空的自己。

【走向与影响】你怕的是「一放就没了」。死神正位提醒你：你真正怕的，可能是失去。心理层面的突破，是接纳——阻碍往往是「我们不敢结束」；结束不是失败，是为了重生。`,
  spiritLayer: `宇宙在等你埋人。你不埋，新土就盖不上。旧的不死，新的不来。你不是在失去，你是在腾地方。\n\n核心启示：你怕的不是失去他，是失去他之后，终于要面对自己。

能量没有散，是聚在「结束」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「放手一样」的小事：选一样你紧抓的——旧的期待、旧的伤害、旧的相處方式——在心里对它说「我愿意放手」。不逼立刻做到，只让意愿发生。检查你的「行囊」：死神问你——你抓着的，是什么？`,
  masterSummary: `想动走势，先认「结束」这道结——真正的死亡不是结束，是你终于敢活着了。 对照第二问：你们之间最大的阻碍，往往是该死未死。死神说：让该死的死，新的才会生。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_13', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（死神逆位）想对你说：走向被「不肯结束或卡在过渡」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 要麼关系早已该斷却拖着、要麼该转型却不敢转，卡在「既回不去又走不出去」。死神逆位说：最大的阻碍，是「结束未完成」——不是没有爱，是旧的没被好好哀悼或放手，新的就卡在门口。 你死死抓着那具尸体不放，以为那是你的命。 今天用「哀悼或放手」替关系试温：你动了，场的流向才会跟着变。`,
  psychologyLayer: `【关系现状】你们的关系已经「死了」。但你还在演——演恩爱、演没事、演「我们还行」。你骗他，也骗自己。死神逆位问你：你演给谁看？\n\n【心理层面】你怕的不是关系没了，是怕没了之后，别人怎么看你。你怕别人说「她怎么又被甩了」「她怎么还不结婚」。你问「这段关系的本质是什么」，其实你真正想问的是：「我怎么跟别人交代？」\n\n【根源层面】你从小就被教「要体面」。所以你把体面看得比真相重。你可以不幸福，但不能不体面。但你忘了，体面是给外人看的，疼是给自己受的。

【走向与影响】你怕的是「一结束就什么都没了」。死神逆位提醒你：你真正怕的，可能是空。心理层面的突破，是问——阻碍是「我们不敢结束」，还是「我们没有好好结束」？`,
  spiritLayer: `宇宙在等你把戏服脱了。演一场戏，没人给你颁奖。真实的你，比任何角色都好看。\n\n核心启示：你怕的不是结束，是结束之后，不得不面对那个早就不在的你。

若问势头卡在哪，多半是「未完成的结束」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「哀悼或放手」的小事：对某个「已经过去」的部分，在心里做一个小小的告别。检查你的「行囊」：死神逆位问你——你拖着的，是什么？`,
  masterSummary: `「未完成的结束」松一寸，走向就变一寸——真正的结束不是他走，是你终于敢不演了。 第二问那句仍管用：你们之间最大的阻碍，往往是结束未完成。死神逆位说：好好结束，才能好好开始。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_14', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（节制正位）想对你说：走向不是「没有爱」那种误会式的死局，而是两人的劲还拧在「没有調和」上，没一起认、也没一起动。 节制中天使調和水与火；最大的阻碍，是你们的节奏、需求、表达方式没有被調和——一个要热、一个要冷；一个要快、一个要慢；或情绪与理性、付出与接受没有平衡。节制说：阻碍是「两端未調和」；当你们愿意各让一步、找到中间的溫度，阻碍就松动。 我站在两个杯子之间，把水从一个倒向另一个。 走向听行动。今天只兑现「調和」——让对方看见你在动，而不是在讲。`,
  psychologyLayer: `【关系现状】你们的关系在「磨合」中。你觉得要忍，要退，要改。但节制告诉你：真正的磨合不是磨掉自己，是两个人混在一起，生出一种新的味道。你没变少，他也没变多，你们变成了「你们」。\n\n【心理层面】你怕「失去自己」。你怕为了关系，把自己改得面目全非。你问「这段关系的本质是什么」，其实你真正想问的是：「我还能是我吗？」\n\n【根源层面】你曾经在一段关系里被磨得太狠。那次之后，你发誓再也不妥协。但你不知道，不妥协和妥协之间，有一条路叫「调和」。像调酒一样，两种酒混在一起，不是酒没了，是有了新酒。

【走向与影响】你怕的是「一让就永远输」。节制正位提醒你：你真正怕的，可能是失衡。心理层面的突破，是接纳——阻碍往往是「我们不肯調和」；調和不是认输，是找到两人都能活的节奏。`,
  spiritLayer: `宇宙在教你「平衡」。不是五五开，是动态的、流动的、今天他多一点，明天你多一点。水在杯子里流，流着流着，就忘了哪滴是他的，哪滴是你的。\n\n核心启示：你怕的不是失去自己，是怕自己不够好，所以不敢和别人混在一起。

这条关系的走势，眼下还拴在「平衡」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「調和」的小事：选一件你们常不同步的事，提出一个「中间方案」——不逼对方全让，只让一步。检查你的「行囊」：节制问你——你堅持的，是原則还是习惯？`,
  masterSummary: `势头绕在「平衡」上——真正的调和不是谁改了，是你们混出了只有你们才有的味道。 第二问早已点破：你们之间最大的阻碍，往往是两端未調和。节制说：調和不是认输，是找到共同的节奏。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_14', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（节制逆位）想对你说：走向被「失衡或无法調和」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 要麼一方一直退、一方一直进；要麼情绪失控、沟通失焦，找不到中间地带。节制逆位说：最大的阻碍，是「調和失败」——不是没有爱，是爱在極端里燒尽或凍僵。 水流了一地。 你要影响走向，今天就卡这一格：把「找中间」做到底，小不要紧，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里充满了「失衡」。要么你太主动，要么他太被动；要么你给太多，要么他收太少。你觉得累，但不知道怎么让它平衡。节制逆位问你：你有没有想过，你可能不是要平衡，是要赢？\n\n【心理层面】你怕的是「掌控不了」。你拼命调，拼命试，拼命想让关系变成你想要的样子。但你越调，它越乱。你问「这段关系的本质是什么」，其实你真正想问的是：「为什么我控制不了它？」\n\n【根源层面】你从小就被教「要掌握主动」。你把这句话带进了爱情，以为主动就能有好结果。但你不知道，有些东西，不是控出来的，是流出来的。你一直用手挡，水当然溅。

【走向与影响】你怕的是「再让就没了」。节制逆位提醒你：你真正怕的，可能是被吃定。心理层面的突破，是问——阻碍是「我们不会調和」，还是「我们不愿調和」？`,
  spiritLayer: `宇宙在等你收手。别调了，让水自己流。它会找到那条路的。你站在旁边看，别上手。你把手插进去，它就乱。\n\n核心启示：你怕的不是失衡，是你怕一松手，他就没了。

能量没有散，是聚在「未平衡」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「找中间」的小事：选一件你们常对立的事，寫下一个「我退一点、你退一点」的具體做法。检查你的「行囊」：节制逆位问你——你卡住的，是原則还是恐惧？`,
  masterSummary: `想动走势，先认「未平衡」这道结——真正的平衡不是你一直扶着，是放手之后，它自己站稳。 对照第二问：你们之间最大的阻碍，往往是調和失败。节制逆位说：找到中间，关系才能流。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_15', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（惡魔正位）想对你说：走向不是「没有吸引力」那种误会式的死局，而是两人的劲还拧在「被綁住了」上，没一起认、也没一起动。 惡魔的锁鏈松垮，却没人脫下；最大的阻碍，是你们其中一人或两人被「執念、癮、依賴、占有慾、或有毒的互动模式」綁住——明知不对却離不开、或用「因为爱」合理化控制与痛苦。惡魔说：阻碍是「自愿的锁鏈」；看见鏈子，才能选择脫不脫。 你被绑着。 你要影响走向，今天就卡这一格：把「看见鏈子」做到底，小不要紧，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里有「瘾」。可能是离不开的人，可能是戒不掉的争吵，可能是明知道不好但还要继续的模式。你以为是因为爱，但恶魔告诉你：爱不是这样的。爱是自由，不是锁链。\n\n【心理层面】你怕的不是关系不好，是怕关系没了之后，你什么都不是。你把他当成了你的坐标，他走了，你就不知道自己站在哪。你问「这段关系的本质是什么」，其实你真正想问的是：「离了他，我还能活吗？」\n\n【根源层面】你曾经被抛弃过。那次之后，你就再也不敢松手了。你把每一段关系都当成了浮板，以为抓着就能活。但你不知道，浮板会沉，你会游泳。你一直不敢游，是因为你忘了自己会水。

【走向与影响】你怕的是「脫下鏈子就没了」。惡魔正位提醒你：你真正怕的，可能是没有对方。心理层面的突破，是接纳——阻碍往往是「我们不敢承认被綁」；承认是解綁的第一步。`,
  spiritLayer: `宇宙在等你发现那链子是假的。它不是铁，是你画的。你解开它，走出去，外面不是深渊，是阳光。你被关太久了，忘了光什么样。\n\n核心启示：你怕的不是失去他，是失去他之后，终于要面对那个一直被你关着的自己。

能量没有散，是聚在「執念与癮」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「看见鏈子」的小事：寫下一句——「这段关系里，我最離不开的、或最让我痛苦的是_____。」不逼立刻脫，只让鏈子被看见。检查你的「行囊」：惡魔问你——你綁的，是爱还是恐惧？`,
  masterSummary: `想动走势，先认「執念与癮」这道结——真正的恶魔不是他，是你不敢走的那扇门。 对照第二问：你们之间最大的阻碍，往往是自愿的锁鏈。惡魔说：看见鏈子，才能选择脫不脫。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_15', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（惡魔逆位）想对你说：走向被「正在脫鏈或卡在脫与不脫之间」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 要麼你们开始看见執念、依賴、有毒模式，正在掙扎要不要放手；要麼一方想脫、一方还在綁。惡魔逆位说：最大的阻碍，是「脫鏈的未完成」——不是没有爱，是爱被旧的锁鏈纏住了，需要先解开才能重新选择。 链子松了。 走向听行动。今天只兑现「松一格」——让对方看见你在动，而不是在讲。`,
  psychologyLayer: `【关系现状】你们的关系已经「松动」了。可能是你开始看开了，可能是你准备放下了。你心里知道，快结束了。但你还是有点犹豫，不知道这一步迈出去之后，外面是什么。\n\n【心理层面】你怕的是「自由」。你一直以为你要的是自由，但自由真的来了，你发现自己不知道拿它怎么办。你问「这段关系的本质是什么」，其实你真正想问的是：「自由之后，我该去哪？」\n\n【根源层面】你从来没见过自由的样子。你一直被管，被教，被安排。突然没人管你了，你慌。但恶魔逆位说：你慌不是因为自由不好，是你不知道怎么做自己。

【走向与影响】你怕的是「一脫就真的没了」。惡魔逆位提醒你：你真正怕的，可能是自由。心理层面的突破，是问——阻碍是「我们不敢脫」，还是「我们不知道怎麼脫」？`,
  spiritLayer: `宇宙在等你迈出第一步。不用跑，就走一步。走出去，外面的空气可能有点凉，但你能呼吸了。\n\n核心启示：你怕的不是离开他，是你怕离开之后，发现自己根本不知道要去哪。

这条关系的走势，眼下还拴在「脫鏈中」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「松一格」的小事：选一个小執念或小习惯（例如一定要对方先訊息），今天松一次。检查你的「行囊」：惡魔逆位问你——你脫的，是鏈子还是爱？`,
  masterSummary: `势头绕在「脫鏈中」上——真正的自由不是你走出去了，是你走出去之后，还能回头看那个地方笑。 第二问早已点破：你们之间最大的阻碍，往往是脫鏈未完成。惡魔逆位说：解开一点，就多一点选择。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_16', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（高塔正位）想对你说：走向不是「没有真相」那种误会式的死局，而是两人的劲还拧在「假象还没被劈开」上，没一起认、也没一起动。 高塔被雷擊中，一切崩塌；最大的阻碍，是你们其中一人或两人一直活在「自以为的关系」里——没说清的期待、没面对的謊言、没承认的裂痕，总有一天会被一道雷劈开。高塔说：阻碍是「该塌未塌的假象」；与其等雷来劈，不如自己拆。 闪电击中高塔，不是雷神愤怒，是屋顶太厚，光进不来。 今天用「面对一道裂痕」替关系试温：你动了，场的流向才会跟着变。`,
  psychologyLayer: `【关系现状】你们的关系正在「崩塌」。可能是他变了，可能是秘密揭穿了，可能是你突然醒了。你觉得世界末日，但塔告诉你：末日之后，才是新世界。你不塌，怎么重建？\n\n【心理层面】你怕的不是塌，是你怕塌了之后，发现自己一直住在危房里。你问「这段关系的本质是什么」，其实你真正想问的是：「能不能让它别塌？」\n\n【根源层面】你太会盖房了。从小就在盖，盖给别人看。盖了这么多年，你忘了问自己：我盖的这间，到底是谁的？现在它塌了，你疼，但也终于可以问这个问题了。

【走向与影响】你怕的是「一拆就全没了」。高塔正位提醒你：你真正怕的，可能是真相。心理层面的突破，是接纳——阻碍往往是「我们不敢拆假象」；拆掉不是毀滅，是为了重建。`,
  spiritLayer: `宇宙在告诉你：有些东西必须崩塌，真相才能出现。不要害怕倒塌，害怕的是继续住在虚假的塔里。\n\n核心启示：你不是不敢面对真相，你是舍不得那个假装有屋顶的地方。

若问势头卡在哪，多半是「假象」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「面对一道裂痕」的小事：选一件你们一直假装没看见的事，用一句话说出来。不逼对方认，只让裂痕被看见。检查你的「行囊」：高塔问你——你护着的，是关系还是假象？`,
  masterSummary: `「假象」松一寸，走向就变一寸——真正的崩塌不是失去屋顶，是你终于看见，原来一直住的是别人的房子。 第二问那句仍管用：你们之间最大的阻碍，往往是该塌未塌的假象。高塔说：先拆的先重建。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_16', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（高塔逆位）想对你说：走向被「崩塌中或拒绝崩塌」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 要麼关系正在经歷剧变、信任被震裂；要麼你们死撐着不让假象塌，用「再忍一下」延后必然的崩塌。高塔逆位说：最大的阻碍，是「该面对的未面对」——不是没有爱，是爱建在会塌的基礎上。 你躲过了这一劫。 你能拧动的开关往往在细节：今天把「承认裂痕」做实，比分析十句有用。`,
  psychologyLayer: `【关系现状】你们的关系还在「撑着」。表面上还行，但你知道，它已经裂了。裂缝从地基往上爬，你没看见，还是不想看见？塔逆位问你：你还能撑多久？\n\n【心理层面】你怕的是「现在塌」。你还没准备好，还没找到下家，还没攒够勇气。你问「这段关系的本质是什么」，其实你真正想问的是：「能不能再给我一点时间？」\n\n【根源层面】你一直是个「晚塌」的人。别人塌的时候，你总能躲过。但你不知道，躲过的那些，最后都在你心里塌了。你现在撑着的外面，里面早就碎了。

【走向与影响】你怕的是「一塌就再也回不去」。高塔逆位提醒你：你真正怕的，可能是失去。心理层面的突破，是问——阻碍是「我们在逃避崩塌」，还是「我们不知道崩塌后怎麼活」？`,
  spiritLayer: `宇宙在等你主动拆。不拆，它自己也会塌。自己拆，还能捡几块能用的砖；等它塌，就只能站在废墟里哭。\n\n核心启示：你怕的不是塔塌，是你怕塌了之后，发现自己根本不会盖新房子。

这条关系的走势，眼下还拴在「未完成的崩塌」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「承认裂痕」的小事：对自己承认一句——「我们之间已经裂开的是_____。」不逼立刻處理，只让裂痕被承认。检查你的「行囊」：高塔逆位问你——你撐着的，是什么？`,
  masterSummary: `势头绕在「未完成的崩塌」上——真正的倒塌不是你躲过的那次，是你终于敢看着它倒。 第二问早已点破：你们之间最大的阻碍，往往是该塌未塌。高塔逆位说：塌了才能重建。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_17', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（星星正位）想对你说：走向不是「没有希望」那种误会式的死局，而是两人的劲还拧在「没有相信希望」上，没一起认、也没一起动。 星星在夜空中；最大的阻碍，是你们其中一人或两人失去了对关系的信任、对未来的相信——伤过之后不敢再信、或一直用「反正不会好」堵住可能。星星说：阻碍是「希望被浇熄」；当你们愿意再次許愿、再次相信一点点，阻碍就从「不可能」变成「也許」。 我跪在水边，把水倒进河里，也倒在岸上。 你若真想推动走势，就从「許一个愿」开始——轻，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里有「希望」。可能是他给你的，可能是你自己给自己的。不管怎样，你还愿意看，还愿意等，还愿意相信。星星告诉你：这就够了。\n\n【心理层面】你怕的是「希望落空」。你不敢再信，因为信过太多次，信完之后又失望。你问「这段关系的本质是什么」，其实你真正想问的是：「这一次，能不能不一样？」\n\n【根源层面】你曾经在黑夜里走得太久。久到忘了星星什么样。现在你又看见了，却不敢认。你怕那是假的，怕那是远处别人的灯。但星星说：你看我的时候，我就亮了。

【走向与影响】你怕的是「再信会再伤」。星星正位提醒你：你真正怕的，可能是脆弱。心理层面的突破，是接纳——阻碍往往是「我们不敢再希望」；許愿不是天真，是勇气。`,
  spiritLayer: `宇宙在等你抬起头。低头看不见我，抬头就能。你不用看很远，就看一步远的地方，那颗最亮的，就是我。\n\n核心启示：你怕的不是没希望，是你怕有了希望之后，又要再失望。

若问势头卡在哪，多半是「希望」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「許一个愿」的小事：对这段关系許一个小小的愿望——不逼成真，只让「我还愿意希望」发生。检查你的「行囊」：星星问你——你熄的，是希望还是自我保护？`,
  masterSummary: `「希望」松一寸，走向就变一寸——真正的希望不是等来的，是你抬头那一刻，它就亮了。 第二问那句仍管用：你们之间最大的阻碍，往往是希望被浇熄。星星说：在黑夜里，先信一顆星。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_17', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（星星逆位）想对你说：走向被「希望破滅或不敢希望」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 要麼曾经相信的被打碎、要麼从头就不敢信，关系卡在「不可能会好」的绝望或麻木里。星星逆位说：最大的阻碍，是「不信」——不是没有爱，是爱被失望蓋住了，需要一点光才能再被看见。 水停了。 别等对方先示范。今天你先用「点一顆星」给关系一个可跟的节拍。`,
  psychologyLayer: `【关系现状】你们的关系里已经没有「希望」了。你不再期待他回消息，不再期待他改变，不再期待明天会更好。你以为这是清醒，但星星逆位说：这是你在等死。\n\n【心理层面】你怕的是「再信一次还是会碎」。你把自己裹起来，告诉自己「算了」。但你算了的人，也把自己算了。你问「这段关系的本质是什么」，其实你真正想问的是：「还有必要信吗？」\n\n【根源层面】你信过太多次了。信父母、信朋友、信爱情，然后被辜负了太多次。你的心已经磨出茧子，再好的东西也进不去。但星星逆位说：茧子也是肉，剥开，还能疼。

【走向与影响】你怕的是「再許愿会再碎」。星星逆位提醒你：你真正怕的，可能是再次受伤。心理层面的突破，是问——阻碍是「我们不敢希望」，还是「我们没有为希望做一点事」？`,
  spiritLayer: `宇宙在等你做一件「没用」的事。比如给花浇水，比如对镜子笑，比如再信一次。信不是为了结果，是为了让你自己还活着。\n\n核心启示：你怕的不是信，是信完之后，还要面对自己其实一直醒着。

若问势头卡在哪，多半是「未点亮的希望」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「点一顆星」的小事：做一件很小的事，让「可能」发生——一句感谢、一次主动、或一个小愿望。检查你的「行囊」：星星逆位问你——你熄的，是希望还是怕失望？`,
  masterSummary: `「未点亮的希望」松一寸，走向就变一寸——真正的失望不是没星星，是你一直低头，骗自己说天黑了。 第二问那句仍管用：你们之间最大的阻碍，往往是不敢再希望。星星逆位说：一点光就够照路。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_18', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（月亮正位）想对你说：走向不是「没有爱」那种误会式的死局，而是两人的劲还拧在「没有照见陰影」上，没一起认、也没一起动。 月亮下有小徑、有犬吠、有看不清的暗處；最大的阻碍，是你们其中一人或两人没有面对「心里的恐惧、过去的伤、没说出口的怀疑」——它们在暗處影响关系，却没被拿出来照见。月亮说：阻碍是「未照见的陰影」；当你们愿意点燈照一照，阻碍就从「不知道是什么」变成「可以面对的」。 你看不清。 把力气花在看得见的一步：今天只做「照陰影」，做完就停。`,
  psychologyLayer: `【关系现状】你们的关系里全是「不确定」。你不知道他怎么想，你不知道要不要继续，你不知道以后会怎样。你慌了，但月亮告诉你：慌是对的。不慌，你就不会醒。\n\n【心理层面】你怕的是「未知」。你把所有的力气都用在找「确定」上，找他爱不爱的证据，找关系走向的线索。但你不知道，有些路，就是要摸黑走的。你问「这段关系的本质是什么」，其实你真正想问的是：「能不能给我一个确切的答案？」\n\n【根源层面】你从小就怕黑。怕黑的人，会把所有的灯都打开，直到把自己累死。但你不知道，有些东西，只有在黑里才看得见——比如月亮，比如星星，比如你自己眼里的光。

【走向与影响】你怕的是「照见了就会崩」。月亮正位提醒你：你真正怕的，可能是真相。心理层面的突破，是接纳——阻碍往往是「我们不敢照陰影」；照见不是毀滅，是为了不再被暗處控制。`,
  spiritLayer: `宇宙在等你摸黑走一步。你看不清没关系，走一步。走一步，前面就会亮一点。你一直站着，就永远在雾里。\n\n核心启示：你怕的不是看不清，是你怕看清之后，发现根本没有路。

能量没有散，是聚在「陰影」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「照陰影」的小事：寫下一句——「这段关系里，我最怕被看见的是_____。」不逼解决，只让陰影被自己看见。检查你的「行囊」：月亮问你——你藏着的，是什么？`,
  masterSummary: `想动走势，先认「陰影」这道结——真正的月亮不是照亮你的路，是让你在看不清楚的时候，还敢走。 对照第二问：你们之间最大的阻碍，往往是未照见的陰影。月亮说：点燈照一照，路就清晰一点。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_18', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（月亮逆位）想对你说：走向被「幻觉或逃避陰影」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 要麼被不实的怀疑、猜忌、幻想綁架；要麼拒绝看暗處、用「没事了」壓住该面对的。月亮逆位说：最大的阻碍，是「陰影的错用或弃用」——不是没有爱，是爱被幻觉或逃避綁架了。 你开始看清了。 影响走向不靠喊话，靠落地。今天完成「辨識幻觉」，再谈别的。`,
  psychologyLayer: `【关系现状】你们的关系里那些迷雾正在散开。可能是你想通了，可能是他摊牌了，可能是真相大白了。你终于知道怎么回事了，但你知道之后，反而不知道怎么办。\n\n【心理层面】你怕的是「真相」。你一直说想知道，但真的知道了，你发现自己并不想承受。你问「这段关系的本质是什么」，现在你知道了，却希望不知道。\n\n【根源层面】你一直用「不知道」保护自己。不知道，就可以不用选；不知道，就可以不用面对。但现在知道了，你没地方躲了。月亮逆位说：躲不了的时候，你才开始活。

【走向与影响】你怕的是「面对陰影就会失去」。月亮逆位提醒你：你真正怕的，可能是真实。心理层面的突破，是问——阻碍是「我们在幻想」，还是「我们不敢照见」？`,
  spiritLayer: `宇宙在等你做一个决定。不是选A还是B，是决定要不要继续在真相里活着。你可以再躲，但你知道，再躲，就是对自己撒谎。\n\n核心启示：你怕的不是真相，是你怕知道真相之后，再也不能装不知道。

能量没有散，是聚在「未面对的陰影」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「辨識幻觉」的小事：选一个你常有的「他／她一定_____」的念头，问自己：这是事实还是恐惧？检查你的「行囊」：月亮逆位问你——你信的，是事实还是幻觉？`,
  masterSummary: `想动走势，先认「未面对的陰影」这道结——真正的看清不是眼睛睁开了，是你知道疼，但还睁着。 对照第二问：你们之间最大的阻碍，往往是幻觉或未照见的陰影。月亮逆位说：照见幻觉，才能看见真实。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_19', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（太陽正位）想对你说：走向不是「没有光明」那种误会式的死局，而是两人的劲还拧在「没有让光进来」上，没一起认、也没一起动。 太陽高照；最大的阻碍，是你们其中一人或两人用「习惯、恐惧、旧伤」擋住了光——不敢慶祝、不敢坦誠、不敢单纯地享受彼此，总在等「再安全一点再说」。太陽说：阻碍是「光被擋住了」；当你们愿意拉开窗簾，让一点真实的喜悅与坦誠进来，阻碍就从「不可能快樂」变成「可以试试」。 我晒着你，不是因为你做对了什么，是因为我本来就会发光。 影响走向不靠喊话，靠落地。今天完成「让光进来」，再谈别的。`,
  psychologyLayer: `【关系现状】你们的关系里有「光」。可能是快乐，可能是轻松，可能是那种不用说话就懂的感觉。你一直觉得这是运气，但太阳告诉你：这不是运气，是你们本来就会亮。\n\n【心理层面】你怕的是「太亮了会灭」。你习惯了阴天，突然天晴，你不适应。你总在问「还能多久」「会不会突然下雨」。你问「这段关系的本质是什么」，其实你真正想问的是：「我配不配一直这么开心？」\n\n【根源层面】你从小就被教「乐极生悲」「好景不长」。你把这两句话刻在骨头里，所以一快乐就慌。你拼命找不快乐的地方，用来自我安慰。但太阳说：你配得上晴天，你不必为天亮道歉。

【走向与影响】你怕的是「一开心就会失去」。太陽正位提醒你：你真正怕的，可能是脆弱。心理层面的突破，是接纳——阻碍往往是「我们不敢让光进来」；喜悅不是幼稚，是勇气。`,
  spiritLayer: `宇宙在教你「接受」。接受自己值得被爱，接受关系可以不苦，接受今天就是今天，不用管明天。晒着，就是答案。\n\n核心启示：你怕的不是太阳下山，是你怕自己从来没在太阳里待过。

若问势头卡在哪，多半是「光」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「让光进来」的小事：做一件纯粹「开心」的事——不談问题、不翻旧帳，只让十分鐘的喜悅发生。检查你的「行囊」：太陽问你——你擋住的，是光还是怕失望？`,
  masterSummary: `「光」松一寸，走向就变一寸——真正的阳光不是他给的，是你敢站在光里的那一刻，自己就开始亮了。 第二问那句仍管用：你们之间最大的阻碍，往往是光被擋住了。太陽说：让光进来，陰影就会退一点。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_19', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（太陽逆位）想对你说：走向被「光被遮住或不敢见光」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 要麼关系卡在灰撲撲的狀态、要麼你们不敢把关系拿到陽光下——不敢公开、不敢慶祝、不敢坦誠。太陽逆位说：最大的阻碍，是「喜悅与坦誠未进来」——不是没有爱，是爱躲在陰影里，需要一点光才能被看见。 云遮住了我。 把力气花在看得见的一步：今天只做「拉开簾」，做完就停。`,
  psychologyLayer: `【关系现状】你们的关系里有一段「阴天」。可能是他忙了，可能是你们吵架了，可能是激情过了。你以为是太阳没了，但太阳逆位告诉你：它还在，你只是没站在它的方向。\n\n【心理层面】你怕的是「阴天会一直阴」。你习惯了把暂时当永远，把情绪当真相。你问「这段关系的本质是什么」，其实你真正想问的是：「是不是永远都这样了？」\n\n【根源层面】你曾经经历过一段漫长的阴天。那次之后，你就再也不相信晴了。你把每一片云都当成末日，把每一次降温都当成终局。但太阳逆位说：云会散，夜会过，你会晒到太阳的。

【走向与影响】你怕的是「见光就死」。太陽逆位提醒你：你真正怕的，可能是被看见。心理层面的突破，是问——阻碍是「我们不敢见光」，还是「我们没有创造见光的机会」？`,
  spiritLayer: `宇宙在等你挪一步。阴天不是太阳的错，是你站的位置。你挪一下，哪怕挪半步，就能晒到。你不挪，就只能一直在阴影里。\n\n核心启示：你怕的不是阴天，是你怕晴了之后，还要再阴。

就走向而言，两人的气机还绕在「未进来的光」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「拉开簾」的小事：选一件你一直藏着的（感受、愿望、或关系狀态），对一个人说出来。检查你的「行囊」：太陽逆位问你——你遮住的，是什么？`,
  masterSummary: `走向的纽子在「未进来的光」——真正的太阳不是永远不落，是你知道它落了还会升。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是光被遮住。太陽逆位说：拉开一点簾，光就进来一点。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_20', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（審判正位）想对你说：走向不是「没有召喚」那种误会式的死局，而是两人的劲还拧在「没有回應召喚」上，没一起认、也没一起动。 審判的号角响起；最大的阻碍，是你们其中一人或两人没有「醒来」——没有真正面对「这段关系对我的意义」「我是否愿意为它負责」「我们要一起往哪里去」。審判说：阻碍是「未回應的召喚」；当你们愿意认真回答心里的召喚，阻碍就从「卡住」变成「可以决定」。 号角响了。 你若真想推动走势，就从「回答召喚」开始——轻，但要真。`,
  psychologyLayer: `【关系现状】你们的关系到了一个「该醒的时候」。可能是一直装睡的感情，可能是一直逃避的问题，可能是你一直在等的那个「信号」。审判告诉你：信号早就响了，你没听见，是你塞着耳朵。\n\n【心理层面】你怕的是「醒来之后怎么办」。睡着的时候，你可以做任何梦；醒过来，就只剩现实。你问「这段关系的本质是什么」，其实你真正想问的是：「我能不能再睡一会儿？」\n\n【根源层面】你太会装睡了。从小就会。家里吵架，你装睡；朋友疏远，你装睡；感情死了，你还装睡。你学会了用「不知道」保护自己，但你忘了，不知道的人，也会被别人走过。

【走向与影响】你怕的是「一回答就没退路」。審判正位提醒你：你真正怕的，可能是承诺。心理层面的突破，是接纳——阻碍往往是「我们不敢回應召喚」；回答不是綁死，是为了活过来。`,
  spiritLayer: `宇宙在等你睁开眼睛。不睁，就永远在梦里；睁了，疼一下，然后就能看见。你怕疼，但更怕一辈子都在梦里。\n\n核心启示：你怕的不是审判，是你怕审判之后，不得不活成真的自己。

就走向而言，两人的气机还绕在「召喚」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「回答召喚」的小事：问自己——「这段关系对我来说，我真正要的是_____？」寫下来，不逼立刻行动。检查你的「行囊」：審判问你——你没回答的，是什么？`,
  masterSummary: `走向的纽子在「召喚」——真正的醒来不是听见号角，是你愿意睁开眼睛，哪怕光刺眼。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是未回應的召喚。審判说：号角响了，回答才能前进。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_20', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（審判逆位）想对你说：走向被「不敢回答或答错了」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 要麼一直逃避「这段关系到底要不要」、要麼用错誤的答案騙自己（例如「我留下来是因为爱」其实是怕孤单）。審判逆位说：最大的阻碍，是「召喚未回應」——不是没有爱，是你们没有认真回答心里的问，关系就卡在「既不起来也不下去」。 你堵住了耳朵。 别等对方先示范。今天你先用「誠实答一题」给关系一个可跟的节拍。`,
  psychologyLayer: `【关系现状】你们的关系里有一个「你不敢听的声音」。可能是该结束了，可能是该开始了，可能是该承认了。你一直捂耳朵，但那个声音一直在。审判逆位问你：你打算装到什么时候？\n\n【心理层面】你怕的是「听了就得动」。你宁愿捂着耳朵，也不愿意动。因为你不知道动了之后，能去哪。你问「这段关系的本质是什么」，其实你真正想问的是：「能不能不动？」\n\n【根源层面】你从小就怕变化。你宁愿待在不舒服的地方，也不愿意挪窝。你把「习惯了」当成爱，把「懒得动」当成专一。但审判逆位说：不动的人，也会被时间推着走。

【走向与影响】你怕的是「答了就没退路」。審判逆位提醒你：你真正怕的，可能是面对。心理层面的突破，是问——阻碍是「我们不敢答」，还是「我们在自欺」？`,
  spiritLayer: `宇宙在等你把手放下来。不一定要马上就听，但至少别捂着。你先放下来，感受一下那个声音。它可能没那么可怕。\n\n核心启示：你怕的不是那个声音，是听了之后，再也装不了没听见。

这条关系的走势，眼下还拴在「未回答」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「誠实答一题」的小事：对「这段关系我要不要」答一句——不逼行动，只让答案被自己听见。检查你的「行囊」：審判逆位问你——你逃避的，是什么答案？`,
  masterSummary: `势头绕在「未回答」上——真正的审判不是号角响，是你明明听见了，还说自己没听见。 第二问早已点破：你们之间最大的阻碍，往往是召喚未回應。審判逆位说：先誠实回答自己。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_21', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（世界正位）想对你说：走向不是「没有圓滿的可能」那种误会式的死局，而是两人的劲还拧在「没有完成当下的循環」上，没一起认、也没一起动。 世界牌中舞者于花環內；最大的阻碍，是你们其中一人或两人没有「把该完成的完成」——该说的话没说、该结束的没结束、该感谢的没感谢，于是新的循環无法真正开始。世界说：阻碍是「未完成的完成」；当你们愿意把这一圈画圓，下一圈才能开始。 我站在花环中央，手里拿着权杖，四周是完成的一切。 把力气花在看得见的一步：今天只做「完成一样」，做完就停。`,
  psychologyLayer: `【关系现状】你们的关系到了一个「圆满」。不是完美，是完整。有过的哭，有过的笑，有过的分分合合，都成了圆圈上的一笔。你不必再问「本质是什么」，因为本质就是：你走完了。\n\n【心理层面】你怕的是「走完以后怎么办」。你习惯了在路上，突然到了终点，你慌。你问「这段关系的本质是什么」，其实你真正想问的是：「接下来呢？」\n\n【根源层面】你一直在追。追一段感情，追一个结果，追一个「终于」。现在追到了，你发现自己不知道站哪儿。但世界告诉你：你追的不是终点，是你自己。你到了，你就能开始下一段。

【走向与影响】你怕的是「一完成就真的要变了」。世界正位提醒你：你真正怕的，可能是结束或开始。心理层面的突破，是接纳——阻碍往往是「我们不敢完成」；完成不是失去，是为了下一段。`,
  spiritLayer: `宇宙在教你「完成」。你不必一直走，走完的时候，你配得上停下来。看看来时的路，那些弯，那些坑，那些泪，都过去了。你站在这里，就是胜利。\n\n核心启示：你怕的不是终点，是你怕到终点之后，发现自己根本不想停。

若问势头卡在哪，多半是「完成」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「完成一样」的小事：选一样「该做没做」的——一句感谢、一次道歉、或一个清楚的「我们现在是_____」。不逼大圓滿，只完成一样。检查你的「行囊」：世界问你——你没画圓的，是什么？`,
  masterSummary: `「完成」松一寸，走向就变一寸——真正的圆满不是你得到了什么，是你终于敢说「够了」。 第二问那句仍管用：你们之间最大的阻碍，往往是未完成的完成。世界说：把这一圈画圓，下一圈才会来。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'major_21', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（世界逆位）想对你说：走向被「圓未画完或不敢画完」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 要麼关系卡在「差一点就圓滿」却总差那一点；要麼你们不敢给关系一个完整的定义、完整的结束或开始。世界逆位说：最大的阻碍，是「完成未完成」——不是没有爱，是爱卡在「既不算圓滿也不算放手」的夾縫里。 你没到。 影响走向不靠喊话，靠落地。今天完成「画一筆」，再谈别的。`,
  psychologyLayer: `【关系现状】你们的关系还差「一口气」。可能是该说的话没说，该原谅的没原谅，该放手的没放手。你觉得快了，但就是到不了。世界逆位问你：你停在门口，是不敢进去，还是在等人开门？\n\n【心理层面】你怕的是「进去之后」。你怕圆满了就没事了，没事了就会散。所以你故意留个口，让自己还有理由不结束。你问「这段关系的本质是什么」，其实你真正想问的是：「能不能永远在门口？」\n\n【根源层面】你从小就不敢收尾。你怕收尾之后，就没人陪你玩了。所以你把每段关系都留个尾巴，假装还没结束。但你不知道，尾巴拖久了，也会烂。

【走向与影响】你怕的是「画圓就真的要面对」。世界逆位提醒你：你真正怕的，可能是结局。心理层面的突破，是问——阻碍是「我们不敢完成」，还是「我们不知道怎麼完成」？`,
  spiritLayer: `宇宙在等你补上那一笔。缺口不大，你伸手就能摸到。但你不伸手，是因为你怕摸到之后，那个圆就真的合上了。\n\n核心启示：你怕的不是合不上，是你怕合上之后，再也找不回那个缺口的自己。

能量没有散，是聚在「未画圓」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「画一筆」的小事：选一样可以「画圓」的小事——一句话、一个儀式、或一个决定。不逼大圓滿，只让「完成」发生一点。检查你的「行囊」：世界逆位问你——你卡住的，是完美还是恐惧？`,
  masterSummary: `想动走势，先认「未画圓」这道结——真正的世界不是一个圆，是你敢承认那个缺口的自己，也是你的一部分。 对照第二问：你们之间最大的阻碍，往往是圓未画完。世界逆位说：完成当下的循環，下一段才能开始。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'wands_1', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（权杖一正位）想对你说：走向不是「没有火」那种误会式的死局，而是两人的劲还拧在「火还没一起点」上，没一起认、也没一起动。 雲端手递发芽的权杖；最大的阻碍，是你们其中一人或两人没有把「想在一起」化成具體的第一步——没表白、没承诺、没一起做一件「我们开始了」的事。权杖一说：阻碍是「起点未成」；火种在，只差一起点。 云中伸出一只手，握着一根刚发芽的权杖。 把力气花在看得见的一步：今天只做「点火」，做完就停。`,
  psychologyLayer: `【关系现状】你们的关系处于「萌芽期」——可能刚认识，可能刚心动，可能刚决定在一起。一切都不确定，但一切都有可能。权杖王牌告诉你：不确定不是问题，问题是你敢不敢把种子埋下去。\n\n【心理层面】你怕的是「万一长不好」。你一直拿着种子看，不敢种。你问「这段关系的本质是什么」，其实你真正想问的是：「它能长成我想要的样子吗？」\n\n【根源层面】你曾经种过，但没收成。那次之后，你就只敢看种子，不敢种土里。但权杖王牌说：你不种，就永远不知道这粒种子能长成什么。可能是草，也可能是树，但你得先让它接触土。

【走向与影响】你怕的是「点了会熄」。权杖一正位提醒你：你真正怕的，可能是被拒或失败。心理层面的突破，是接纳——阻碍往往是「我们不敢点火」；先让一把小火燒起来，再談永远。`,
  spiritLayer: `宇宙在等你这双手松下来。种子在手里攥久了，会捂熟的。你得松开，让它掉进土里，让天决定它活不活。你能做的，只是浇水。\n\n核心启示：你怕的不是关系不好，是你怕自己种不好。

这条关系的走势，眼下还拴在「起点」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「点火」的小事：为这段关系做一件「第一次」或「我们开始」的具體事。检查你的「行囊」：权杖一问你——你没点的，是怕熄还是怕負责？`,
  masterSummary: `势头绕在「起点」上——真正的开始不是你准备好了，是你敢在没准备好的时候，先迈脚。 第二问早已点破：你们之间最大的阻碍，往往是火还没一起点。权杖一说：阻碍是起点未成。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'wands_1', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（权杖一逆位）想对你说：走向被「火被浇熄或没人点」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 热情石沈大海、起点夭折、或你们其中一人不敢再试。权杖一逆位说：最大的阻碍，是「火花未显」；火种还在，需要你们一起护着再点。 权杖掉在地上，芽还没发就蔫了。 影响走向不靠喊话，靠落地。今天完成「护火」，再谈别的。`,
  psychologyLayer: `【关系现状】你们的关系一直「没开始」。可能是暧昧，可能是试探，可能是你想了很多但什么都没做。你觉得有戏，但戏没开演。权杖王牌逆位问你：你等的是什么？\n\n【心理层面】你怕的是「开始了就回不去了」。所以你宁愿停在开始前，那样永远可以有「万一」。你问「这段关系的本质是什么」，其实你真正想问的是：「能不能不开始，但一直有感觉？」\n\n【根源层面】你太会给自己留后路了。每件事你都想好了退路才做，但感情不是这样的。感情是你退了，就没了。你一直站在门口不进，门会自己关的。

【走向与影响】你怕的是「再点再熄」。权杖一逆位提醒你：你真正怕的，可能是重复失望。心理层面的突破，是问——阻碍是外在浇熄，还是我们不敢再点？`,
  spiritLayer: `宇宙在等你推门。不用推很大力，就推一点。推开了，你就能看见里面的光。你不推，就一直在门外猜。\n\n核心启示：你怕的不是开始，是你怕开始了之后，发现不过如此。

能量没有散，是聚在「火未点」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「护火」的小事：选一件你曾为这段关系做过却停下来的事，再做一次。检查你的「行囊」：权杖一逆位问你——上次熄火，是别人还是自己？`,
  masterSummary: `想动走势，先认「火未点」这道结——真正的开始不是准备好了，是你终于承认，永远不会有准备好的那天。 对照第二问：你们之间最大的阻碍，往往是火还没点起来。权杖一逆位说：火种还在，再点一次。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'wands_2', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（权杖二正位）想对你说：走向不是「没有方向」那种误会式的死局，而是两人的劲还拧在「方向未一起选」上，没一起认、也没一起动。 人站城牆托地球儀；最大的阻碍，是你们对「我们要往哪里去」没有共識——一个想定、一个想拖；一个要婚姻、一个要自由。权杖二说：阻碍是「未启航的选择」；不一起看地图，就一直在城牆上卡着。 你站在城堡顶上，手里握着地球。 影响走向不靠喊话，靠落地。今天完成「地图」，再谈别的。`,
  psychologyLayer: `【关系现状】你们的关系到了「选择的门槛」。可能是异地，可能是要不要推进，可能是要不要给承诺。你站在高处看，想看清每条路的尽头。但权杖二告诉你：你看不到的，只有走了才知道。\n\n【心理层面】你怕的是「选错」。你太想把每一步都算对了，算来算去，时间全花在算上，没花在走上。你问「这段关系的本质是什么」，其实你真正想问的是：「我能不能不走错？」\n\n【根源层面】你从小就被教「要选对」。所以你把选对看得比什么都重。但你不知道，感情里没有对错，只有选了之后怎么走。你一直站着，不是因为你还没想好，是因为你怕动。

【走向与影响】你怕的是「选了就要負责」。权杖二正位提醒你：你真正怕的，可能是承诺。心理层面的突破，是接纳——阻碍往往是「我们不敢一起选方向」；先对齊地图，再談启航。`,
  spiritLayer: `宇宙在等你把地球放下来。你手里握着的，不是你拥有的世界，是你舍不得放下的可能。你不放，手就一直满着，装不了新的。\n\n核心启示：你怕的不是选错，是你怕选了之后，不能怪别人了。

就走向而言，两人的气机还绕在「愿景」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「地图」的小事：和对方或自己寫下一句——「我们这段关系，一年后希望_____。」检查你的「行囊」：权杖二问你——你卡住的，是选错还是怕选？`,
  masterSummary: `走向的纽子在「愿景」——真正的选择不是站在高处看，是走进去之后，才知道低处有什么。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是方向未一起选。权杖二说：不一起看地图，就一直在城牆上。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'wands_2', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（权杖二逆位）想对你说：阻碍是「一方想走一方想留」或「不敢选」。 地球儀很重、視線模糊；最大的阻碍，是你们对未来的想像从没对齊，或一直用拖延代替选择。权杖二逆位说：阻碍是「未启航」；不选，時间一样在走。 你慌了。 把力气花在看得见的一步：今天只做「对齊」，做完就停。`,
  psychologyLayer: `【关系现状】你们的关系里全是「犹豫」。他进你退，他退你进，谁都不肯先迈。你觉得自己在等时机，但权杖二逆位告诉你：你等的是别人先动。\n\n【心理层面】你怕的是「万一错了」。你太怕错了，所以把决定权推给他。他选对了，你沾光；他选错了，你怪他。你问「这段关系的本质是什么」，其实你真正想问的是：「能不能让他选？」\n\n【根源层面】你从小就没被允许犯过错。每次错都被骂，所以你现在干脆不选了。不选，就不会被骂。但你不选，也就没有你自己。

【走向与影响】你怕的是「选错就回不了头」。权杖二逆位提醒你：你真正怕的，可能是失去选项。心理层面的突破，是问——阻碍是我们要的不一样，还是我们不敢说要什么？`,
  spiritLayer: `宇宙在等你把地球扔出去。你拿着有什么用？那是别人的世界，不是你的。你扔了它，才能空出手来接自己的。\n\n核心启示：你怕的不是选错，是你怕选了之后，再也没有人让你怪了。

能量没有散，是聚在「未对齊」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「对齊」的小事：问对方或自己——「你觉得我们这段关系，现在最缺的是_____？」检查你的「行囊」：权杖二逆位问你——你留城牆上，是看远方还是怕跳？`,
  masterSummary: `想动走势，先认「未对齊」这道结——真正的犹豫不是你选不出来，是你不敢对自己负责。 对照第二问：你们之间最大的阻碍，往往是未启航的选择。权杖二逆位说：不选，時间一样在走。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'wands_3', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（权杖三正位）想对你说：走向不是「没有船」那种误会式的死局，而是两人的劲还拧在「船还没一起等」上，没一起认、也没一起动。 三根权杖落地、船駛向远方；最大的阻碍，是你们对「结果什么時候到」「要等多久」没有共識——一方急、一方慢；或你们放了船却各自等不同的岸。权杖三说：阻碍是「等待未同步」；一起等，船才会有同一个方向。 你站在岸边，看着船出海。 别等对方先示范。今天你先用「对表」给关系一个可跟的节拍。`,
  psychologyLayer: `【关系现状】你们的关系里有一个「等待期」。可能是等他回复，可能是等他决定，可能是等他回来。你把目光都钉在海平面上，忘了看脚下的土。权杖三问你：你站的地方，草都长高了，你没看见？\n\n【心理层面】你怕的是「白等」。你怕等了半天，船不回来，你什么都没落下。你问「这段关系的本质是什么」，其实你真正想问的是：「我等的人，值得我等吗？」\n\n【根源层面】你太会等了。从小就在等，等长大、等毕业、等那个人来。你把等当成了爱，但你不知道，真正爱你的人，不会让你一直等。你一直在等，是因为你不敢要。

【走向与影响】你怕的是「等不到」。权杖三正位提醒你：你真正怕的，可能是白等。心理层面的突破，是接纳——阻碍往往是「我们等的不是同一艘船」；先对齊等的什么，再談耐心。`,
  spiritLayer: `宇宙在等你转身。你一直看海，海就那么几个颜色。你转身，能看见山，能看见花，能看见一个也在等你的人。\n\n核心启示：你怕的不是等不到，是你怕不等了之后，发现自己根本不知道去哪。

就走向而言，两人的气机还绕在「远见」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「对表」的小事：和对方说一句——「我们这段关系，已经在路上了；我们在等的是_____。」检查你的「行囊」：权杖三问你——你等的，是船还是不会来的保证？`,
  masterSummary: `走向的纽子在「远见」——真正的等待不是你一直看着海，是你看着海的时候，手里还在种地。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是等待未同步。权杖三说：一起等，船才有同一个方向。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'wands_3', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（权杖三逆位）想对你说：走向被「船迟迟不歸或方向错了」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 预期落空、共識破裂；最大的阻碍，是你们等的不是同一艘船、或羅盤错了却没人承认。权杖三逆位说：阻碍是「孤立的等待」；别在廢港死等。 船还没回来，你开始慌了。 你若真想推动走势，就从「对表」开始——轻，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里充满了「不确定感」。你每天在想他是不是变了，是不是不爱了，是不是要走了。你把所有精力都用在猜上，忘了问自己：我在不在？\n\n【心理层面】你怕的是「被丢下」。你太怕了，所以一直在确认。确认他有没有回消息，确认他有没有看别人，确认他是不是还爱你。但你确认来确认去，把自己确认没了。你问「这段关系的本质是什么」，其实你真正想问的是：「他会不会丢下我？」\n\n【根源层面】你被丢下过一次。那次之后，你就不敢再信了。你把自己变成侦探，每天找蛛丝马迹，生怕又被丢下。但你不知道，你越找，你越像那个会被丢下的人。

【走向与影响】你怕的是「承认等错」。权杖三逆位提醒你：你真正怕的，可能是幻滅。心理层面的突破，是问——我们等的，是同一艘船吗？`,
  spiritLayer: `宇宙在等你把放大镜放下。你看得太细了，细到看不见大的。他不回消息，可能只是忙；他走慢一步，可能只是累了。你把每个细节都当成证据，但你不知道，证据是要在法庭上用的，不是在爱里用的。\n\n核心启示：你怕的不是他走，是你怕他走了之后，你终于要面对那个一直不信任的自己。

能量没有散，是聚在「方向或時机」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「对表」的小事：问对方——「你觉得我们这段关系，现在在等什么？」检查你的「行囊」：权杖三逆位问你——你等的，是爱还是习惯？`,
  masterSummary: `想动走势，先认「方向或時机」这道结——真正的信任不是他永远不回消息，是你敢在不回消息的时候，还信自己。 对照第二问：你们之间最大的阻碍，往往是等的不是同一艘船。权杖三逆位说：别在廢港死等。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'wands_4', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（权杖四正位）想对你说：走向不是「没有家」那种误会式的死局，而是两人的劲还拧在「家的柱子不稳」上，没一起认、也没一起动。 四根权杖撐花環；最大的阻碍，是你们的稳定建立在「假装没问题」上——没談清楚的界線、没面对的裂痕、或一方扛太多另一方不知。权杖四说：阻碍是「结構松动」；不一起撐四根柱子，慶典是假的。 四根权杖立在地上，花环挂在上头。 你能拧动的开关往往在细节：今天把「检查柱子」做实，比分析十句有用。`,
  psychologyLayer: `【关系现状】你们的关系到了一个「稳定期」。可能是同居了，可能是见过家长了，可能是你们不再折腾了。你觉得踏实，但又有点怕太踏实。权杖四问你：你怕的不是稳，是稳了之后，还有什么？\n\n【心理层面】你怕的是「没新鲜感了」。你把激情当成了爱的唯一标准，一稳下来就觉得是不是不爱了。你问「这段关系的本质是什么」，其实你真正想问的是：「就这样了吗？」\n\n【根源层面】你从小就在动。家里动，学校动，你从来没真正停过。所以现在一停，你就不习惯。但权杖四说：停不是不动，是你可以安心在这里了。

【走向与影响】你怕的是「一碰就塌」。权杖四正位提醒你：你真正怕的，可能是面对裂痕。心理层面的突破，是接纳——阻碍往往是「我们不敢承认柱子歪了」；先看见，再一起修。`,
  spiritLayer: `宇宙在等你安下心来。你一直跑来跑去，是因为不信有地方能让你停。现在你停了，就好好停一会儿。感受一下，停的感觉，也很快乐。\n\n核心启示：你怕的不是稳定，是你怕稳定之后，就没有理由再跑了。

若问势头卡在哪，多半是「根基」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「检查柱子」的小事：寫下一句——「这段关系里，我们一直在假装没问题的是_____。」检查你的「行囊」：权杖四问你——你的四根柱子，是两人撐还是你一人扛？`,
  masterSummary: `「根基」松一寸，走向就变一寸——真正的家不是四面墙，是你站进去，就不想再跑的地方。 第二问那句仍管用：你们之间最大的阻碍，往往是家的柱子不稳。权杖四说：不一起撐，慶典是假的。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'wands_4', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（权杖四逆位）想对你说：走向被「名存实亡的安定」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 花環傾斜、人群散去；最大的阻碍，是你们在一段不再成长的稳定里窒息、或表面和谐底下基石松了。权杖四逆位说：阻碍是「偽安詳」；别在漏水的城堡里跳舞。 花环掉在地上，权杖歪了。 今天用「看见」替关系试温：你动了，场的流向才会跟着变。`,
  psychologyLayer: `【关系现状】你们的关系里缺少「归属感」。可能是一直没定下来，可能是总感觉不到「这是我家」。你觉得不稳，但不知道差什么。权杖四逆位问你：你有没有想过，你差的是你自己先住进去？\n\n【心理层面】你怕的是「这不是我想要的」。但你也不知道你想要什么。你一直等别人给你安全感，但你自己都没给自己安全感。你问「这段关系的本质是什么」，其实你真正想问的是：「谁能给我一个家？」\n\n【根源层面】你从小就没一个真正的家。爸妈忙，你一个人；朋友换，你一个人。你把家这个词看得太重，重到谁都给不起。但权杖四逆位说：家不是别人给的，是你自己建的。

【走向与影响】你怕的是「拆穿就无家可歸」。权杖四逆位提醒你：你真正怕的，可能是失去安全。心理层面的突破，是问——我们是在撐家，还是在粉飾裂痕？`,
  spiritLayer: `宇宙在等你先住下来。你别管房子歪不歪，你先坐下。坐下了，心就定了。心定了，房子就会慢慢变正。\n\n核心启示：你怕的不是没家，是你怕有了家之后，发现自己根本不会住。

若问势头卡在哪，多半是「结構松动」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「看见」的小事：承认一句——「这段关系里，我们假装没问题的是_____。」检查你的「行囊」：权杖四逆位问你——你留着，是爱还是怕没地方去？`,
  masterSummary: `「结構松动」松一寸，走向就变一寸——真正的家不是有人等你，是你自己敢回的地方。 第二问那句仍管用：你们之间最大的阻碍，往往是漏水的城堡。权杖四逆位说：别在漏水的城堡里跳舞。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'wands_5', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（权杖五正位）想对你说：走向不是「没有在意」那种误会式的死局，而是两人的劲还拧在「在意的方式在打架」上，没一起认、也没一起动。 五根权杖亂舞；最大的阻碍，是你们用爭吵、競爭、各執己见代替沟通——没人听见对方在爭什么，只在乎自己有没有赢。权杖五说：阻碍是「亂局未釐清」；在雜音中保持自己的节奏，也要听对方的权杖在揮什么。 五根权杖在空中交叉，你打我，我打你。 走向听行动。今天只兑现「听爭」——让对方看见你在动，而不是在讲。`,
  psychologyLayer: `【关系现状】你们的关系里充满了「冲突」。为小事吵，为大事吵，为没发生的事也吵。你累了，你觉得是不是不合适。但权杖五告诉你：吵不可怕，可怕的是你们吵完不记笔记。\n\n【心理层面】你怕的是「吵多了会散」。你不敢吵，不敢说，不敢表达真实的想法。你以为忍着就能和平，但忍着的和平是假的。你问「这段关系的本质是什么」，其实你真正想问的是：「我们能不吵吗？」\n\n【根源层面】你从小就见惯了「吵就散」的戏。父母吵架，邻居离婚，你得出一个结论：吵架就是终结的前奏。但权杖五说：你见的是不会吵的，真正会吵的人，吵完了还能一起吃饭。

【走向与影响】你怕的是「不爭就输」。权杖五正位提醒你：你真正怕的，可能是被否定。心理层面的突破，是接纳——阻碍往往是「我们在爭对错而不是爭被看见」；吵出边界也是一种沟通。`,
  spiritLayer: `宇宙在等你学会「健康的冲突」。不是不吵，是吵的时候还知道对方是谁。不是赢了才罢休，是吵完了还能抱。你越躲，冲突越积越大。\n\n核心启示：你怕的不是吵架，是你怕吵完之后，发现你们都不会和好。

这条关系的走势，眼下还拴在「磨合」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「听爭」的小事：下次有摩擦時，闭嘴三十秒，只听对方在爭什么。检查你的「行囊」：权杖五问你——你爭的，是对错还是被看见？`,
  masterSummary: `势头绕在「磨合」上——真正的冲突不是谁赢谁输，是吵完了，还愿意睡一张床。 第二问早已点破：你们之间最大的阻碍，往往是亂局未釐清。权杖五说：吵完要听见彼此。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'wands_5', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（权杖五逆位）想对你说：走向被「冷戰或逃避冲突」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 喧闹靜止；最大的阻碍，是你们不吵了，但问题转到地下——表面客气、各怀鬼胎，或疲憊后的假和平。权杖五逆位说：阻碍是「沉默比爭吵更伤」；别再玩躲貓貓。 权杖散了一地，没人打架了。 你要影响走向，今天就卡这一格：把「破冰」做到底，小不要紧，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里现在「不吵了」。你以为是变好了，但其实你心里知道，不是不吵，是不想吵了。你们各自回到角落，不说话，不看对方。权杖五逆位问你：你是不是觉得，这样就安全了？\n\n【心理层面】你怕的是「吵了也没用」。你觉得无论怎么说，他都不会改；无论怎么表达，你都听不见。所以你干脆不说。但你不知道，不说，就真的没救了。你问「这段关系的本质是什么」，其实你真正想问的是：「我说了有用吗？」\n\n【根源层面】你曾经吵过，没用过。那次之后，你就把嘴闭上了。但你不知道，没用，不是因为你吵得不对，是因为你吵的那个人，根本不想听。现在这个人，你还没试过，就闭嘴了。

【走向与影响】你怕的是「一吵就崩」。权杖五逆位提醒你：你真正怕的，可能是面对冲突。心理层面的突破，是问——我们是在休息，还是在躲？`,
  spiritLayer: `宇宙在等你张开嘴。沉默不是金，是墙。你越沉默，墙越厚。墙厚到有一天，你连他在哪都看不见了。\n\n核心启示：你怕的不是吵，是你怕吵了之后，发现根本没人听。

若问势头卡在哪，多半是「未解决的冲突」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「破冰」的小事：选一件你一直没说的不滿，寫下来或说一句。检查你的「行囊」：权杖五逆位问你——你闭嘴，是为了和平还是为了不面对？`,
  masterSummary: `「未解决的冲突」松一寸，走向就变一寸——真正的沉默不是没话说，是你说了也没人听之后，就不再说了。 第二问那句仍管用：你们之间最大的阻碍，往往是地下的事没拿到地上说。权杖五逆位说：沉默有時比爭吵更伤。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'wands_6', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（权杖六正位）想对你说：走向不是「没有值得被祝福的」那种误会式的死局，而是两人的劲还拧在「不敢一起被看见」上，没一起认、也没一起动。 戰士騎馬戴桂冠；最大的阻碍，是你们其中一人或两人不敢公开、不敢一起接受祝福、或只有一方在光里一方在陰影。权杖六说：阻碍是「光未共享」；一起站在光里，阻碍就从「怕被看」变成「一起被祝福」。 你骑着马，举着权杖，有人在你前面开路，有人在你后面欢呼。 你要影响走向，今天就卡这一格：把「分享光」做到底，小不要紧，但要真。`,
  psychologyLayer: `【关系现状】你们的关系到了一个「被认可」的阶段。可能是朋友祝福了，可能是家人接受了，可能是你们终于可以光明正大在一起了。你心里有光，但权杖六问你：这个光，是别人给你的，还是你自己点的？\n\n【心理层面】你怕的是「赢了一时，赢不了一世」。你怕现在被认可，以后被推翻。你问「这段关系的本质是什么」，其实你真正想问的是：「这份认可，能持续多久？」\n\n【根源层面】你从小就需要被认可。考了第一名才被夸，做对了事才被爱。你把这份习惯带进了感情，以为只有被大家说好，才算好。但权杖六说：真正的好，是你自己觉得好。

【走向与影响】你怕的是「见光死」。权杖六正位提醒你：你真正怕的，可能是被評判。心理层面的突破，是接纳——阻碍往往是「我们不敢一起被看见」；分享榮耀，不独占舞台。`,
  spiritLayer: `宇宙在等你放下那些欢呼。你听听，真正在喊的，不是他们，是你自己心里那句：「我做到了。」那一声，比所有都响。\n\n核心启示：你怕的不是不被认可，是你怕自己从来就没认可过自己。

就走向而言，两人的气机还绕在「被认可」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「分享光」的小事：在一个场合里，把对方或这段关系介紹给别人，或公开感谢对方一次。检查你的「行囊」：权杖六问你——你要的，是关系被看见还是只有自己被看见？`,
  masterSummary: `走向的纽子在「被认可」——真正的胜利不是你站在高处被人看，是你敢在高处看自己。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是不敢一起被看见。权杖六说：一起接受掌声。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'wands_6', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（权杖六逆位）想对你说：走向被「掌声没了或只有一方在光里」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 戰士跌落、花環掉泥；最大的阻碍，是热情消退、外界不看好、或你们对「我们还值不值得被祝福」动摇了。权杖六逆位说：阻碍是「信任危机」；舞台会塌，但你们可以一起在泥里站起来。 你从马上摔下来，权杖丢了，后面的人散了。 走向听行动。今天只兑现「不靠掌声」——让对方看见你在动，而不是在讲。`,
  psychologyLayer: `【关系现状】你们的关系里出现了「反转」。可能是一直顺利的事突然卡了，可能是一直支持你们的人突然变脸了。你觉得委屈，觉得不公平。但权杖六逆位问你：你站得那么高，是他们的功劳，还是你本来就高？\n\n【心理层面】你怕的是「失去认可」。你太习惯被人夸了，一没了，就慌。你问「这段关系的本质是什么」，其实你真正想问的是：「他们为什么不看好我们了？」\n\n【根源层面】你一直靠外界的评价活着。他们说你好，你就好；他们说不好，你就怀疑自己。你把评价权交给了别人，别人一转身，你就空了。但权杖六逆位说：空的是你手里的权杖，不是你自己。

【走向与影响】你怕的是「我们不够好」。权杖六逆位提醒你：你真正怕的，可能是掌声是假的。心理层面的突破，是问——我们是为掌声而活，还是为彼此而活？`,
  spiritLayer: `宇宙在等你学会「不被认可的时候怎么活」。那些散了的人，本来就不是你的。你真正的队伍，是你自己。\n\n核心启示：你怕的不是别人不认可，是你怕自己认可了自己之后，别人还不认可。

这条关系的走势，眼下还拴在「对外界的依賴」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「不靠掌声」的小事：做一件纯粹为彼此、不为任何人看见的事。检查你的「行囊」：权杖六逆位问你——你爱的是这个人，还是「被羡慕的我们」？`,
  masterSummary: `势头绕在「对外界的依賴」上——真正的失败不是从马上掉下来，是你掉下来之后，以为自己就再也不能骑马了。 第二问早已点破：你们之间最大的阻碍，往往是掌声没了之后的信任危机。权杖六逆位说：舞台会塌，心别塌。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'wands_7', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（权杖七正位）想对你说：走向不是「没有立场」那种误会式的死局，而是两人的劲还拧在「没有一起守」上，没一起认、也没一起动。 一人抵御下方圍攻；最大的阻碍，是外界壓力、流言、或「谁来扛」——只有一方在守、另一方撤了，或两人没有站在同一条防線上。权杖七说：阻碍是「防線未合一」；一起占据高地，阻碍才守得住。 你站在高处，六根权杖从下面攻上来，你举着手里的那根，往下戳。 今天用「划界」替关系试温：你动了，场的流向才会跟着变。`,
  psychologyLayer: `【关系现状】你们的关系里出现了「外部压力」。可能是朋友反对，可能是现实问题，可能是你们自己的心开始动摇。你站在高处，一个一个地应对，累了，但没撤。权杖七问你：你这么守，守的是什么？\n\n【心理层面】你怕的是「守不住」。你怕你撑了那么久，最后还是撑不住。你问「这段关系的本质是什么」，其实你真正想问的是：「我还要守多久？」\n\n【根源层面】你从小就是那个「扛事」的人。家里有事你扛，朋友有事你扛，现在感情有事还是你扛。你把扛当成责任，但你忘了，你也是人，也会累。权杖七说：你扛的不是关系，是你那个「不能输」的自己。

【走向与影响】你怕的是「守不住」或「只剩自己在守」。权杖七正位提醒你：你真正怕的，可能是孤軍奮戰。心理层面的突破，是问——我们是在同一条防線上吗？`,
  spiritLayer: `宇宙在等你问一句：「我能不能不扛？」不是你撑不住了，是你该换人扛一扛了。两个人的关系，你一个人扛，迟早塌。\n\n核心启示：你怕的不是守不住，是你怕守不住了之后，发现没人帮你。

就走向而言，两人的气机还绕在「防衛」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「划界」的小事：对一个试图介入或否定你们关系的外人，给出一句礼貌但堅定的界線。检查你的「行囊」：权杖七问你——你守的是关系，还是只有自己的面子？`,
  masterSummary: `走向的纽子在「防衛」——真正的守护不是你一个人撑，是你撑的时候，知道身后有人。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是没有一起守。权杖七说：一起守，防線才在。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'wands_7', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（权杖七逆位）想对你说：走向被「招架不住或防線只有一人」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 山丘崩塌、防線吃力；最大的阻碍，是外界壓力太大、或你们对「还要不要守」动摇了，有一方已经撤了。权杖七逆位说：阻碍是「困獸之鬥」；若堅持只会燃尽，或許需要撤退或找盟友。 你退下来了。 你能拧动的开关往往在细节：今天把「求援」做实，比分析十句有用。`,
  psychologyLayer: `【关系现状】你们的关系里出现了「撤退」。可能是你主动退了一步，可能是你不再争了，可能是你发现守着没意义。你觉得自己输了，但权杖七逆位问你：你退下来之后，看见什么了？\n\n【心理层面】你怕的是「放手之后一无所有」。你守了那么久，是因为你觉得只有守着，关系才在。但你不知道，有些关系，你越守，它越远。你问「这段关系的本质是什么」，其实你真正想问的是：「我放手了，它还在吗？」\n\n【根源层面】你一直被教育「不能放弃」。所以你不懂什么是「主动撤退」。你把所有坚持都当成对的，把放手都当成输。但权杖七逆位说：有时候，放下来，才能看见是不是真的值得守。

【走向与影响】你怕的是「一撤就全垮」。权杖七逆位提醒你：你真正怕的，可能是只剩自己在扛。心理层面的突破，是问——我们是该一起撤，还是一起找援軍？`,
  spiritLayer: `宇宙在等你站起来，不用再守了。你下来，不是为了逃，是为了看清那些攻上来的人，到底是谁。是你自己，还是你想象出来的敌人？\n\n核心启示：你怕的不是守不住，是你怕一放，就再也不会守了。

这条关系的走势，眼下还拴在「孤軍奮戰」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「求援」的小事：和对方或信任的人说一句——「我／我们需要支持。」检查你的「行囊」：权杖七逆位问你——你守的，是关系还是已经守不住的堡壘？`,
  masterSummary: `势头绕在「孤軍奮戰」上——真正的撤退不是输了，是你发现战场是错的。 第二问早已点破：你们之间最大的阻碍，往往是孤軍奮戰。权杖七逆位说：别一个人死磕。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'wands_8', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（权杖八正位）想对你说：走向不是「没有动能」那种误会式的死局，而是两人的劲还拧在「动能不同步」上，没一起认、也没一起动。 八根权杖掠过天空；最大的阻碍，是你们一个想快、一个想慢，或消息誤傳、节奏亂了——箭在弦上却没一起发。权杖八说：阻碍是「速度未对齊」；順流時，唯一的错誤是犹豫，但若两人不同步，流会把你们沖散。 八根权杖在空中飞，像箭，像流星。 你若真想推动走势，就从「順流」开始——轻，但要真。`,
  psychologyLayer: `【关系现状】你们的关系正在「加速」。可能是他突然表白了，可能是你们突然同居了，可能是事情一件接一件，你都来不及反应。你觉得太快了，但权杖八问你：快，就一定不好吗？你一直想要结果，现在结果来了，你却怕了。\n\n【心理层面】你怕的是「太快了会摔」。你习惯了一步一步走，每一步都想清楚。现在火箭一样往前冲，你觉得自己要被甩出去。你问「这段关系的本质是什么」，其实你真正想问的是：「能不能慢一点？」\n\n【根源层面】你从小就被教「欲速则不达」。你把这句话刻在脑子里，什么都慢慢来，生怕太快了就出错。但你忘了，有些事，快的时候才过瘾。感情不是盖房子，不用每一块砖都对得整整齐齐。

【走向与影响】你怕的是「一慢就没了」。权杖八正位提醒你：你真正怕的，可能是错过時机。心理层面的突破，是接纳——阻碍往往是「我们没有一起乘風」；先对齊速度，再发箭。`,
  spiritLayer: `宇宙在等你张开手接住。那八根权杖是冲着你来的，不是来打你的，是来给你的。你一直躲，就永远接不住。你伸手，哪怕只接住一根，那也是你的。\n\n核心启示：你怕的不是太快，是你怕太快了之后，发现那不是你要的。

这条关系的走势，眼下还拴在「流动」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「順流」的小事：对这段关系做一件「不拖延」的事——一句表白、一次约定、或一个决定。检查你的「行囊」：权杖八问你——你迟疑的，是怕错还是怕快？`,
  masterSummary: `势头绕在「流动」上——真正的快不是赶路，是你终于敢跟着风跑一次。 第二问早已点破：你们之间最大的阻碍，往往是动能不同步。权杖八说：一起乘風，箭发不回。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'wands_8', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（权杖八逆位）想对你说：走向被「欲速則不达或节奏亂了」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 权杖在空中糾结或墜落；最大的阻碍，是消息誤傳、发展过快导致不適、或你们对「要冲多快」不同步。权杖八逆位说：阻碍是「混亂的疾速」；若速度让你看不清方向，先停下来。 权杖还在空中飞，但永远到不了。 别等对方先示范。今天你先用「暫停」给关系一个可跟的节拍。`,
  psychologyLayer: `【关系现状】你们的关系正在「卡在半路」。可能是他一直不表态，可能是你一直等不来那句承诺，可能是事情该发生了却迟迟不发生。你等得心焦，但你不知道，是你站的地方不对。\n\n【心理层面】你怕的是「永远等不到」。你把时间都花在等上，等他说那三个字，等他想明白，等他迈出那一步。但你不知道，你等的那些人，可能一直在等你迈第一步。你问「这段关系的本质是什么」，其实你真正想问的是：「我能不能不等了？」\n\n【根源层面】你从小就在等。等爸妈回家，等朋友来找你，等别人主动。你习惯了被动，把主动当成别人的事。但权杖八逆位说：你站那么远，人家怎么把权杖递给你？

【走向与影响】你怕的是「一停就散」。权杖八逆位提醒你：你真正怕的，可能是错过。心理层面的突破，是问——速度让你看清方向了吗？若看不清，先停。`,
  spiritLayer: `宇宙在等你往前走一步。不用太多，就一步。你走一步，权杖就离你近一步。你一直站着，它就永远在半空。\n\n核心启示：你怕的不是等不到，是你怕走了之后，发现根本没有权杖。

若问势头卡在哪，多半是「盲目冲刺」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「暫停」的小事：接下来 24 小時，不做任何「加速」的决定，只觀察。检查你的「行囊」：权杖八逆位问你——你冲的，是爱还是焦慮？`,
  masterSummary: `「盲目冲刺」松一寸，走向就变一寸——真正的等待不是你站着不动，是你一边走一边等。 第二问那句仍管用：你们之间最大的阻碍，往往是混亂的疾速。权杖八逆位说：速度让你看不清時，先停。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'wands_9', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（权杖九正位）想对你说：走向不是「没有防線」那种误会式的死局，而是两人的劲还拧在「防線只有你在守」上，没一起认、也没一起动。 受伤戰士靠权杖、身后是屏障；最大的阻碍，是你们其中一人歷经戰鬥后已经透支，或两人没有一起守住最后一哩路——一方撤了、一方还在硬撐。权杖九说：阻碍是「最后防線未一起守」；快不行的時候，往往就是天亮前，但要一起守。 你身上全是伤，旧的没好，新的又来了。 把力气花在看得见的一步：今天只做「不撤」，做完就停。`,
  psychologyLayer: `【关系现状】你们的关系里充满了「疲惫」。吵过，和好过，又吵过。你觉得自己像个战士，天天在守，天天在防。但你不知道，你在防的不是他，是你自己心里那个「不能再输一次」的自己。\n\n【心理层面】你怕的是「撑不住」。你把所有力气都用在了撑上，忘了问自己：我为什么要撑？你问「这段关系的本质是什么」，其实你真正想问的是：「我能不能不撑了？」\n\n【根源层面】你从小就是那个「撑」的人。家里有事你撑，朋友有事你撑，恋爱有事你撑。你把撑当成了习惯，当成了活着的证明。但你不知道，一直撑的人，会撑成一座雕像，不会动，也不会软。

【走向与影响】你怕的是「再也守不住」。权杖九正位提醒你：你真正怕的，可能是孤軍奮戰。心理层面的突破，是接纳——疲憊是勇敢的勳章；堅持住，但别一个人守。`,
  spiritLayer: `宇宙在等你放下来一秒钟。你不用全放，就放下来一秒钟，感受一下没有武器的自己。那一秒，你可能发现，没人打你。\n\n核心启示：你怕的不是守不住，是你怕一放下来，就再也拿不起来了。

就走向而言，两人的气机还绕在「终局考验」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「不撤」的小事：对对方或自己说一句——「我们还在一起，我们还守着。」检查你的「行囊」：权杖九问你——你守的，是关系还是习惯？`,
  masterSummary: `走向的纽子在「终局考验」——真正的撑不是你一直站着，是你敢站的时候也敢坐。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是没有一起守到天亮。权杖九说：我们还站着，但要一起。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'wands_9', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（权杖九逆位）想对你说：走向被「徹底透支或防御崩潰」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 权杖掉落、屏障崩潰；最大的阻碍，是你们推开了想幫的人、或精神脆弱轻易投降，或对「还要不要守」已经没力了。权杖九逆位说：阻碍是「无效防御」；有時放下权杖，才是出路。 你撑不住了。 影响走向不靠喊话，靠落地。今天完成「松手」，再谈别的。`,
  psychologyLayer: `【关系现状】你们的关系里你「卸下了」。可能是不吵了，可能是不争了，可能是你终于说了一句「我不行了」。你觉得自己输了，但权杖九逆位问你：输了，就一定是坏事吗？\n\n【心理层面】你怕的是「承认累就是认输」。你一直撑着，就是不想认输。但现在撑不动了，你终于承认了。你问「这段关系的本质是什么」，其实你真正想问的是：「承认累了，还能继续吗？」\n\n【根源层面】你从小就被教「不能喊累」。喊累就是没本事，喊累就是不如人。所以你一直硬撑着，直到撑断为止。但权杖九逆位说：累是正常的，喊出来，才能有人帮你撑。

【走向与影响】你怕的是「一松就全垮」。权杖九逆位提醒你：你真正怕的，可能是承认撐不住。心理层面的突破，是问——我们是在守关系，还是与空气格鬥？`,
  spiritLayer: `宇宙在等你开口说一句：「我累了。」不是抱怨，是承认。你承认了，天不会塌，反而会有人走过来，问你一句：「要不要靠一下？」\n\n核心启示：你怕的不是累，是你怕累了之后，就没人爱你了。

能量没有散，是聚在「过度防衛」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「松手」的小事：选一件你一直「死守」的堅持，试着说——「我累了，我们可以換一种方式吗？」检查你的「行囊」：权杖九逆位问你——你防的，是真正的危险还是过去的伤？`,
  masterSummary: `想动走势，先认「过度防衛」这道结——真正的累不是撑不住，是你撑住了才发现，根本没人让你撑。 对照第二问：你们之间最大的阻碍，往往是撐不住時不敢松手。权杖九逆位说：放下权杖，有時才是出路。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'wands_10', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（权杖十正位）想对你说：走向不是「没有担当」那种误会式的死局，而是两人的劲还拧在「担子分配错了」上，没一起认、也没一起动。 人抱十根权杖低头行路；最大的阻碍，是你们其中一人或两人背負了过多——对方的期待、家族的壓力、或「关系该怎样」的剧本，壓到看不见前方的路。权杖十说：阻碍是「重担未分配」；背負全世界的人，终將被壓垮。 你被压弯了。 今天用「減負」替关系试温：你动了，场的流向才会跟着变。`,
  psychologyLayer: `【关系现状】你们的关系里你一个人扛了太多。他的情绪、他的问题、他的未来，你都背在身上。你觉得自己在爱，但其实你是在替别人活。权杖十问你：你背的这些东西，有多少是他让你背的？有多少是你自己抢着背的？\n\n【心理层面】你怕的是「放下来就散了」。你以为你扛着一切，关系才能维持。你问「这段关系的本质是什么」，其实你真正想问的是：「我能不能放下来试试？」\n\n【根源层面】你从小就是那个「懂事」的孩子。家里的事你扛，朋友的事你扛，别人的错你也扛。你把扛当成了爱，但你不懂，真爱是两个人一起扛，不是你一个人当牛。

【走向与影响】你怕的是「一放下就全垮」。权杖十正位提醒你：你真正怕的，可能是没人扛。心理层面的突破，是问——哪些担子是我们的，哪些是别人的？學会分配。`,
  spiritLayer: `宇宙在等你分一半出去。不是他不愿意扛，是你从来没给过他机会。你一直说「我来」，他就习惯了「你来」。现在你累了，分一点给他，他才知道你也需要人帮。\n\n核心启示：你怕的不是扛不动，是你怕一放下来，发现你扛的根本不是你该扛的。

能量没有散，是聚在「责任分配」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「減負」的小事：寫下「这段关系里，我／我们背負的十件事」，圈出三件可以交给对方或放下的。检查你的「行囊」：权杖十问你——你背的，是爱还是习惯性扛？`,
  masterSummary: `想动走势，先认「责任分配」这道结——真正的扛不是你一个人撑着天，是你撑着的时候，知道有人也在撑你。 对照第二问：你们之间最大的阻碍，往往是重担未分配。权杖十说：放下幾根权杖，抬头看路。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'wands_10', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（权杖十逆位）想对你说：走向被「壓力崩潰或该放未放」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 权杖灑落一地；最大的阻碍，是你们突然放弃、或终于肯放下一些担子却不知如何分工——斷舍離的陣痛。权杖十逆位说：阻碍是「该放手的未放手」；放下一些权杖，才能走得更远。 你放下来了。 你能拧动的开关往往在细节：今天把「不撿」做实，比分析十句有用。`,
  psychologyLayer: `【关系现状】你们的关系里你「卸货了」。可能是你终于不管了，可能是你让他自己处理了。你觉得轻松了，但也空了。权杖十逆位问你：你空了之后，还知道你是谁吗？\n\n【心理层面】你怕的是「没事干之后，就没人需要你了」。你把价值都绑在「能扛事」上，一不用扛，就不知道自己算什么。你问「这段关系的本质是什么」，其实你真正想问的是：「不扛了，我还算什么？」\n\n【根源层面】你从小就被夸「能干」。能干的你，被需要；不能干的你，被忽略。所以你拼命能干，拼命被需要，直到自己把自己榨干。但权杖十逆位说：需要你的，不是因为你有多能干，是因为你是你。

【走向与影响】你怕的是「放手等于不爱」。权杖十逆位提醒你：你真正怕的，可能是被说不負责任。心理层面的突破，是接纳——放下不是放弃，是分配。`,
  spiritLayer: `宇宙在等你学会「空着也值得」。你不需要扛着全世界，你只需要扛着自己。空了，才能装新的东西。\n\n核心启示：你怕的不是空，是你怕空了之后，发现自己根本不认识那个不扛事的自己。

能量没有散，是聚在「该放手」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「不撿」的小事：选一件你一直扛着、其实可以放下的担子，今天不撿起来。检查你的「行囊」：权杖十逆位问你——你放下的，是为了轻装还是为了逃？`,
  masterSummary: `想动走势，先认「该放手」这道结——真正的放下不是你卸了货，是你卸了货之后，还知道自己是谁。 对照第二问：你们之间最大的阻碍，往往是该放未放。权杖十逆位说：放下，才能走得更远。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'wands_11', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（权杖侍从正位）想对你说：走向不是「没有火苗」那种误会式的死局，而是两人的劲还拧在「火苗没有被一起护」上，没一起认、也没一起动。 年轻侍从凝視发芽的权杖；最大的阻碍，是你们对关系的态度不同步——一个已经在冲、一个还在觀望；或热情没有被对方接住，就熄了。权杖侍从说：阻碍是「起点未一起护」；火种需要保护才能成火炬。 你手里拿着权杖，眼睛看着远方。 你若真想推动走势，就从「发芽」开始——轻，但要真。`,
  psychologyLayer: `【关系现状】你们的关系还处于「好奇期」。可能是刚认识，可能是刚心动，可能是你想知道更多关于他的事。你不确定未来，但你对现在很兴奋。权杖侍从问你：你这么兴奋，是真的喜欢他，还是喜欢「喜欢他」的感觉？\n\n【心理层面】你怕的是「付出了没结果」。你以前吃过亏，所以现在想做之前先问值不值得。但你问「这段关系的本质是什么」，其实你真正想问的是：「这次会不会不一样？」\n\n【根源层面】你曾经是那个什么都不想就往前冲的人。冲了几次，摔了几次，你开始学聪明了。但你忘了，聪明的人，往往也最不快乐。权杖侍从说：你摔过，不代表这次也会摔。你越怕，越会招来怕的结果。

【走向与影响】你怕的是「三分鐘热度」。权杖侍从正位提醒你：你真正怕的，可能是定性不够。心理层面的突破，是接纳——阻碍往往是「我们没有一起护火」；先让火种在，再談永远。`,
  spiritLayer: `宇宙在等你再当一次孩子。孩子不怕摔，摔了就哭，哭了就站起来。你不站起来，就一直趴着。你站起来，哪怕再摔，也是站着摔的。\n\n核心启示：你怕的不是没结果，是你怕试了之后，发现结果不是你想要的。

就走向而言，两人的气机还绕在「冒险邀請」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「发芽」的小事：做一件纯粹为「好玩」而和对方一起做的事。检查你的「行囊」：权杖侍从问你——你是在探索这段关系，还是在逃避上一段？`,
  masterSummary: `走向的纽子在「冒险邀請」——真正的年轻不是年纪小，是你还敢在摔了之后，说「再来一次」。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是火苗没有一起护。权杖侍从说：火种需要保护才能成火炬。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'wands_11', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（权杖侍从逆位）想对你说：走向被「三分鐘热度或不負责任的冒险」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 火热变流言、热情石沈大海；最大的阻碍，是你们开了很多头没一个堅持、或傳递的消息带誤导。权杖侍从逆位说：阻碍是「灵魂多动症」；别把冲动当夢想。 你手里的权杖掉地上了。 别等对方先示范。今天你先用「定下来」给关系一个可跟的节拍。`,
  psychologyLayer: `【关系现状】你们的关系里你「退缩了」。可能是表白了一半咽回去了，可能是靠近了一步又退了回去。你以为自己是谨慎，但权杖侍从逆位问你：你退的那一步，真的是为了保护自己，还是因为你不信自己值得？\n\n【心理层面】你怕的是「被拒绝」。你太怕了，怕到宁可不要，也不开口。你问「这段关系的本质是什么」，其实你真正想问的是：「他会不会拒绝我？」\n\n【根源层面】你被拒绝过太多次。要糖被拒绝，要抱被拒绝，要爱也被拒绝。你学会了一招：不要，就不会被拒绝。但你也学会了另一招：不要，也就不会有了。权杖侍从逆位说：你退得越远，越安全，也越孤单。

【走向与影响】你怕的是「被说不成熟」。权杖侍从逆位提醒你：你真正怕的，可能是定性。心理层面的突破，是问——我们是在探索，还是在逃避深度？`,
  spiritLayer: `宇宙在等你再伸手一次。伸出去，可能被接住，也可能被推开。但你不伸，就永远不知道手张开是什么感觉。\n\n核心启示：你怕的不是被拒绝，是你怕被拒绝之后，又要面对那个「我不够好」的自己。

若问势头卡在哪，多半是「淺薄」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「定下来」的小事：选一件你为这段关系「开了头却没繼续」的事，今天做一步。检查你的「行囊」：权杖侍从逆位问你——你的热情，是对人还是对「新鮮」？`,
  masterSummary: `「淺薄」松一寸，走向就变一寸——真正的勇敢不是你一直往前冲，是你退了之后，还敢再回来看一眼。 第二问那句仍管用：你们之间最大的阻碍，往往是冲动未成堅持。权杖侍从逆位说：别把冲动当夢想。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'wands_12', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（权杖騎士正位）想对你说：走向不是「没有冲勁」那种误会式的死局，而是两人的劲还拧在「冲的方向或速度不同」上，没一起认、也没一起动。 騎士騎紅馬躍起；最大的阻碍，是你们一个想冲、一个想稳，或冲太快导致冲突、没顧及对方节奏。权杖騎士说：阻碍是「动能未对齊」；在馬蹄騰空時，别忘拉紧韁绳、对齊方向。 你冲过来了。 把力气花在看得见的一步：今天只做「对齊速度」，做完就停。`,
  psychologyLayer: `【关系现状】你们的关系正在「冲刺」。可能是热恋期，可能是你们都在用力。你觉得很有激情，但权杖骑士问你：你这么急，是要去哪？\n\n【心理层面】你怕的是「停下来就凉了」。你拼命维持热度，拼命制造新鲜感，生怕一停就回到平淡。你问「这段关系的本质是什么」，其实你真正想问的是：「能不能永远这么热？」\n\n【根源层面】你见过太多关系从热变冷，从冷变没。你怕自己也那样，所以一直跑，不敢停。但你忘了，跑得越快，消耗得越快。跑不动那天，还是会停。权杖骑士说：停之前，你想没想过停下来之后的事？

【走向与影响】你怕的是「一慢就输」。权杖騎士正位提醒你：你真正怕的，可能是错过。心理层面的突破，是接纳——速度是武器也是陷阱；一起冲，但要对齊。`,
  spiritLayer: `宇宙在等你学会「不跑的时候怎么爱」。真正的爱不是冲刺，是散步。两个人慢慢走，才能看见路边的花，才能听见对方呼吸的声音。\n\n核心启示：你怕的不是跑不动，是你怕一停，发现根本没人等你。

就走向而言，两人的气机还绕在「热血」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「对齊速度」的小事：和对方说一句——「你觉得我们这段关系，现在最適合的节奏是_____？」检查你的「行囊」：权杖騎士问你——你冲的，是爱还是征服欲？`,
  masterSummary: `走向的纽子在「热血」——真正的冲刺不是你一直在跑，是你跑的时候，知道有人和你一起跑。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是动能未对齊。权杖騎士说：一起冲，但要拉紧韁绳。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'wands_12', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（权杖騎士逆位）想对你说：走向被「失速或莽撞」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 紅馬失控、騎士面臨墜落；最大的阻碍，是你们其中一人过度冲动、爭執、或「为了赢而赢」——那不叫冲刺，叫自毀。权杖騎士逆位说：阻碍是「焦慮的破壞力」；若速度超出掌控，先拉韁绳。 你摔了。 影响走向不靠喊话，靠落地。今天完成「減速」，再谈别的。`,
  psychologyLayer: `【关系现状】你们的关系里你「失控了」。可能是你冲动做错事，可能是你说错话，可能是你搞砸了。你觉得是自己运气不好，但权杖骑士逆位问你：你冲的时候，有没有看一眼脚下那些石头？\n\n【心理层面】你怕的是「一次失误毁所有」。你太怕了，所以越来越不敢动。但你不动的结果，和动了之后摔了，是一样的——你还是在原地。你问「这段关系的本质是什么」，其实你真正想问的是：「还能不能重来？」\n\n【根源层面】你从小到大都是个「急脾气」。想做的事立刻做，想说的话立刻说。快是快，但也经常摔。你摔怕了，现在开始怀疑自己。但权杖骑士逆位说：摔不是问题，问题是你摔了之后，有没有学会看路。

【走向与影响】你怕的是「一慢就输」。权杖騎士逆位提醒你：你真正怕的，可能是用速度掩蓋方向错誤。心理层面的突破，是问——我们是在冲向彼此，还是逃开什么？控制脾气。`,
  spiritLayer: `宇宙在等你学会「慢下来」。快，不一定好；慢，不一定差。你试试走几步，看看路边，看看脚下。你会发现，那些你以前没看见的东西，其实一直在那。\n\n核心启示：你怕的不是摔，是你怕摔了之后，再也没有勇气站起来跑。

能量没有散，是聚在「失速」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「減速」的小事：选一件你习惯「立刻反應」的事，今天先停三十秒再回應。检查你的「行囊」：权杖騎士逆位问你——你冲的，是爱还是脾气？`,
  masterSummary: `想动走势，先认「失速」这道结——真正的慢不是你故意不走，是你走的时候，知道自己在走。 对照第二问：你们之间最大的阻碍，往往是失速。权杖騎士逆位说：失速不是冲刺，是自毀。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'wands_13', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（权杖皇后正位）想对你说：走向不是「没有光」那种误会式的死局，而是两人的劲还拧在「光没有相互照亮」上，没一起认、也没一起动。 皇后持权杖与向日葵；最大的阻碍，是你们其中一人用強勢、控制、或「我才是对的」壓过对方——或一方一直发光、一方一直陰影。权杖皇后说：阻碍是「单向的太陽」；爱是相互照亮，不是谁照亮谁。 你坐在王座上，手里拿着向日葵，脸上有光。 影响走向不靠喊话，靠落地。今天完成「发光不灼伤」，再谈别的。`,
  psychologyLayer: `【关系现状】你们的关系里你「自成一派」。你不靠他给安全感，不靠他给肯定。你有自己的光，自己的火，自己的热。权杖王后问你：你这么亮，是想照亮他，还是想照亮自己？\n\n【心理层面】你怕的是「太亮了会烧到自己」。你一直给，给温暖，给热情，给能量。但你也会累，也会需要被照亮。你问「这段关系的本质是什么」，其实你真正想问的是：「我给了这么多，他会给我吗？」\n\n【根源层面】你从小就习惯当那个「照顾人」的角色。爸妈忙，你照顾自己；朋友累，你安慰他们；恋爱了，你温暖对方。你把给当成了爱，但你忘了，一直给的人，早晚会枯。权杖王后说：你先给自己，再给别人。你不是太阳，你是需要充电的人。

【走向与影响】你怕的是「一软就灼伤」。权杖皇后正位提醒你：你真正怕的，可能是失去主导。心理层面的突破，是接纳——阻碍往往是「我们没有相互照亮」；你本身就是光，但别灼伤对方。`,
  spiritLayer: `宇宙在等你先把自己照亮。你不亮，给的也是冷的。你亮了，不用给，别人也会围过来。因为光，是吸引人的。\n\n核心启示：你怕的不是他不爱你，是你怕爱了自己之后，就没力气爱他了。

就走向而言，两人的气机还绕在「女性力量」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「发光不灼伤」的小事：在关系里做一件「为自己」的事，但不壓过对方。检查你的「行囊」：权杖皇后问你——你是在照亮对方，还是燒尽自己？`,
  masterSummary: `走向的纽子在「女性力量」——真正的光是先把自己点亮，然后顺便照亮别人。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是光没有相互照亮。权杖皇后说：你本身就是光，别灼伤人。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'wands_13', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（权杖皇后逆位）想对你说：走向被「自我价值感坍塌或極度虛榮嫉妒」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 向日葵枯萎、黑貓露爪；最大的阻碍，是你们其中一人用戲剧化、打壓、或情绪控制取代了爱——不先照亮自己，热度只会灼伤人。权杖皇后逆位说：阻碍是「內在匱乏」；先照亮自己，再照别人。 你的火快灭了，但你还在往外给。 把力气花在看得见的一步：今天只做「收爪」，做完就停。`,
  psychologyLayer: `【关系现状】你们的关系里你「透支了」。你一直在给，给到他都习惯了，给到自己都快没了。你觉得委屈，但说不出口，因为你说过「我不需要」。权杖王后逆位问你：你真的不需要，还是不敢要？\n\n【心理层面】你怕的是「一要就输了」。你一直给，是因为给的人高高在上，收的人矮一头。你不想矮，所以一直给，给到死为止。你问「这段关系的本质是什么」，其实你真正想问的是：「我能不能也收一次？」\n\n【根源层面】你从小就被夸「懂事」。懂事的你，不需要；懂事的你，自己来。你把「不需要」当成了美德，但你不知道，真正的美德是：需要的时候敢说出来。权杖王后逆位说：你说出来，不会死的，可能还会有人帮你。

【走向与影响】你怕的是「不被看见」。权杖皇后逆位提醒你：你真正怕的，可能是用強勢掩蓋脆弱。心理层面的突破，是问——我们是在爭取被爱，还是控制对方？先与內心陰影相處。`,
  spiritLayer: `宇宙在等你开口要一次。一次就好。要一个拥抱，要一句安慰，要一杯水。你要了，天不会塌，反而会有人递过来。\n\n核心启示：你怕的不是要不到，是你怕要到了之后，发现自己没那么「懂事」。

若问势头卡在哪，多半是「情绪控制」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「收爪」的小事：选一件你习惯「用強勢表达」的事，今天用柔软的方式说。检查你的「行囊」：权杖皇后逆位问你——你要的是爱，还是被崇拜？`,
  masterSummary: `「情绪控制」松一寸，走向就变一寸——真正的暖不是一直往外给，是你冷的时候，也敢让人给你披件衣服。 第二问那句仍管用：你们之间最大的阻碍，往往是內在匱乏。权杖皇后逆位说：不先照亮自己，热度只会灼伤人。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'wands_14', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（权杖国王正位）想对你说：走向不是「没有領导」那种误会式的死局，而是两人的劲还拧在「領导变成独裁」上，没一起认、也没一起动。 国王坐宝座权杖直立；最大的阻碍，是你们其中一人过度主导、不听对方、用权威壓制——关系需要结構，但权威在臥室里会成障碍。权杖国王说：阻碍是「单向的权威」；領袖的责任是照亮他人的路，不是壓制。 你坐在王座上，手里拿着权杖，不是用来打的，是用来指的。 别等对方先示范。今天你先用「傾听」给关系一个可跟的节拍。`,
  psychologyLayer: `【关系现状】你们的关系里你「领路」。你比他成熟，比他果断，比他看得远。你带他走，带他跳，带他过河。你习惯了当那个指路的人，但权杖国王问你：你指的路，是他想走的吗？\n\n【心理层面】你怕的是「他不跟了」。你领路领惯了，觉得理所当然。但你不知道，他一直跟着，不是因为你路指得好，是因为他信任你。你问「这段关系的本质是什么」，其实你真正想问的是：「我还能领多久？」\n\n【根源层面】你从小就是那个「领头的」。家里的事你领头，学校的事你领头，工作的事你领头。你把领头当成了习惯，当成了责任。但权杖国王说：领路的人，也要看路，也要等后面的人。你一直走，忘了回头，后面的人可能已经丢了。

【走向与影响】你怕的是「一软就亂」。权杖国王正位提醒你：你真正怕的，可能是失控。心理层面的突破，是接纳——用成熟引領爱人，给安全感；但學会傾听，权威在臥室里只会成障碍。`,
  spiritLayer: `宇宙在等你慢下来一次。不用跑那么快，等等他。让他走几步，让你看看他也能领路。你会发现，他也能的。\n\n核心启示：你怕的不是他跟不上，是你怕他跟上之后，发现你其实也不知道去哪。

这条关系的走势，眼下还拴在「权威」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「傾听」的小事：选一件你习惯「直接拍板」的事，今天先问对方：「你觉得呢？」检查你的「行囊」：权杖国王问你——你是在带領，还是在控制？`,
  masterSummary: `势头绕在「权威」上——真正的领路不是你一直走在前头，是你走的时候，知道后面有人。 第二问早已点破：你们之间最大的阻碍，往往是单向的权威。权杖国王说：先傾听再指明路。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'wands_14', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（权杖国王逆位）想对你说：走向被「暴君或極度固執」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 火蜥蜴变毒蛇；最大的阻碍，是你们其中一人听不进意见、用权威壓人、或只懂征服不懂守护——帝国会在怒火中崩塌。权杖国王逆位说：阻碍是「自我毀滅式擴张」；只懂征服不懂守护，帝国会崩塌。 你坐在王座上，但王座歪了。 你若真想推动走势，就从「让权」开始——轻，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里你「独裁了」。你说了算，他跟着走。你以为这是爱，其实是控制。权杖国王逆位问你：你指的路，是他想走的，还是你逼他走的？\n\n【心理层面】你怕的是「他不跟了」。所以你拼命指路，拼命证明自己是对的。但你不知道，跟久了的人，也会累。你问「这段关系的本质是什么」，其实你真正想问的是：「我还能指多久？」\n\n【根源层面】你从小就是那个「说了算」的人。没人问过你想不想，所以你也不知道怎么问别人。权杖国王逆位说：领路的人，也要回头。你不回头，后面的人就丢了。

【走向与影响】你怕的是「一软就失控」。权杖国王逆位提醒你：你真正怕的，可能是失去掌控。心理层面的突破，是问——我们是在带領关系，还是壓制对方？权威在臥室里只会成障碍。`,
  spiritLayer: `宇宙在等你回头看一眼。不用一直指路，等等他，问一句：「你还跟吗？」\n\n核心启示：你怕的不是他跟不上，是你怕一回头，发现后面早就没人了。

若问势头卡在哪，多半是「高處不勝寒的偏執」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「让权」的小事：选一件你习惯「我说了算」的事，今天让对方做决定。检查你的「行囊」：权杖国王逆位问你——你要的是共同王国，还是唯我独尊？`,
  masterSummary: `「高處不勝寒的偏執」松一寸，走向就变一寸——真正的国王不是一直指路，是你敢回头问一句：你还跟吗？ 第二问那句仍管用：你们之间最大的阻碍，往往是权威的错用。权杖国王逆位说：只懂征服不懂守护，帝国会崩塌。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'cups_1', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（圣杯一正位）想对你说：走向不是「没有爱」那种误会式的死局，而是两人的劲还拧在「心没有敞开」上，没一起认、也没一起动。 雲端手托溢出的圣杯；最大的阻碍，是你们其中一人或两人关上了心门——不敢给、不敢收、或爱没有以活水的方式流动。圣杯一说：阻碍是「杯子未敞开」；当你內心丰盛，活水才流得出去。 云中伸出一只手，托着一个满溢的圣杯。 别等对方先示范。今天你先用「敞开」给关系一个可跟的节拍。`,
  psychologyLayer: `【关系现状】你们的关系刚开始，或者刚有情感的涌动。你觉得心里满满的，想给，想分享，想把他填满。但圣杯王牌问你：你这么满，是真的满，还是因为终于有人来接了，所以你才发现自己原来有这么多？\n\n【心理层面】你怕的是「给了就没了」。你一直渴，一直等，一直以为自己是空的。现在有个人来，你发现原来自己也有水。你拼命给，生怕不给就没了。但圣杯王牌告诉你：你是泉眼，不是水库。给不完的，越给越多。你问「这段关系的本质是什么」，其实你真正想问的是：「我能给他吗？给了之后我还有吗？」\n\n【根源层面】你从小就被教育「爱是有限的」。爱给出去就少了，所以要省着点用。所以你一直收着，收着，收着，收到自己都不知道自己有多少。现在有人让你打开，你慌了。但圣杯王牌说：爱是越给越多的。你试试，倒出去一点，它还会满回来。

【走向与影响】你怕的是「付出后落空」。圣杯一正位提醒你：你真正怕的，可能是受伤。心理层面的突破，是接纳——空杯无法斟酒，先學会爱自己，你给出的爱才不会变成索取。`,
  spiritLayer: `宇宙在等你学会「给」。你不是没有，你是不敢。现在你面前有个人，愿意接你的水。你倒吧，倒了才知道，原来你是井。\n\n核心启示：你怕的不是他没水，是你怕自己有水，却一直不敢倒。

能量没有散，是聚在「情感觉醒」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「敞开」的小事：对一个你关心的人说一句溫暖、不带目的的关怀。检查你的「行囊」：圣杯一问你——你给的，是丰盛还是索取？`,
  masterSummary: `想动走势，先认「情感觉醒」这道结——真正的爱不是你从他那里得到多少，是你敢把自己的水倒给他，还不怕自己会干。 对照第二问：你们之间最大的阻碍，往往是心未敞开。圣杯一说：內心丰盛，爱才流得出去。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'cups_1', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（圣杯一逆位）想对你说：走向被「情感的枯竭或拒绝感受」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 圣杯翻覆、活水流失；最大的阻碍，是你们其中一人关上了心门、或告白被拒、灵感枯竭——你试图向外索取爱填补缺口，源头却在你心里。圣杯一逆位说：阻碍是「空杯」；先填滿自己的杯子。 圣杯歪了，水洒了一地。 你若真想推动走势，就从「自爱」开始——轻，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里你「枯了」。你给过太多，给到现在什么都没了。你觉得委屈，觉得不值，觉得是他把你吸干的。但圣杯王牌逆位问你：你给的时候，有没有想过自己也要加一点？\n\n【心理层面】你怕的是「不给就没人爱」。你把给当成了爱的唯一方式，给了，才觉得自己值得。但你现在给空了，没人给了，你就觉得自己不值得了。你问「这段关系的本质是什么」，其实你真正想问的是：「我都给完了，他怎么还不给我？」\n\n【根源层面】你从小就是那个「听话的孩子」。听话，是因为想被爱。你把爱和付出划了等号，以为付出就有爱。但圣杯王牌逆位说：付出不是爱，付出是付出。爱是你给了，还能收到。

【走向与影响】你怕的是「再敞开会再伤」。圣杯一逆位提醒你：你真正怕的，可能是受伤后不敢再给。心理层面的突破，是问——我们是先填滿自己的杯子，还是一直在討？`,
  spiritLayer: `宇宙在等你先给自己倒一杯。你不倒，就永远空着。空了，别人想给你都没地方接。\n\n核心启示：你怕的不是给空，是你怕自己空了之后，就没人要了。

若问势头卡在哪，多半是「拒绝感受」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「自爱」的小事：对镜子里的自己说一声「我爱你，辛苦了」。检查你的「行囊」：圣杯一逆位问你——你关上心门，是保护还是逃避？`,
  masterSummary: `「拒绝感受」松一寸，走向就变一寸——真正的爱不是你一直往外倒，是你倒了之后，还敢收别人倒给你的。 第二问那句仍管用：你们之间最大的阻碍，往往是空杯。圣杯一逆位说：先填滿自己的杯子。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'cups_2', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（圣杯二正位）想对你说：走向不是「没有连结」那种误会式的死局，而是两人的劲还拧在「杯子没有举到同一高度」上，没一起认、也没一起动。 男女举杯、荷米斯之杖在上；最大的阻碍，是关系失衡——一方给太多、一方收太多；或頻率失联、貌合神離。圣杯二说：阻碍是「施与受未对等」；两个圣杯要举到同一高度，爱才流动。 你们面对面站着，手里各捧一个杯子，碰在一起。 你能拧动的开关往往在细节：今天把「对視」做实，比分析十句有用。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「平等」。不是谁追谁，不是谁给谁，是两个人同时往前走了一步。你觉得自己被看见了，他也觉得自己被看见了。圣杯二问你：你看见的，是真正的他，还是你想象中的他？\n\n【心理层面】你怕的是「看错了」。你太想有个人能和你碰杯，所以看见谁都像对的人。但现在他真的来了，你反而不敢信。你问「这段关系的本质是什么」，其实你真正想问的是：「他是真的吗？还是我幻想出来的？」\n\n【根源层面】你太渴望被理解了。从小就觉得没人懂你，没人接得住你的情绪。现在有个人愿意接，你反而慌了，怕接不住。但圣杯二说：你不是要别人接，你是要两个人一起碰。

【走向与影响】你怕的是「平衡会打破」。圣杯二正位提醒你：你真正怕的，可能是失去。心理层面的突破，是接纳——真正的力量来自连结；誠实表达，尊重彼此，现在是合一的時刻。`,
  spiritLayer: `宇宙在等你信一次。信他是真的，信你是真的，信你们碰在一起的这一刻是真的。这一刻，就是永恒。\n\n核心启示：你怕的不是他不真，是你怕自己信了之后，发现信错了。

就走向而言，两人的气机还绕在「灵魂共鳴」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「对視」的小事：邀請对方一次「不带手机」的深度相處，专注于彼此的眼神与語气。检查你的「行囊」：圣杯二问你——你们的杯子，是对等举起还是一高一低？`,
  masterSummary: `走向的纽子在「灵魂共鳴」——真正的平等不是谁多谁少，是你伸出手的时候，他也伸了。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是杯子没有举到同一高度。圣杯二说：合一。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'cups_2', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（圣杯二逆位）想对你说：走向被「頻率失联或关系失衡」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 圣杯墜落、獅子头冷漠；最大的阻碍，是沟通变爭吵、信任瓦解、或一方卑微乞求关注——若需要不斷犧牲尊嚴維持，那是寄生不是互补。圣杯二逆位说：阻碍是「单向依附」；别用碎掉的杯子装爱。 你们站着，杯子在手里，但眼睛看向别处。 今天用「对表」替关系试温：你动了，场的流向才会跟着变。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「疏远」。不是不爱，是爱了但不看。你等他主动，他等你主动，等到杯子里的水都凉了。圣杯二逆位问你：你等的是什么？等他先爱你，还是等他先认输？\n\n【心理层面】你怕的是「先动就输了」。你太怕输，所以宁愿不赢，也不先动。你问「这段关系的本质是什么」，其实你真正想问的是：「我能不能不主动，还能有爱？」\n\n【根源层面】你从小就学会了「谁先动谁就错」。家里的事，先开口的挨骂；朋友的事，先低头的认输。你把这套带进了爱情，以为爱情也是战场。但圣杯二逆位说：爱情不是战场，是舞场。你先迈一步，他才会跟着你转。

【走向与影响】你怕的是「承认不平衡」。圣杯二逆位提醒你：你真正怕的，可能是失去对方。心理层面的突破，是问——我们是在互补，还是一方在吸血？`,
  spiritLayer: `宇宙在等你迈那一步。迈了，可能被踩到，也可能舞起来。但你不迈，就一直站着，站到音乐结束。\n\n核心启示：你怕的不是他不爱，是你怕自己爱了之后，发现他不值得。

这条关系的走势，眼下还拴在「破裂」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「对表」的小事：和对方确认一次——「我们这段关系，双方觉得平衡吗？」检查你的「行囊」：圣杯二逆位问你——你留着，是爱还是怕没人爱？`,
  masterSummary: `势头绕在「破裂」上——真正的看见不是你等他看，是你先转过头，让他看见你的眼睛。 第二问早已点破：你们之间最大的阻碍，往往是单向依附。圣杯二逆位说：单向依附不是爱。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'cups_3', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（圣杯三正位）想对你说：走向不是「没有喜悅」那种误会式的死局，而是两人的劲还拧在「喜悅没有被一起分享」上，没一起认、也没一起动。 三女举杯共舞；最大的阻碍，是你们的快樂建立在「演给别人看」或「只有一方在慶祝」——关系没有融入真正的社群、或你们在热闹中孤寂。圣杯三说：阻碍是「共舞未成」；分享喜悅，丰盛才会加倍。 你们三个围在一起，举着杯子，笑着，跳着。 走向听行动。今天只兑现「共舞」——让对方看见你在动，而不是在讲。`,
  psychologyLayer: `【关系现状】你们的关系里有「快乐」。可能是一起玩的朋友，可能是能一起疯的恋人。你不用装，不用演，想笑就笑，想闹就闹。圣杯三问你：你在他面前，能笑成小孩吗？\n\n【心理层面】你怕的是「笑完了就没了」。你太怕失去，所以不敢全情投入。你笑一半，留一半，怕万一以后哭了，自己太难看。你问「这段关系的本质是什么」，其实你真正想问的是：「我们能一直这么开心吗？」\n\n【根源层面】你从小就被教「乐极生悲」。开心的时候不要太过，否则会倒霉。你把这句话刻在脑子里，所以每次开心都掐自己一下，提醒自己别太快乐。但圣杯三说：快乐不会带来悲伤，悲伤本来就在，只是你快乐的时候忘了它。你现在忘了，就好好忘，别急着想回来。

【走向与影响】你怕的是「热闹是假的」。圣杯三正位提醒你：你真正怕的，可能是被孤立。心理层面的突破，是接纳——喜悅是灵魂的肥料；让关系融入社交，分享快樂。`,
  spiritLayer: `宇宙在等你全情投入一次。不防着，不怕着，不计算着。就笑，笑到肚子疼，笑到流眼泪。笑完之后你会发现，世界没塌。\n\n核心启示：你怕的不是笑完会哭，是你怕哭了之后，再也笑不出来了。

若问势头卡在哪，多半是「社群支持」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「共舞」的小事：組織一次小型聚会或和对方做一件「纯开心」的事，不談壓力只談存在。检查你的「行囊」：圣杯三问你——你们的慶典，是两个人的还是别人定义的？`,
  masterSummary: `「社群支持」松一寸，走向就变一寸——真正的快乐不是你一直笑，是你敢笑的时候，不怕以后哭。 第二问那句仍管用：你们之间最大的阻碍，往往是喜悅没有一起分享。圣杯三说：分享喜悅。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'cups_3', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（圣杯三逆位）想对你说：走向被「社交消耗或小圈子排擠」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 杯子碎裂、舞步混亂；最大的阻碍，是虛假狂欢、背后流言、或「三人行」的尷尬——别让酒精与空談掏空灵魂。圣杯三逆位说：阻碍是「社交宿醉」；若只追求热闹而忽視独處，会被雜音淹没。 你们散了。 你要影响走向，今天就卡这一格：把「減噪」做到底，小不要紧，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「孤独」。可能是一群人在一起，但你觉得只有自己；可能是他就在身边，但你觉得隔着墙。你笑着，闹着，但心里是空的。圣杯三逆位问你：你笑给谁看？\n\n【心理层面】你怕的是「被落下」。你拼命参与，拼命融入，拼命表现自己很快乐，怕他们看出你不快乐。但你越演，越累。你问「这段关系的本质是什么」，其实你真正想问的是：「他们是真的爱我，还是只是需要我演？」\n\n【根源层面】你从小就学会了「讨喜」。讨喜的人，才有人喜欢；不讨喜的人，没人要。所以你一直演，一直笑，一直让别人舒服。但圣杯三逆位说：你把自己演丢了，谁还记得你是谁？

【走向与影响】你怕的是「没人祝福」。圣杯三逆位提醒你：你真正怕的，可能是被孤立。心理层面的突破，是问——我们追求的是表面热闹，还是心灵的独處与真实连结？`,
  spiritLayer: `宇宙在等你停下来。不演了，不笑了，不装了。就一个人待着，感受那个空。你会发现，空里面，也有东西。\n\n核心启示：你怕的不是一个人，是你怕一个人之后，发现自己根本不认识那个不演的自己。

能量没有散，是聚在「社交宿醉」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「減噪」的小事：和对方约定一段「不應酬、不表演」的独處時间，只談两个人。检查你的「行囊」：圣杯三逆位问你——你们的快樂，是演给别人看还是真的？`,
  masterSummary: `想动走势，先认「社交宿醉」这道结——真正的陪伴不是一群人围着你，是你一个人待着的时候，还能对自己笑。 对照第二问：你们之间最大的阻碍，往往是社交宿醉。圣杯三逆位说：别让空談掏空灵魂。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'cups_4', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（圣杯四正位）想对你说：走向不是「没有机会」那种误会式的死局，而是两人的劲还拧在「心太擠看不见」上，没一起认、也没一起动。 男子坐树下无視面前三杯与雲端第四杯；最大的阻碍，是你们其中一人或两人进入倦怠、对现状索然无味、或宇宙递来的第四个杯子你们没抬头接。圣杯四说：阻碍是「厭倦与忽視」；心太擠就清空，别因盯着旧杯子错过新的活水。 你面前有三个杯子，天上还有一个杯子递过来。 你要影响走向，今天就卡这一格：把「抬头」做到底，小不要紧，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「不满足」。可能是他做得够好了，但你总觉得差点什么；可能是这段感情挺好的，但你总在想会不会有更好的。圣杯四问你：你要的，到底是什么？\n\n【心理层面】你怕的是「就这个了」。你怕一满足，就再也没机会得到更好的了。所以你不满足，不快乐，不错过。你问「这段关系的本质是什么」，其实你真正想问的是：「他是不是最好的？还有没有更好的？」\n\n【根源层面】你从小就活在被比较里。成绩要比，玩具要比，连爱也要比。你习惯了「更好的」这个念头，永远在找，永远不满足。但圣杯四说：你再找，也找不到一个完美的。完美的只在你心里。

【走向与影响】你怕的是「承认倦了」。圣杯四正位提醒你：你真正怕的，可能是没了这段关系就什么都没了。心理层面的突破，是问——我们是没机会，还是心太擠看不见？`,
  spiritLayer: `宇宙在等你低头看一眼。你低下去，看见的不是地上的灰，是你面前那三个杯子。它们一直在那，你从来没认真看过。\n\n核心启示：你怕的不是不够好，是你怕够了之后，再也没有东西追了。

就走向而言，两人的气机还绕在「內省闭锁」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「抬头」的小事：对一个你平時都会拒绝的、对方的小提議说「好」。检查你的「行囊」：圣杯四问你——你厭倦的，是关系还是自己？`,
  masterSummary: `走向的纽子在「內省闭锁」——真正的满足不是你得到了最好的，是你终于看见，你手里已经有了。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是心太擠看不见第四个杯子。圣杯四说：心太擠就清空。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'cups_4', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（圣杯四逆位）想对你说：走向被「从倦怠中甦醒未完成」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 男子抬头看见第四杯；最大的阻碍，是你们突然接受原本不看好的机会、或结束自怨自艾，但世界一直在等，只是你之前闭上眼——有時急于填补空虛会再跳进坑里。圣杯四逆位说：阻碍是「觉醒的陣痛」；别让傲慢与迟鈍毀了下一场好運。 你抬头了。 走向听行动。今天只兑现「接受」——让对方看见你在动，而不是在讲。`,
  psychologyLayer: `【关系现状】你们的关系里有一个「机会」。可能是他主动了，可能是你想通了，可能是你们要往前走了。你看见了，但你还在犹豫。圣杯四逆位问你：你还在等什么？等一个更完美的时机？\n\n【心理层面】你怕的是「接了之后后悔」。你太怕选错了，所以连机会摆在面前也不敢伸手。你问「这段关系的本质是什么」，其实你真正想问的是：「这次接对了，会不会下次有更好的？」\n\n【根源层面】你太会挑了。买东西要挑，工作要挑，连爱人都要挑。你挑花了眼，挑累了，但还是不敢下手。但圣杯四逆位说：你挑的不是最好的，你挑的是你敢接的。敢接的，就是最好的。

【走向与影响】你怕的是「改变会更糟」。圣杯四逆位提醒你：你真正怕的，可能是醒来后要面对。心理层面的突破，是接纳——世界一直在等你，睜开眼。`,
  spiritLayer: `宇宙在等你伸手。伸了，可能接住，也可能接不住。但你不伸，就永远空着手。\n\n核心启示：你怕的不是接错，是你怕接了之后，再也没机会挑了。

就走向而言，两人的气机还绕在「该醒未醒」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「接受」的小事：选一件你曾经拒绝的、关于这段关系的提議，重新考慮一次。检查你的「行囊」：圣杯四逆位问你——你醒来，是为了爱还是逃離无聊？`,
  masterSummary: `走向的纽子在「该醒未醒」——真正的看见不是你终于抬头，是你抬头之后，还敢伸手。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是未从倦怠中抬头。圣杯四逆位说：世界一直在等。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'cups_5', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（圣杯五正位）想对你说：走向不是「没有爱过」那种误会式的死局，而是两人的劲还拧在「对失去的过度執着」上，没一起认、也没一起动。 黑衣人低头看打翻的三杯、没看见身后两杯；最大的阻碍，是你们其中一人或两人反芻分手細节、困在过去陰影、不肯转身看见剩下的。圣杯五说：阻碍是「沈溺遺憾」；失去是事实但不是全部，转身需要勇气，那是唯一出路。 你低着头，看着地上倒了的三个杯子。 今天用「转身」替关系试温：你动了，场的流向才会跟着变。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「失去感」。可能是失去了信任，可能是失去了激情，可能是失去了一个人。你沉浸在失去里，看不见还有什么是剩下的。圣杯五问你：你还要看这三个倒的，看多久？\n\n【心理层面】你怕的是「什么都没了」。你把失去当成了全部，以为没了就是没了。但你不知道，失去的旁边，还有留下的。你问「这段关系的本质是什么」，其实你真正想问的是：「我还能好起来吗？」\n\n【根源层面】你从小就怕失去。失去一个玩具，哭一天；失去一个朋友，记一辈子。你把失去刻得太深，深到忘了，失去的后面，还有得到的。圣杯五说：你回头看的那一眼，可能就能看见，还有两个杯子，满满的。

【走向与影响】你怕的是「忘记等于背叛」。圣杯五正位提醒你：你真正怕的，可能是放下就什么都没了。心理层面的突破，是接纳——允許悲伤，但别让悲伤定义一生。`,
  spiritLayer: `宇宙在等你回头。不回头，你就一直盯着那滩水；回头了，你就能看见，还有人站在你身后。\n\n核心启示：你怕的不是失去，是你怕失去了之后，再也没有了。

这条关系的走势，眼下还拴在「沈溺遺憾」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「转身」的小事：處理掉一件「代表过去伤痛」的实體物品，或对自己说「那件事已经结束了，我还拥有现在」。检查你的「行囊」：圣杯五问你——你盯着的，是打翻的三杯还是身后的两杯？`,
  masterSummary: `势头绕在「沈溺遺憾」上——真正的失去不是你倒了三个，是你忘了身后还有两个。 第二问早已点破：你们之间最大的阻碍，往往是对失去的过度執着。圣杯五说：转身看见身后的杯子。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'cups_5', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（圣杯五逆位）想对你说：走向被「从伤痛中解套未完成」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 黑衣人转身看见剩下两杯；最大的阻碍，是你们决定止損、停止自艾自怜、或终于原諒，但别在廢墟上蓋紀念館——往前走才有活路。圣杯五逆位说：阻碍是「復原期的臨界点」；转身需要巨大勇气，但那是唯一出路。 你开始回头了。 你能拧动的开关往往在细节：今天把「止損」做实，比分析十句有用。`,
  psychologyLayer: `【关系现状】你们的关系里有一个「转折」。可能是你终于不哭了，可能是你终于决定往前走了。你回头了，看见了还在的，但你还不知道下一步怎么走。圣杯五逆位问你：看见了，然后呢？\n\n【心理层面】你怕的是「看见了也不会更好」。你回头了，但心里还是空。你以为看见还在的就能满，但发现，看见只是看见。你问「这段关系的本质是什么」，其实你真正想问的是：「看见了之后，我能得到什么？」\n\n【根源层面】你一直以为「看见」就是「得到」。小时候看见糖，就以为能吃到；看见玩具，就以为能玩到。你把这个习惯带到现在，以为看见还在的，就能拥有。但圣杯五逆位说：看见是第一步，走过去，才是第二步。

【走向与影响】你怕的是「強颜欢笑」。圣杯五逆位提醒你：你真正怕的，可能是承认还在痛。心理层面的突破，是接纳——不必急着原諒或忘记，先接纳「我现在很痛」。`,
  spiritLayer: `宇宙在等你走过去。你转身了，看见了，然后你还要迈步。走过去，端起来，喝一口。喝下去，你才知道那水是什么味道。\n\n核心启示：你怕的不是看不见，是你怕看见了之后，发现自己还是不知道怎么办。

这条关系的走势，眼下还拴在「该走未走」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「止損」的小事：寫一封「给过去伤痛的悼詞」，理清教訓，然后象徵性刪除或收起。检查你的「行囊」：圣杯五逆位问你——你转身，是为了活还是逃？`,
  masterSummary: `势头绕在「该走未走」上——真正的回头不是你看见了，是你看见之后，还敢走过去。 第二问早已点破：你们之间最大的阻碍，往往是未带着剩下的两杯往前走。圣杯五逆位说：别在廢墟上蓋紀念館。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'cups_6', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（圣杯六正位）想对你说：走向不是「没有纯真」那种误会式的死局，而是两人的劲还拧在「卡在过去不肯长大」上，没一起认、也没一起动。 男孩將装滿鮮花的圣杯交给女孩；最大的阻碍，是你们其中一人或两人过度依賴「以前的好時光」、用回憶麻痹当下、或不愿面对关系需要成长。圣杯六说：阻碍是「沉溺过去导致停滯」；初心是根，但天空才是方向。 你回到了小时候。 你若真想推动走势，就从「初心」开始——轻，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「怀旧」。可能是他让你想起某个人，可能是你们做的事让你想起某段时光。你觉得温暖，但你也知道，回不去了。圣杯六问你：你是在怀念过去，还是在用过去暖现在？\n\n【心理层面】你怕的是「现在不够暖」。你把过去翻出来，一遍一遍回味，因为现在太冷。但你越回味，越觉得现在冷。你问「这段关系的本质是什么」，其实你真正想问的是：「现在能不能像过去一样暖？」\n\n【根源层面】你曾经被好好爱过。那段日子太暖，暖到你现在还舍不得走。你把过去当成了标准，拿现在比，比来比去，现在永远不够好。但圣杯六说：过去是过去的暖，现在是现在的暖。你一直回头看，就看不见眼前的。

【走向与影响】你怕的是「单纯会被利用」。圣杯六正位提醒你：你真正怕的，可能是长大。心理层面的突破，是接纳——珍惜纯粹的悸动，但过去滋养当下，不是取代当下。`,
  spiritLayer: `宇宙在等你把过去装进包里，然后往前走。你带着那些暖，走一段，累的时候拿出来暖一暖。但你一直站在过去，包都打不开。\n\n核心启示：你怕的不是现在不够好，是你怕现在好了之后，就忘了过去。

若问势头卡在哪，多半是「怀旧安全感」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「初心」的小事：联絡一位了解你「最原始面貌」的老朋友，或和对方做一件「小時候会做的事」。检查你的「行囊」：圣杯六问你——你留恋的，是当下的对方还是过去的幻影？`,
  masterSummary: `「怀旧安全感」松一寸，走向就变一寸——真正的怀旧不是你想回去，是你敢把过去装心里，然后往前走。 第二问那句仍管用：你们之间最大的阻碍，往往是卡在过去不肯长大。圣杯六说：过去滋养当下。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'cups_6', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（圣杯六逆位）想对你说：走向被「沉溺过去导致停滯」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 花朵枯萎、莊园大门关上；最大的阻碍，是你们过度依賴、总想回到以前的好時光麻痹自己、或过去的人事物負面干扰——你不能永远穿縮水的衣服。圣杯六逆位说：阻碍是「发展停滯」；未来的路不在身后，請长大。 你困在过去里了。 别等对方先示范。今天你先用「长大」给关系一个可跟的节拍。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「逃避」。你老提以前，老说「我们那时候」。不是那时候多好，是你不想看现在多烂。圣杯六逆位问你：你还要比到什么时候？\n\n【心理层面】你怕的是「现在就是最烂的」。你不敢面对，因为一面对，就要承认可能选错了。所以你拼命美化过去，把现在比下去。你问「这段关系的本质是什么」，其实你真正想问的是：「能不能让现在变成过去？」\n\n【根源层面】你曾经做过一个错误的选择，但你一直不肯认。你把它包装成「命运」，包装成「没办法」，但你知道，那是你选的。圣杯六逆位说：你选了，就认了。认了，才能继续走。不认，就一直在那转圈。

【走向与影响】你怕的是「长大就没了」。圣杯六逆位提醒你：你真正怕的，可能是面对当下的不完美。心理层面的突破，是问——我们是在怀旧还是在逃避长大？`,
  spiritLayer: `宇宙在等你放下过去的那只手。你一只手抓着过去，一只手想抓现在，什么都抓不住。你放了一只，另一只才能抓紧。\n\n核心启示：你怕的不是回不去，是你怕回去了之后，发现根本没那么好。

能量没有散，是聚在「停滯」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「长大」的小事：和对方談一件「我们以前从没认真談过」的现实问题，不逃避。检查你的「行囊」：圣杯六逆位问你——你抓着的，是回憶还是借口？`,
  masterSummary: `想动走势，先认「停滯」这道结——真正的放下不是你忘了，是你敢承认，过去已经过去了。 对照第二问：你们之间最大的阻碍，往往是沉溺过去。圣杯六逆位说：未来的路不在身后。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'cups_7', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（圣杯七正位）想对你说：走向不是「没有选择」那种误会式的死局，而是两人的劲还拧在「选择过剩的幻觉」上，没一起认、也没一起动。 雲端七杯装珠宝、毒蛇、龍；最大的阻碍，是你们沉溺于「所有可能」、多角曖昧、或对未来的宏大空想却没一个落地——在貪婪或恐惧的投影里，不是做决定的好時机。圣杯七说：阻碍是「慾望幻象」；只有一个是真实的，其餘都是消耗。 你站在七朵云前面，每朵云上都有一个杯子，装着城堡、珠宝、龙、蛇。 把力气花在看得见的一步：今天只做「刪減」，做完就停。`,
  psychologyLayer: `【关系现状】你们的关系里充满了「幻想」。你想他变成的样子，你想你们未来的样子，你想这段感情能给你的东西。你想得太多，想得太远，忘了看现在。圣杯七问你：你爱的，是真实的他，还是你梦里的他？\n\n【心理层面】你怕的是「现实太普通」。你把感情想得太好，怕一面对现实，就碎了。所以你一直做梦，一直想，一直不落地。你问「这段关系的本质是什么」，其实你真正想问的是：「他能不能变成我梦里的样子？」\n\n【根源层面】你从小就被故事喂大。王子公主，童话结局，你觉得感情就该那样。但你不知道，故事里的王子，也是要上厕所的。圣杯七说：你把感情当成了童话，但童话的下一页，就是现实。

【走向与影响】你怕的是「选错」。圣杯七正位提醒你：你真正怕的，可能是要了 A 就没了 BCD。心理层面的突破，是问——我们要的是关系，还是「所有可能」？釐清你真正需要的是什么。`,
  spiritLayer: `宇宙在等你落地。你飞得太久了，以为云就是地。但你一直飘，永远落不下来。落了，才能真的走。\n\n核心启示：你怕的不是现实不美，是你怕现实一落地，就再也没法做梦了。

能量没有散，是聚在「慾望幻象」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「刪減」的小事：把所有的择偶或感情期待寫在纸上，強迫自己刪到只剩三个最重要的条件。检查你的「行囊」：圣杯七问你——你要的是眼前人，还是雲端那七杯？`,
  masterSummary: `想动走势，先认「慾望幻象」这道结——真正的爱不是你把他变成梦里的样子，是你敢看他在现实里，还愿意一起走。 对照第二问：你们之间最大的阻碍，往往是选择过剩的幻觉。圣杯七说：只有一个是真实的。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'cups_7', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（圣杯七逆位）想对你说：走向被「被迫清醒或幻滅后的专注」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 雲雾散去、杯子墜地；最大的阻碍，是你们看清陷阱、结束混亂曖昧、或承认宏大计画只是白日夢——雖然清醒痛苦，但让你不再为幻影奔跑；真实的土地雖貧瘠，却可耕耘。圣杯七逆位说：阻碍是「排除法」；别再往雲端看，低头看路。 云散了。 影响走向不靠喊话，靠落地。今天完成「落地」，再谈别的。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「幻灭」。可能是他的真面目露出来了，可能是你们的未来不如你想的那样。你觉得被骗了，但你不知道，骗你的不是他，是你自己的幻想。圣杯七逆位问你：现在没得幻想了，你还爱吗？\n\n【心理层面】你怕的是「他就是这样的人」。你一直把他想成别的样子，现在终于看见了，但你不接受。你问「这段关系的本质是什么」，其实你真正想问的是：「他能不能变回去？」\n\n【根源层面】你太会给自己讲故事了。从小到大，你把世界讲成你想要的样子。现在故事破了，你疼，但也终于能看见真的了。圣杯七逆位说：真的，可能不如故事好看，但真的，是能摸到的。

【走向与影响】你怕的是「清醒后一无所有」。圣杯七逆位提醒你：你真正怕的，可能是面对现实。心理层面的突破，是接纳——清醒是痛苦的，但它让你专注。`,
  spiritLayer: `宇宙在等你接受真实。它不完美，不童话，但它就在这。你接受了，才能往下走。\n\n核心启示：你怕的不是他不够好，是你怕自己看错了人。

这条关系的走势，眼下还拴在「该落地未落地」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「落地」的小事：选一件你一直幻想「如果……就……」的事，找出一个现在就能开始的替代方案並做一步。检查你的「行囊」：圣杯七逆位问你——你醒来，是为了爱还是不再失望？`,
  masterSummary: `势头绕在「该落地未落地」上——真正的清醒不是你梦醒了，是你醒了之后，还敢睁眼看。 第二问早已点破：你们之间最大的阻碍，往往是幻滅后未落地。圣杯七逆位说：真实的土地可以耕耘。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'cups_8', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（圣杯八正位）想对你说：走向不是「没有學到」那种误会式的死局，而是两人的劲还拧在「该離开的未離开」上，没一起认、也没一起动。 一人背对八杯夜里走向远方；最大的阻碍，是你们其中一人或两人不敢離开舒適區、不敢结束该结束的、或用「再忍一下」代替「带着學到的離开」——離开需要勇气，不離开有時也需要；想清楚再动。圣杯八说：阻碍是「未完成的離开」；带着學到的东西離开，而非两手空空。 你转身走了。 影响走向不靠喊话，靠落地。今天完成「清点」，再谈别的。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「结束感」。可能是你累了，可能是你醒了，可能是你终于决定走了。你回头看那些一起走过的日子，不舍，但你知道不能再待了。圣杯八问你：你走，是因为真的没了，还是因为不敢再试了？\n\n【心理层面】你怕的是「走了就没了」。你怕一走，那些曾经的付出都白费了。你问「这段关系的本质是什么」，其实你真正想问的是：「我走了之后，还能不能找到更好的？」\n\n【根源层面】你是个念旧的人。什么都舍不得扔，什么都舍不得放。但你不知道，有些东西，你不扔，就永远装不进新的。圣杯八说：你走的那条路，不是回头路，是新路。

【走向与影响】你怕的是「離开就没了」。圣杯八正位提醒你：你真正要的，可能是更好的下一站。心理层面的突破，是问——我若離开，是为了更好的下一站，还是只是在逃？`,
  spiritLayer: `宇宙在等你迈一步。迈出去，可能冷，可能暗，但你走了，才能看见下一盏灯。\n\n核心启示：你怕的不是离开，是你怕离开之后，发现外面也没有更好的。

若问势头卡在哪，多半是「流动」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「清点」的小事：寫下「从这段关系里，我已经學到／带走的是_____」。检查你的「行囊」：圣杯八问你——你走，是为了下一站还是逃？`,
  masterSummary: `「流动」松一寸，走向就变一寸——真正的离开不是你不想回头，是你终于敢往前走了。 第二问那句仍管用：你们之间最大的阻碍，往往是该離开的未離开。圣杯八说：带着學到的離开。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'cups_8', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（圣杯八逆位）想对你说：走向被「離开被卡住」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 不敢離开、半途而廢、或该留的却走了、冲动離开事后后悔——我若留下，是出于爱与选择还是恐惧？我若離开，是为了更好的下一站还是只是在逃？圣杯八逆位说：阻碍是「未决」；想清楚再动。。 你想走，但没走。 把力气花在看得见的一步：今天只做「问心」，做完就停。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「僵持」。你不想待了，但也不走。你说为了他，为了孩子，为了那么多年的感情。但你心里知道，你是为了自己不敢走。圣杯八逆位问你：你怕的是什么？\n\n【心理层面】你怕的是「走了没人要」。你把这段关系当成了自己的价值，没了它，你就不知道自己算什么。你问「这段关系的本质是什么」，其实你真正想问的是：「我能不能一个人？」\n\n【根源层面】你从小就被教「要有人陪」。一个人太可怜，一个人太孤单。所以你再不舒服，也不肯一个人。但圣杯八逆位说：一个人，不一定可怜；两个人，不一定不孤单。

【走向与影响】你怕的是「走错」。圣杯八逆位提醒你：你真正怕的，可能是留下是懦弱、走是殘忍。心理层面的突破，是问——留下是爱还是怕？走是自由还是逃？`,
  spiritLayer: `宇宙在等你敢一个人站一会儿。你站住了，就知道自己有多重。不靠别人撑着，自己也能站直。\n\n核心启示：你怕的不是走，是你怕走了之后，发现自己根本不认识那个一个人的自己。

能量没有散，是聚在「未决」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「问心」的小事：问自己——「我若留下，是出于什么？我若離开，是出于什么？」寫下来，不逼答案。检查你的「行囊」：圣杯八逆位问你——你卡住的，是爱还是习惯？`,
  masterSummary: `想动走势，先认「未决」这道结——真正的留下不是你不敢走，是你敢走的时候，还选择留。 对照第二问：你们之间最大的阻碍，往往是未想清楚就动或不动。圣杯八逆位说：留下或離开，都要出于清醒的选择。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'cups_9', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（圣杯九正位）想对你说：走向不是「没有丰盛」那种误会式的死局，而是两人的劲还拧在「自足变成了圍牆」上，没一起认、也没一起动。 一人独坐身后九杯自足；最大的阻碍，是你们其中一人或两人「什么都有却没人」——独享变成孤島、不愿留空间给对方进来。圣杯九说：阻碍是「门未开」；在自足時也留一点空间给分享，你值得被看见。 你坐在那里，九个杯子整整齐齐摆在你身后。 别等对方先示范。今天你先用「留门」给关系一个可跟的节拍。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「满足」。可能是他让你觉得够了，可能是你自己觉得够了。你不想要更多，不想要更好，就现在这样，挺好。圣杯九问你：你是真的满足，还是不敢再要了？\n\n【心理层面】你怕的是「要了就会失去」。你太怕失去，所以告诉自己「够了」。但你心里还有一点空，那个空，是你故意留的，怕满了就没了。你问「这段关系的本质是什么」，其实你真正想问的是：「我能不能再要一点？」\n\n【根源层面】你从小就不敢要。要糖怕被骂，要爱怕被拒。你习惯了「差不多就行」，习惯了「这样也挺好」。但圣杯九说：差不多，不是真好。你真的好，是敢要还觉得自己值。

【走向与影响】你怕的是「需要别人等于不够強」。圣杯九正位提醒你：你真正要的，是一段可以既独立又连结的关系。心理层面的突破，是接纳——你值得拥有，也值得被看见；留一点门给值得的人进来。`,
  spiritLayer: `宇宙在等你张开手。你抱着胸，是防御。张开手，才能接，才能给，才能真的满。\n\n核心启示：你怕的不是不满，是你怕满了之后，就再也没东西追了。

就走向而言，两人的气机还绕在「自足」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「留门」的小事：做一件「为对方留一点空间」的事——一句邀請、一次分享、或一个「我需要你」的誠实表达。检查你的「行囊」：圣杯九问你——你的自足，是丰盛还是圍牆？`,
  masterSummary: `走向的纽子在「自足」——真正的满足不是你有了多少，是你有了之后，还敢不敢要更多。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是自足变成了圍牆。圣杯九说：你值得被看见，留一点门。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'cups_9', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（圣杯九逆位）想对你说：走向被「自足变成空虛、独享变成孤独或貪婪」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 表面什么都有、內心却觉得还不够；或害怕与人分享而把一切抓紧——你需要的不只是物质与成就，而是被看见、被连结。圣杯九逆位说：阻碍是「孤島」；打开一点门，让值得的人进来。 九个杯子还在，但你笑不出来。 你若真想推动走势，就从「要」开始——轻，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「不满足」。他做了很多，你觉得还不够；他给了很多，你觉得还差一点。你永远在要，永远不够。圣杯九逆位问你：你要的，是他能给的，还是你自己心里那个洞？\n\n【心理层面】你怕的是「满足了就没了」。你一直不满足，因为满足了就没盼头了。你问「这段关系的本质是什么」，其实你真正想问的是：「我怎么才能不这么贪？」\n\n【根源层面】你心里有一个洞。不是他给的少，是你一直没补上那个洞。那个洞叫「我不够好」。你把他给的一切往里填，填多少，漏多少。圣杯九逆位说：你把洞堵上，一勺就够了。

【走向与影响】你怕的是「敞开会被掏空」。圣杯九逆位提醒你：你真正怕的，可能是依賴。心理层面的突破，是问——我们要的是独占还是连结？与人连结可以补足独享的不足。`,
  spiritLayer: `宇宙在等你承认自己够了。你够了，不是因为有了多少，是因为你就是你。你值，不用加任何东西。\n\n核心启示：你怕的不是不够，是你怕够了之后，就再也没理由要了。

就走向而言，两人的气机还绕在「孤独或貪婪」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「要」的小事：对对方说一句你真正需要的——「我需要_____」。检查你的「行囊」：圣杯九逆位问你——你抓紧的，是丰盛还是恐惧？`,
  masterSummary: `走向的纽子在「孤独或貪婪」——真正的满足不是你终于要到了，是你敢说「我现在这样，就够了」。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是不敢要『被看见』。圣杯九逆位说：打开一点门。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'cups_10', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（圣杯十正位）想对你说：走向不是「没有圓滿的可能」那种误会式的死局，而是两人的劲还拧在「家的定义未对齊」上，没一起认、也没一起动。 伴侶与孩童在彩虹下举杯；最大的阻碍，是你们对「家是什么」「谁是家人」「界線在哪」没有共識——或过度依賴家人／伴侶、表面一家心不在一起。圣杯十说：阻碍是「家的定义」；珍惜身边的人，同時照顧好自己的界線，家可以是选择的。 你看见了那道彩虹。 走向听行动。今天只兑现「歸屬」——让对方看见你在动，而不是在讲。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「完整」。不是完美，是完整。有笑有泪，有吵有闹，但都在。你不再想要别的，因为这就是你要的。圣杯十问你：你确定吗？\n\n【心理层面】你怕的是「太完整了会碎」。你太珍惜，太怕失去，所以连幸福都不敢全信。你问「这段关系的本质是什么」，其实你真正想问的是：「能一直这样吗？」\n\n【根源层面】你见过太多破碎的家，太多分离的爱。你不信永恒，不信永远。但圣杯十说：永远不是时间长，是你这一刻，愿意相信它会在。

【走向与影响】你怕的是「圓滿是假的」。圣杯十正位提醒你：你真正要的，是一段可以成家、可以长久承诺的关系。心理层面的突破，是接纳——家可以是选择的；珍惜身边的人，界線也要顧好。`,
  spiritLayer: `宇宙在等你收下这份完整。不是你挣的，不是你修的，是它给你的。你收了，你就有了。\n\n核心启示：你怕的不是没有，是你怕有了之后，还要失去。

若问势头卡在哪，多半是「歸屬」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「歸屬」的小事：和对方定义一次「我们的家是什么」——不逼形式，只让「我们是一家人」被说出口。检查你的「行囊」：圣杯十问你——这个家，是两个人选的还是别人期待的？`,
  masterSummary: `「歸屬」松一寸，走向就变一寸——真正的完整不是你什么都拥有了，是你终于敢认，你已经有了。 第二问那句仍管用：你们之间最大的阻碍，往往是家的定义未对齊。圣杯十说：家可以是选择的。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'cups_10', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（圣杯十逆位）想对你说：走向被「圓滿出现裂痕」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 家庭議题、过度依賴家人或伴侶、或家的定义与现实冲突——你以为的家真的是你要的吗？圣杯十逆位说：阻碍是「需要重新定义家」；照顧好界線，家可以是选择的，你也可以选择什么人、什么方式構成歸屬。。 彩虹碎了。 你要影响走向，今天就卡这一格：把「界線」做到底，小不要紧，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「破碎感」。可能是吵架了，可能是疏远了，可能是你觉得家不像家了。你努力拼，但总是差一块。圣杯十逆位问你：你拼的，是外面的家，还是心里的家？\n\n【心理层面】你怕的是「再也拼不好了」。你把家看得很重，重到一点裂痕都接受不了。但你越怕，越容易碎。你问「这段关系的本质是什么」，其实你真正想问的是：「还能拼好吗？」\n\n【根源层面】你从小就没一个完整的家。所以你拼命想要一个，比谁都想要。但你越要，越容易碎，因为你要的，是完美的。圣杯十逆位说：完整不是完美，完整是裂了还能在一起。

【走向与影响】你怕的是「家会散」。圣杯十逆位提醒你：你真正怕的，可能是承认这个家不完美。心理层面的突破，是问——我们以为的家，真的是我们要的吗？该分开的帳要分开。`,
  spiritLayer: `宇宙在等你先在心里建一个家。不管外面怎么碎，心里那个家在，你就不怕。\n\n核心启示：你怕的不是外面碎了，是你怕心里没有家。

若问势头卡在哪，多半是「家的定义」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「界線」的小事：寫下一句「在这个家里，我需要保留的界線是_____」。检查你的「行囊」：圣杯十逆位问你——你为家犧牲的，是爱还是义務？`,
  masterSummary: `「家的定义」松一寸，走向就变一寸——真正的家不是外面那道彩虹，是你心里那个拆不掉的房子。 第二问那句仍管用：你们之间最大的阻碍，往往是家的定义与界線。圣杯十逆位说：家可以是选择的，界線也是。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'cups_11', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（圣杯侍从正位）想对你说：走向不是「没有感受」那种误会式的死局，而是两人的劲还拧在「感受没有流出来」上，没一起认、也没一起动。 年轻人捧杯专注聆听；最大的阻碍，是你们其中一人或两人把感受壓在心里、不敢表达、或只活在幻想里不落地——你的情绪需要被看见，包括被你本人。圣杯侍从说：阻碍是「未流露」；用一个具體方式表达感受或灵感，不必等完美，先让它流出来。 你手里捧着一个杯子，眼睛盯着里面的鱼。 你要影响走向，今天就卡这一格：把「流露」做到底，小不要紧，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「天真」。可能是他做了件傻事，可能是你莫名笑了。你不用想太多，不用算计，就只是觉得有意思。圣杯侍从问你：你还记得这种感觉吗？\n\n【心理层面】你怕的是「太天真会被骗」。你吃了太多亏，学会了防，学会了算，学会了不笑。但你不笑的时候，也忘了快乐是什么。你问「这段关系的本质是什么」，其实你真正想问的是：「我还能不能像以前一样开心？」\n\n【根源层面】你曾经是个特别容易开心的人。一朵花，一只猫，一句话，都能让你笑。后来你长大了，笑点高了，也少笑了。但圣杯侍从说：那个小孩还在你心里，只是你把他关起来了。

【走向与影响】你怕的是「说出来会破壞」。圣杯侍从正位提醒你：你真正要的，是一段可以表达感受的关系。心理层面的突破，是接纳——你的情绪需要被看见；新恋情的萌芽、曖昧或心动，先让它流出来。`,
  spiritLayer: `宇宙在等你放那个小孩出来。他跑出来，看见鱼跳，还是会笑。你让他笑一次，你就知道，快乐还在。\n\n核心启示：你怕的不是不快乐，是你怕快乐的时候，忘了自己是个大人。

这条关系的走势，眼下还拴在「直觉」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「流露」的小事：用一个具體方式表达你的感受——寫下来、画出来、或说给一个人听。检查你的「行囊」：圣杯侍从问你——你壓着的，是爱还是怕被拒绝？`,
  masterSummary: `势头绕在「直觉」上——真正的快乐不是你长大了还能笑，是你笑的时候，还是个孩子。 第二问早已点破：你们之间最大的阻碍，往往是感受没有流出来。圣杯侍从说：先流出来。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'cups_11', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（圣杯侍从逆位）想对你说：走向被「敏感变成过度敏感、创意变成沉溺幻想」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 过度解读他人、或活在自己想像里不愿面对真相、不敢表白而卡在幻想里——把创意与感受落实在生活中；让內在的水流动，不要堵在心里。圣杯侍从逆位说：阻碍是「未落地」；寫下来、画出来、说给一个人听。 鱼死了。 走向听行动。今天只兑现「落地」——让对方看见你在动，而不是在讲。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「麻木」。以前让你开心的事，现在没感觉了。以前让你笑的人，现在懒得笑了。你觉得一切都淡了，没意思了。圣杯侍从逆位问你：是你的心淡了，还是他变了？\n\n【心理层面】你怕的是「再也提不起劲了」。你试过几次，想让自己开心，但就是开心不起来。你问「这段关系的本质是什么」，其实你真正想问的是：「我还能不能爱？」\n\n【根源层面】你经历了太多，累了。累到连快乐都觉得累。但你不是没感觉，你是不敢感觉，因为感觉了，就要面对可能失去。圣杯侍从逆位说：你一直防着，防着，把自己防成了石头。

【走向与影响】你怕的是「真相会伤人」。圣杯侍从逆位提醒你：你真正怕的，可能是面对现实。心理层面的突破，是问——我们是在感受还是在幻想？让感受落地。`,
  spiritLayer: `宇宙在等你碎一次。石头碎了，才能长出草。你疼一次，才能知道，疼也是活着的证明。\n\n核心启示：你怕的不是没感觉，是你怕有感觉的时候，又要疼一次。

这条关系的走势，眼下还拴在「幻想」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「落地」的小事：选一件你一直「只在心里想」的关于这段关系的事，用一个具體方式表达出来。检查你的「行囊」：圣杯侍从逆位问你——你卡住的，是爱还是怕被拒绝？`,
  masterSummary: `势头绕在「幻想」上——真正的活着不是你一直开心，是你敢不开心的时候，还不装开心。 第二问早已点破：你们之间最大的阻碍，往往是感受未落地。圣杯侍从逆位说：不要堵在心里。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'cups_12', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（圣杯騎士正位）想对你说：走向不是「没有浪漫」那种误会式的死局，而是两人的劲还拧在「追求没有对准真实的人」上，没一起认、也没一起动。 騎馬捧杯姿态优雅；最大的阻碍，是你们其中一人过度理想化对方、或热情没有对准可回應的对象——追求時保持真实不演戲；把热情对准真正值得的人与事。圣杯騎士说：阻碍是「未对准」；把热情对准可回應的对象。 你骑着马，慢慢地走。 今天用「追求」替关系试温：你动了，场的流向才会跟着变。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「优雅」。不是轰轰烈烈，是慢慢来。他不急，你不急，你们就顺着走。你觉得这样挺好，但也怕太慢会错过。圣杯骑士问你：你要的是快，还是对？\n\n【心理层面】你怕的是「慢了就没了」。你看别人快，看别人急，你慌。你问「这段关系的本质是什么」，其实你真正想问的是：「慢的，能走到最后吗？」\n\n【根源层面】你一直是个急的人。急长大，急毕业，急成功。你习惯了快，一慢就不习惯。但圣杯骑士说：快，不一定先到；慢，不一定晚到。你慢慢走，才能看见风景。

【走向与影响】你怕的是「主动会掉价」。圣杯騎士正位提醒你：你真正要的，是一段可以浪漫、可以追求的关系。心理层面的突破，是接纳——告白、约会、新恋情或浪漫期，保持真实；把热情对准可回應的对象。`,
  spiritLayer: `宇宙在等你学会慢。慢的时候，才能听风的声音，才能看云的形状，才能发现，他要的，和你一样。\n\n核心启示：你怕的不是慢，是你怕慢了之后，发现他根本不想走。

若问势头卡在哪，多半是「为爱与理想而动」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「追求」的小事：做一件「跟隨內心」的、为这段关系的主动出擊——一句真心话、一次邀约、或一个承诺。检查你的「行囊」：圣杯騎士问你——你追的，是人还是幻觉？`,
  masterSummary: `「为爱与理想而动」松一寸，走向就变一寸——真正的骑士不是他一直走，是他走的时候，手里还捧着给你的杯子。 第二问那句仍管用：你们之间最大的阻碍，往往是热情未对准可回應的对象。圣杯騎士说：对准值得的人。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'cups_12', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（圣杯騎士逆位）想对你说：走向被「浪漫变成不切实际、追求变成退縮或单恋」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 过度理想化对方、或不敢行动而错过緣分——若对方无意學会收手，若你有意學会表达。圣杯騎士逆位说：阻碍是「未对准」；把热情对准可回應的对象。 你迷路了。 你能拧动的开关往往在细节：今天把「对准」做实，比分析十句有用。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「逃避」。你总说没遇到对的人，但遇到的时候你又跑。你总说想要爱，但爱来了你又躲。圣杯骑士逆位问你：你到底想不想要？\n\n【心理层面】你怕的是「真的有了怎么办」。你习惯了幻想，习惯了追，但不习惯得到。因为你怕得到了之后，会发现没那么好。你问「这段关系的本质是什么」，其实你真正想问的是：「我敢不敢要？」\n\n【根源层面】你从小就没真正得到过想要的东西。每一次接近，每一次失去。你学会了不期望，不争取，不受伤。但你也学会了，永远在门口转，不敢进去。圣杯骑士逆位说：你不进去，永远不知道里面有什么。

【走向与影响】你怕的是「被拒绝」。圣杯騎士逆位提醒你：你真正怕的，可能是行动后的答案。心理层面的突破，是问——我们是在追求还是在幻想？该表达就表达，该收手就收手。`,
  spiritLayer: `宇宙在等你敲门。不用推门，就敲。敲了，可能有人开门，也可能没人。但你敲了，你就不是一直转圈的人了。\n\n核心启示：你怕的不是得不到，是你怕得到了之后，发现不过如此。

若问势头卡在哪，多半是「不切实际或退縮」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「对准」的小事：若你有意，做一件具體的表达；若对方无意，做一件具體的收手或界線。检查你的「行囊」：圣杯騎士逆位问你——你卡住的，是爱还是怕被拒？`,
  masterSummary: `「不切实际或退縮」松一寸，走向就变一寸——真正的骑士不是一直在路上，是他终于敢停下来，敲一扇门。 第二问那句仍管用：你们之间最大的阻碍，往往是热情未对准可回應的对象。圣杯騎士逆位说：有意就表达，无意就收手。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'cups_13', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（圣杯皇后正位）想对你说：走向不是「没有滋养」那种误会式的死局，而是两人的劲还拧在「滋养前没有先滿自己的杯」上，没一起认、也没一起动。 皇后坐海边捧杯凝視；最大的阻碍，是你们其中一人一直给、给到枯竭，或没有先填滿自己的杯子就试图填滿对方——你的情绪需要被看见，包括被你本人；先填滿自己的杯子，才能给出真正的滋养。圣杯皇后说：阻碍是「未自滿」；先滿再给。 你坐在海边，手里捧着一个精致的圣杯，杯子盖着。 你若真想推动走势，就从「自滿」开始——轻，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「深情」。你能感受到他的情绪，甚至他自己还没察觉的，你已经感受到了。你用这温柔去爱，去接住那些掉下来的人。但圣杯王后问你：你自己掉下来的时候，谁来接你？\n\n【心理层面】你怕的是「没人接我」。你一直接别人，别人习惯了被你接，忘了你也会掉。你问「这段关系的本质是什么」，其实你真正想问的是：「我能不能也被人接一次？」\n\n【根源层面】你从小就是那个「懂事」的。爸妈累，你安静；朋友哭，你安慰；他难过，你陪伴。你把别人放在前面，把自己放在最后。但圣杯王后说：你放在最后的人，最后会找不到。

【走向与影响】你怕的是「不付出就不被爱」。圣杯皇后正位提醒你：你真正要的，是一段可以相互滋养的关系。心理层面的突破，是接纳——能滋养关系、给安全感；先填滿自己的杯子再给出去。`,
  spiritLayer: `宇宙在等你把杯子倒过来。一直满着，装不下新的。你倒一点出来，给自己，给自己一点温柔。\n\n核心启示：你怕的不是没人爱你，是你怕自己忘了怎么爱自己。

能量没有散，是聚在「成熟的女性水元素」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「自滿」的小事：做一件纯粹「为自己填滿杯子」的事——独處、療癒、或设一个界線。检查你的「行囊」：圣杯皇后问你——你给的，是丰盛还是掏空自己？`,
  masterSummary: `想动走势，先认「成熟的女性水元素」这道结——真正的王后不是你一直温柔待人，是你终于敢温柔待己。 对照第二问：你们之间最大的阻碍，往往是未先滿自己的杯。圣杯皇后说：先滿再给。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'cups_13', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（圣杯皇后逆位）想对你说：走向被「滋养变成情绪化、同理变成依賴或过度付出」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 用付出換取被爱、或情绪起伏大难以自稳——过度付出失去界線、或因受伤而封闭；你不需要为所有人的情绪負责。圣杯皇后逆位说：阻碍是「未自滿」；先填滿自己的杯子——独處、療癒、设界線。 你的杯子快溢出来了。 别等对方先示范。今天你先用「界線」给关系一个可跟的节拍。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「透支」。你一直在给，给到空了，还在给。你觉得这是爱，但你不知道，空的人给的，是冷的。圣杯王后逆位问你：你自己都没了，拿什么给他？\n\n【心理层面】你怕的是「不给就没人爱」。你把给当成了唯一的价值，给了，才觉得自己存在。但你给空了，他走了，你更空了。你问「这段关系的本质是什么」，其实你真正想问的是：「我能不能不给了？」\n\n【根源层面】你从小就是那个「照顾者」。家里的情绪你接，朋友的情绪你接，恋人的情绪你也接。你把照顾当成了使命，当成了活着的理由。但圣杯王后逆位说：你照顾了所有人，谁来照顾你？

【走向与影响】你怕的是「不付出就没人爱」。圣杯皇后逆位提醒你：你真正怕的，可能是被抛弃。心理层面的突破，是问——我们是在滋养还是在討爱？先填滿自己的杯子；小心过度付出、失去界線。`,
  spiritLayer: `宇宙在等你先把自己装满。你不装，就永远是空的。空的杯子，倒不出水。\n\n核心启示：你怕的不是他不爱你，是你怕自己不爱自己之后，就真的没人爱你了。

若问势头卡在哪，多半是「情绪化或过度付出」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「界線」的小事：选一件你习惯「为对方情绪負责」的事，今天不做；或设一个「我不会_____」的界線。检查你的「行囊」：圣杯皇后逆位问你——你付出的，是爱还是討爱？`,
  masterSummary: `「情绪化或过度付出」松一寸，走向就变一寸——真正的温柔不是你对谁都好，是你对自己好的时候，还能对他好。 第二问那句仍管用：你们之间最大的阻碍，往往是未先滿自己的杯。圣杯皇后逆位说：你不需要为所有人的情绪負责。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'cups_14', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（圣杯国王正位）想对你说：走向不是「没有稳定」那种误会式的死局，而是两人的劲还拧在「稳定壓住了感受」上，没一起认、也没一起动。 国王端坐海浪中王座持杯；最大的阻碍，是你们其中一人用「理性」「負责」壓抑自己与对方的感受——成熟不是壓抑，是知道何時流露、何時收斂；在稳定時保留表达感受的空间。圣杯国王说：阻碍是「未流露」；成熟是能接住情绪，不是没有情绪。 你坐在王座上，手里捧着一个杯子。 把力气花在看得见的一步：今天只做「流露」，做完就停。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「稳定」。不是没风浪，是风浪来了你还能稳。你能接住他的情绪，也能控制自己的情绪。圣杯国王问你：你这么稳，是因为你强，还是因为你不敢乱？\n\n【心理层面】你怕的是「一乱就全乱了」。你把稳当成了唯一的标准，不敢波动，不敢失控，不敢流露。你问「这段关系的本质是什么」，其实你真正想问的是：「我能乱一次吗？」\n\n【根源层面】你从小就是那个「靠谱」的。家里的事你处理，朋友的事你帮忙，关系的事你协调。你把靠谱当成了盔甲，穿上就脱不下来。但圣杯国王说：靠谱的人，也需要不靠谱的时候。

【走向与影响】你怕的是「流露会失控」。圣杯国王正位提醒你：你真正要的，是一段可以给承诺与安全感的关系。心理层面的突破，是接纳——能给出承诺与安全感；在稳定的框架里留一点柔软。`,
  spiritLayer: `宇宙在等你洒一滴水。不用洒多，就一滴。洒了，你才知道，稳不是不洒，是洒了还能满回来。\n\n核心启示：你怕的不是不稳，是你怕不稳了之后，就再也稳不回来了。

这条关系的走势，眼下还拴在「情感责任」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「流露」的小事：在稳定的前提下，做一件「表达感受」的事——一句感谢、一个拥抱、或一次「我感觉_____」的分享。检查你的「行囊」：圣杯国王问你——你的稳定，是成熟还是壓抑？`,
  masterSummary: `势头绕在「情感责任」上——真正的国王不是他一直稳，是他不稳的时候，还能让自己稳回来。 第二问早已点破：你们之间最大的阻碍，往往是稳定壓住了感受。圣杯国王说：成熟是能接住情绪。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'cups_14', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（圣杯国王逆位）想对你说：走向被「成熟变成冷漠、稳定变成壓抑或控制」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 不敢表达情感、或用理性壓制自己与他人的感受——冷漠、逃避承诺或壓抑感受；在稳定的框架里，留一点柔软。圣杯国王逆位说：阻碍是「未流露」；允許自己与他人流露情感。 你翻了。 影响走向不靠喊话，靠落地。今天完成「柔软」，再谈别的。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「失控」。可能是你终于忍不住了，可能是你终于爆发了。你一直装没事，一直装稳，现在装不下去了。圣杯国王逆位问你：你现在这样，是输了，还是终于活了？\n\n【心理层面】你怕的是「被人看见」。你一直装，就是怕被人看见你的乱。但现在藏不住了，你慌。你问「这段关系的本质是什么」，其实你真正想问的是：「乱了之后，他还爱我吗？」\n\n【根源层面】你从小就不被允许乱。哭要挨骂，闹要挨打，所以你学会了一个字：忍。忍到今天，忍到忍不了。但圣杯国王逆位说：忍不了的，才是真的你。

【走向与影响】你怕的是「软了会受伤」。圣杯国王逆位提醒你：你真正怕的，可能是脆弱。心理层面的突破，是问——我们是在稳定还是在壓抑？允許自己与他人流露情感。`,
  spiritLayer: `宇宙在等你乱一次。乱了，才能看清谁会在旁边接你。不乱，永远不知道谁是真正爱你的人。\n\n核心启示：你怕的不是乱，是你怕乱了之后，没人接你。

就走向而言，两人的气机还绕在「过度理性」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「柔软」的小事：选一件你习惯「用理性壓住」的感受，今天用一句话表达出来。检查你的「行囊」：圣杯国王逆位问你——你壓住的，是保护还是恐惧？`,
  masterSummary: `走向的纽子在「过度理性」——真正的国王不是他一直不乱，是他乱了之后，还敢让人看见。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是稳定壓住了感受。圣杯国王逆位说：成熟不是壓抑。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'swords_1', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（宝剑一正位）想对你说：走向不是「没有真相」那种误会式的死局，而是两人的劲还拧在「真相未被刺穿」上，没一起认、也没一起动。 雲中手紧握筆直宝剑刺穿皇冠；最大的阻碍，是你们没有把「我们之间到底卡在哪」想清楚、说清楚——思绪清明時不要拖延，把决定做出来。宝剑一说：阻碍是「未面对的清晰」；抓住那个清晰的念头，用行动落实。 一把剑从云中伸出来，剑尖顶着王冠。 你能拧动的开关往往在细节：今天把「清晰」做实，比分析十句有用。`,
  psychologyLayer: `【关系现状】你们的关系到了一个「该看清的时候」。可能是他一直没说的真相，可能是你一直不敢看的现实。剑来了，你不能再装看不见。宝剑王牌问你：你是真的不知道，还是不敢知道？\n\n【心理层面】你怕的是「看清了就没法装了」。你一直躲在雾里，假装一切都好。但剑来了，雾会散，真相会露出来。你问「这段关系的本质是什么」，其实你真正想问的是：「看清了之后，我还能不能装作不知道？」\n\n【根源层面】你太会装糊涂了。从小装，装不知道家里的事，装不知道朋友的事，装不知道自己的事。你装得太久，久到真的不知道了。但宝剑王牌说：剑来了，你装不了了。

【走向与影响】你怕的是「看清后无法回头」。宝剑一正位提醒你：你真正要的，是一段可以想清楚再走的关系。心理层面的突破，是接纳——抓住清晰的念头，用行动落实；关系中的真相浮现時，给彼此一点空间再下结論。`,
  spiritLayer: `宇宙在等你接过这把剑。剑在手，你可以砍，也可以放下。但你不接，它就永远悬在头顶，让你睡不着。\n\n核心启示：你怕的不是看清，是你怕看清之后，再也没有理由骗自己了。

这条关系的走势，眼下还拴在「真相」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「清晰」的小事：把「这段关系我们之间最大的阻碍是什么」寫成一句话，不逼对方认同，只让自己看见。检查你的「行囊」：宝剑一问你——你要的是真相，还是安全？`,
  masterSummary: `势头绕在「真相」上——真正的真相不是你看见的，是你看见了之后还敢认。 第二问早已点破：你们之间最大的阻碍，往往是真相未被刺穿。宝剑一说：把决定做出来。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'swords_1', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（宝剑一逆位）想对你说：走向被「清晰被混亂、偏见或迟来的領悟取代」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 想太快、判斷失准、或真相太痛所以不想看——區分直觉的清晰与冲动的偏见；必要時寻求第二意见，再行动。宝剑一逆位说：阻碍是「未面对的真相」；思绪还亂時，先沉澱再动。 剑歪了。 今天用「沉澱」替关系试温：你动了，场的流向才会跟着变。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「假清醒」。你以为自己想通了，想明白了，但其实你只是换了个角度继续骗自己。宝剑王牌逆位问你：你用这把剑，是劈开真相，还是砍人？\n\n【心理层面】你怕的是「真看清了会疼」。所以你宁愿拿着歪剑，劈东劈西，就是不劈自己的心。你问「这段关系的本质是什么」，其实你真正想问的是：「能不能给个不疼的答案？」\n\n【根源层面】你从小就会找借口。考试不好怪题难，朋友散了怪别人。你太会找理由，找到自己都信了。但宝剑王牌逆位说：理由找得再多，真相还是真相。

【走向与影响】你怕的是「面对真相」。宝剑一逆位提醒你：你真正怕的，可能是答案。心理层面的突破，是问——我们是在逃避还是在沉澱？给头脑一点時间，但沉澱之后还是要面对。`,
  spiritLayer: `宇宙在等你把剑扶正。歪着砍，砍不到要害。扶正了，可能疼，但那一刀下去，病就好了。\n\n核心启示：你怕的不是看不清，是你怕看清了之后，发现那个理由是你自己编的。

这条关系的走势，眼下还拴在「未面对的真相」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「沉澱」的小事：不逼结論，只把「我害怕面对的是_____」寫下来。检查你的「行囊」：宝剑一逆位问你——你迟迟不面对的，是真相还是恐惧？`,
  masterSummary: `势头绕在「未面对的真相」上——真正的清醒不是你拿着剑，是你拿剑的时候，知道要砍什么。 第二问早已点破：你们之间最大的阻碍，往往是未在沉澱后面对。宝剑一逆位说：區分直觉与偏见，再动。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'swords_2', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（宝剑二正位）想对你说：走向不是「没有选项」那种误会式的死局，而是两人的劲还拧在「卡在两难不敢选」上，没一起认、也没一起动。 一人蒙眼坐海边双剑交叉；最大的阻碍，是你们在「要繼续还是放手」「选 A 还是选 B」之间僵持——不做选择也是一种选择，拖延会让选项变少。宝剑二说：阻碍是「未做的选择」；列出取舍的利弊，再问內心更怕失去哪一边。 你坐着，双手交叉，两把剑在面前，眼睛被蒙住。 走向听行动。今天只兑现「取舍」——让对方看见你在动，而不是在讲。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「僵局」。左也难，右也难。你不想选，不敢选，就蒙上眼睛假装不用选。但时间在走，你在原地。宝剑二问你：你能蒙多久？\n\n【心理层面】你怕的是「选错」。你太怕错了，所以干脆不选。但你不知道，不选，也是选——你选了停在原地。你问「这段关系的本质是什么」，其实你真正想问的是：「有没有一条路是肯定不会错的？」\n\n【根源层面】你曾经选错过一次。那次让你疼了很久，所以你发誓再也不选了。但你忘了，那次疼，不是因为选了，是因为你没看清就选了。宝剑二说：你看清再选，可能就不疼了。

【走向与影响】你怕的是「选错」。宝剑二正位提醒你：你真正怕的，可能是选了就要負责。心理层面的突破，是问——我们更怕失去哪一边？选一个，然后承担。`,
  spiritLayer: `宇宙在等你把蒙眼布解开。就三秒，看一眼。看一眼，再蒙上。明天再看一眼。慢慢，你就习惯了看见。\n\n核心启示：你怕的不是选错，是你怕选了之后，再也怪不了别人了。

这条关系的走势，眼下还拴在「选择」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「取舍」的小事：寫下「若选 A 我怕_____；若选 B 我怕_____」。不逼立刻选，只让恐惧被看见。检查你的「行囊」：宝剑二问你——你卡住的，是两个都好还是两个都怕？`,
  masterSummary: `势头绕在「选择」上——真正的选择不是你选对了，是你终于敢睁眼看自己的路。 第二问早已点破：你们之间最大的阻碍，往往是卡在两难不敢选。宝剑二说：不选，选项会变少。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'swords_2', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（宝剑二逆位）想对你说：走向被「僵局开始松动却未完成」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 终于愿意走出僵局、做出选择，或该选不选、让别人替你选了——接纳没有完美答案，选一个可修正的。宝剑二逆位说：阻碍是「选了还可以微調」；选一个，用「先试一季」破局也好过无限拖延。 你放下了剑。 你要影响走向，今天就卡这一格：把「破局」做到底，小不要紧，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「被迫清醒」。可能是他终于摊牌了，可能是你终于受不了了。你不能再装，不能再躲，必须面对了。宝剑二逆位问你：你现在看见了，怎么办？\n\n【心理层面】你怕的是「看见之后要负责」。以前你可以说「我不知道」，现在知道了，就要决定了。你问「这段关系的本质是什么」，其实你真正想问的是：「我能不能不看？」\n\n【根源层面】你一直用「不知道」保护自己。不知道，就可以不选；不知道，就可以不负责。但现在知道了，没地方躲了。宝剑二逆位说：躲不了的时候，你才开始活。

【走向与影响】你怕的是「选了会后悔」。宝剑二逆位提醒你：你真正怕的，可能是承担。心理层面的突破，是接纳——选一个，用「先试一季」破局也好过无限拖延。`,
  spiritLayer: `宇宙在等你做决定。不是一定要选对，是选了就行。选了，你才能往前走。\n\n核心启示：你怕的不是看见，是你怕看见之后，再也不能装看不见了。

若问势头卡在哪，多半是「该选未选」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「破局」的小事：选一件你一直卡住的「二选一」，用「先试_____（一个小步）」破局。检查你的「行囊」：宝剑二逆位问你——你松动的，是真心还是被迫？`,
  masterSummary: `「该选未选」松一寸，走向就变一寸——真正的看见不是你终于睁眼，是你睁眼之后还敢走下一步。 第二问那句仍管用：你们之间最大的阻碍，往往是未选一个可修正的答案。宝剑二逆位说：选了还可以微調。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'swords_3', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（宝剑三正位）想对你说：走向不是「没有痛过」那种误会式的死局，而是两人的劲还拧在「三把剑还刺在心里」上，没一起认、也没一起动。 三把剑刺穿一顆心；最大的阻碍，是你们其中一人或两人没有走出心碎、背叛、失落或拒绝——伤需要時间结痂，壓抑或否认往往让它拖更久。宝剑三说：阻碍是「未療癒的伤」；接纳伤痛的存在，同時相信它会減轻。 三把剑插在一颗心上。 你要影响走向，今天就卡这一格：把「接纳痛」做到底，小不要紧，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「心碎」。可能是他走了，可能是你发现他不爱了，可能是你终于承认这段感情死了。你疼，疼得喘不过气。宝剑三问你：你疼成这样，是因为失去他，还是因为失去自己？\n\n【心理层面】你怕的是「疼了也好不了」。你怕这疼会一直跟着你，永远好不了。你问「这段关系的本质是什么」，其实你真正想问的是：「我还能不能好了？」\n\n【根源层面】你曾经被伤过。那次伤了很久才好，所以你这次更怕，怕更久，怕好不了。但宝剑三说：心不碎，就不知道心在哪。疼，是因为你还活着。

【走向与影响】你怕的是「再痛一次」。宝剑三正位提醒你：你真正要的，是一段可以不心碎的关系。心理层面的突破，是接纳——允許自己走过这段路；不必急着原諒或忘记，先接纳「我现在很痛」。`,
  spiritLayer: `宇宙在等你把剑拔出来。一把一把拔，慢慢拔。拔出来，伤口才能长。不拔，剑就一直插着。\n\n核心启示：你怕的不是疼，是你怕疼完了之后，发现心里空了一块。

就走向而言，两人的气机还绕在「療癒」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「接纳痛」的小事：对自己说一句「我现在很痛，这是被允許的」。不逼好起来，只让伤被承认。检查你的「行囊」：宝剑三问你——你壓着的，是伤还是憤怒？`,
  masterSummary: `走向的纽子在「療癒」——真正的心碎不是你被插了三把剑，是你插着剑的时候，还不敢喊疼。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是未接纳伤痛存在。宝剑三说：给它時间结痂。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'swords_3', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（宝剑三逆位）想对你说：走向被「伤口开始癒合未完成」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 療癒中、逐漸釋放痛苦，或痛还在但你不愿再被它定义——伤口会结痂，但你需要允許自己走过这段路。宝剑三逆位说：阻碍是「未完成的療癒」；逐漸走出、把伤痛转成學习，不再反芻。 心上的剑被拔出来了。 走向听行动。今天只兑现「带着伤走」——让对方看见你在动，而不是在讲。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「恢复期」。可能是你终于不哭了，可能是你终于能正常生活了。你还记得疼，但疼不再控制你了。宝剑三逆位问你：你带着伤，还能爱吗？\n\n【心理层面】你怕的是「带着伤会连累他」。你怕自己没好全，怕自己还会疼，怕自己不够好。你问「这段关系的本质是什么」，其实你真正想问的是：「我这样，还能被爱吗？」\n\n【根源层面】你从小就被教「要完美才能被爱」。成绩好才被夸，听话才被疼。你把这套带进感情，觉得自己有伤就不配。但宝剑三逆位说：有伤的，才是人。

【走向与影响】你怕的是「忘记等于背叛」。宝剑三逆位提醒你：你真正怕的，可能是放下痛就没了存在感。心理层面的突破，是接纳——不必急着原諒，先接纳痛。`,
  spiritLayer: `宇宙在等你继续走。带着伤走，走得慢一点，但能走。伤是你的，也是你的力量。\n\n核心启示：你怕的不是伤没好，是你怕伤好了之后，你就不再是那个受伤的人了。

就走向而言，两人的气机还绕在「復原中」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「带着伤走」的小事：做一件「痛还在，但我选择_____」的具體行动。检查你的「行囊」：宝剑三逆位问你——你放下的，是痛还是对痛的執着？`,
  masterSummary: `走向的纽子在「復原中」——真正的愈合不是你忘了疼，是你疼的时候，还能对自己说「我在好」。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是未带着伤往前走。宝剑三逆位说：伤会结痂，你先接纳。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'swords_4', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（宝剑四正位）想对你说：走向不是「没有停頓」那种误会式的死局，而是两人的劲还拧在「该靜的没靜、该动的没动」上，没一起认、也没一起动。 一人平躺教堂內三剑掛牆；最大的阻碍，是你们用冷戰、逃避、或「我需要空间」无限拖延——你不是在逃，是在儲备；用这段停頓儲备能量，而非自责。宝剑四说：阻碍是「停頓的错用」；休息够了，再动。 你躺下了。 今天用「停頓」替关系试温：你动了，场的流向才会跟着变。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「暂停」。可能是你们吵累了，可能是你一个人撑累了。你终于肯停下来，不争不吵，就躺着。宝剑四问你：你躺下的时候，是休息，还是放弃？\n\n【心理层面】你怕的是「一躺就起不来了」。你一直跑，一直撑，就是怕停下来。现在停了，你慌。你问「这段关系的本质是什么」，其实你真正想问的是：「我还能起来吗？」\n\n【根源层面】你从小就被教「不能停」。停了就输，停了就被落下。你从来没真正休息过，不知道休息是什么感觉。但宝剑四说：休息不是输，是充电。

【走向与影响】你怕的是「一停就散了」。宝剑四正位提醒你：你真正要的，是一段可以暫停再来的关系。心理层面的突破，是接纳——关系冷戰、需要空间或暫時不談時，休息是为了再动。`,
  spiritLayer: `宇宙在等你好好躺一会儿。不用想以后，不用想他，不用想关系。就躺着，让身体自己恢复。恢复好了，自然会醒。\n\n核心启示：你怕的不是躺，是你怕躺了之后，发现自己不想起来了。

就走向而言，两人的气机还绕在「暫停」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「停頓」的小事：和对方或自己约定一段「不談问题、只休息」的時间。检查你的「行囊」：宝剑四问你——你停下来，是復原还是逃避？`,
  masterSummary: `走向的纽子在「暫停」——真正的休息不是你终于躺下，是你躺下的时候，还敢闭眼。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是停頓的错用。宝剑四说：休息是为了再动。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'swords_4', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（宝剑四逆位）想对你说：走向被「停頓被打破未完成」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 逐漸恢復、准备再戰，或你其实在逃避，用「我在休息」当借口迟迟不行动——區分有意識的休息与逃避；若躺很久却没有更清醒，问自己：我是在復原，还是在躲？宝剑四逆位说：阻碍是「该动未动」；休息够了再动。。 你躺不下去了。 你能拧动的开关往往在细节：今天把「再动」做实，比分析十句有用。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「被迫起来」。可能又吵了，可能又有事了，可能你不得不面对了。你还没准备好，但箭在弦上，不得不发。宝剑四逆位问你：你现在起来，能撑住吗？\n\n【心理层面】你怕的是「没休息好会撑不住」。你太累了，但又不得不动。你问「这段关系的本质是什么」，其实你真正想问的是：「能不能再给我一点时间？」\n\n【根源层面】你从来就没真正休息过。每次刚要躺下，就有人喊你。你习惯了半睡半醒，习惯了随时待命。但宝剑四逆位说：你一直这样，会把自己熬干的。

【走向与影响】你怕的是「一动又吵」。宝剑四逆位提醒你：你真正怕的，可能是面对。心理层面的突破，是问——我们休息够了吗？该沟通就沟通，不要用「我需要靜一靜」无限拖延。`,
  spiritLayer: `宇宙在等你学会拒绝。不是每一次喊你你都要应。你应一次，就不停有人喊你。你学会不应的那次，才能真的睡。\n\n核心启示：你怕的不是没休息好，是你怕休息好了之后，发现人家早就不喊你了。

若问势头卡在哪，多半是「该动未动」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「再动」的小事：选一件你一直用「我在休息」拖延的对话，约一个時间談。检查你的「行囊」：宝剑四逆位问你——你起来，是为了关系还是为了不面对？`,
  masterSummary: `「该动未动」松一寸，走向就变一寸——真正的休息不是你被人喊醒，是你醒了之后，还敢继续睡。 第二问那句仍管用：你们之间最大的阻碍，往往是该动時未动。宝剑四逆位说：休息够了再动。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'swords_5', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（宝剑五正位）想对你说：走向不是「没有在意」那种误会式的死局，而是两人的劲还拧在「赢了戰场、输了关系」上，没一起认、也没一起动。 戰后三人散落、勝者持剑；最大的阻碍，是你们用爭吵、競爭、各執己见代替沟通——赢了这场，会得到什么？值得吗？有時不爭就是赢。宝剑五说：阻碍是「爭奪取代了连结」；放下「要对」的執念，把力气留给真正重要的事。 你赢了。 你若真想推动走势，就从「不爭」开始——轻，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「胜负」。可能是你吵赢了，可能是你占上风了，可能是你让他低头了。但你赢了之后，发现他也不在了，心也不在了。宝剑五问你：你赢了吗？\n\n【心理层面】你怕的是「输了就没了」。所以你拼命赢，拼命争，拼命证明自己是对的。但你赢了，他还是没了。你问「这段关系的本质是什么」，其实你真正想问的是：「我赢了之后，他能回来吗？」\n\n【根源层面】你从小就被教「要赢」。赢才有人夸，赢才被看见。你把赢当成了唯一的标准，连感情也要赢。但宝剑五说：感情里没有赢家，只有两个输的人。

【走向与影响】你怕的是「输」。宝剑五正位提醒你：你真正怕的，可能是被否定。心理层面的突破，是问——我们是在爭对错，还是在爭被看见？`,
  spiritLayer: `宇宙在等你放下剑。你不放，手就一直举着，举到酸，举到疼。放下，手才能空出来，才能接别的东西。\n\n核心启示：你怕的不是输，是你怕输了之后，就再也没人要了。

能量没有散，是聚在「对立」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「不爭」的小事：选一件你习惯「一定要说赢」的事，今天只听不辯。检查你的「行囊」：宝剑五问你——你爭的，是真理还是面子？`,
  masterSummary: `想动走势，先认「对立」这道结——真正的赢不是你赢了，是你输得起的时候，还敢再比。 对照第二问：你们之间最大的阻碍，往往是赢了戰场输了关系。宝剑五说：赢了这场，值得吗？`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'swords_5', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（宝剑五逆位）想对你说：走向被「对立开始松动未完成」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 和解、放下输赢、或从冲突中學习——愿意用对话取代对抗；愿意先收剑，就是第一步。宝剑五逆位说：阻碍是「未收剑」；从冲突中學到教訓，下次用不同方式。 你输了。 别等对方先示范。今天你先用「收剑」给关系一个可跟的节拍。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「认输」。可能是你终于不争了，可能是你终于放手了。你输了，但也轻了。宝剑五逆位问你：输了之后，你看到什么了？\n\n【心理层面】你怕的是「输了就完了」。但你输了之后，发现没完，你还活着，还能呼吸。你问「这段关系的本质是什么」，其实你真正想问的是：「输了之后，我还算什么？」\n\n【根源层面】你一直把「赢」当成存在的证明。赢了，才有人看见；输了，就什么都不是。但宝剑五逆位说：你输了，才看见那些赢的时候看不见的东西。

【走向与影响】你怕的是「先收剑就输了」。宝剑五逆位提醒你：你真正怕的，可能是软弱。心理层面的突破，是接纳——各退一步、寻求共識，或接受「不必每次都要说赢」。`,
  spiritLayer: `宇宙在等你看见「输」的背面。那里没有掌声，但有自己。\n\n核心启示：你怕的不是输，是你怕输了之后，发现自己从来就没赢过什么重要的。

这条关系的走势，眼下还拴在「该收剑未收」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「收剑」的小事：对对方说一句「剛才那场，我们可以換一种方式吗？」检查你的「行囊」：宝剑五逆位问你——你收剑，是为了关系还是为了不內耗？`,
  masterSummary: `势头绕在「该收剑未收」上——真正的输不是你打输了，是你打完才发现，根本不该打。 第二问早已点破：你们之间最大的阻碍，往往是未先收剑。宝剑五逆位说：从冲突中學到教訓。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'swords_6', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（宝剑六正位）想对你说：走向不是「没有路」那种误会式的死局，而是两人的劲还拧在「没有带着能带走的轻装上路」上，没一起认、也没一起动。 一人撐船渡水、船上插六剑；最大的阻碍，是你们没有一起離开困难情境、或心态上决定「不再留在原地」——不必等伤口完全癒合才动；有時动了，療癒才会开始。宝剑六说：阻碍是「未启程」；带着能带走的，轻装上路。 你坐在船上，船在水上漂。 把力气花在看得见的一步：今天只做「轻装」，做完就停。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「过渡」。可能是分手了，可能是搬家了，可能是你们要异地了。你在走，在动，在离开。宝剑六问你：你带走的是回忆，还是包袱？\n\n【心理层面】你怕的是「忘不掉」。你太怕那些回忆会一直跟着你，太重，重到你走不动。你问「这段关系的本质是什么」，其实你真正想问的是：「我能不能不带走？」\n\n【根源层面】你是一个念旧的人。什么东西都舍不得扔，什么人都不想忘。但你忘了，船太重，会沉。宝剑六说：不是让你忘，是让你放。

【走向与影响】你怕的是「離开就没了」。宝剑六正位提醒你：你真正要的，可能是一起渡过难关的过渡。心理层面的突破，是接纳——離开、过渡或前行，带着能带走的；不必等伤口完全癒合才动。`,
  spiritLayer: `宇宙在等你往前看。你看后面，就看不见前面。你一直回头，船就会偏。你看前面，它自然会到。\n\n核心启示：你怕的不是忘不掉，是你怕忘了之后，就真的没了。

就走向而言，两人的气机还绕在「前行」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「轻装」的小事：寫下「从这段关系里，我要带走的是_____；我可以放下的是_____」。检查你的「行囊」：宝剑六问你——你带的，是爱还是執着？`,
  masterSummary: `走向的纽子在「前行」——真正的过渡不是你离开，是你离开的时候，还敢往前走。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是未带着能带走的轻装上路。宝剑六说：动了療癒才开始。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'swords_6', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（宝剑六逆位）想对你说：走向被「过渡被卡住」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 无法放手、迟迟不離开有毒的環境或关系、或離开后又回头——既回不去又还没到彼岸，焦慮与无力交織。宝剑六逆位说：阻碍是「未走」；是什么在拉住我？若已经决定要走，就不要再頻頻回望。 船沉了。 影响走向不靠喊话，靠落地。今天完成「不回望」，再谈别的。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「卡住」。走不了，回不去，就在中间漂着。你累了，但不知道怎么办。宝剑六逆位问你：你带的那些剑，有几把是你自己的？\n\n【心理层面】你怕的是「扔了就没了」。你把每一段回忆都当成了剑，以为扔了就会轻，但扔了也怕会忘。你问「这段关系的本质是什么」，其实你真正想问的是：「我能不能都留着，还能走？」\n\n【根源层面】你太怕错过了。怕错过重要的，怕以后后悔，所以什么都留着。留到现在，留到走不动。但宝剑六逆位说：你留的不是回忆，是累赘。

【走向与影响】你怕的是「走了就真的没了」。宝剑六逆位提醒你：你真正怕的，可能是孤单。心理层面的突破，是问——我们不敢走，是爱还是习惯？下一步需要勇气，但留在原地往往更耗損。`,
  spiritLayer: `宇宙在等你扔一把。不用都扔，就扔一把。最重的那把。扔了，船就能动了。\n\n核心启示：你怕的不是扔，是你怕扔了之后，再也想不起来了。

这条关系的走势，眼下还拴在「该走未走」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「不回望」的小事：选一件你「走了又回头」的习惯，今天只做一次「不回头」的决定。检查你的「行囊」：宝剑六逆位问你——你卡住的，是爱还是恐惧？`,
  masterSummary: `势头绕在「该走未走」上——真正的放下不是你扔了，是你扔了之后，还记得，但不再疼了。 第二问早已点破：你们之间最大的阻碍，往往是走就不再回望。宝剑六逆位说：留在原地往往更耗損。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'swords_7', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（宝剑七正位）想对你说：走向不是「没有策略」那种误会式的死局，而是两人的劲还拧在「策略取代了底線」上，没一起认、也没一起动。 一人悄悄取走五把剑留两把在后；最大的阻碍，是你们用回避、保留、不正面冲突代替真话——算计的同時别忘了底線；策略可以灵活，原則不能丟；否則赢了局面，输了自我。宝剑七说：阻碍是「底線未守」；原則不能丟。 你偷偷拿走了五把剑，留下两把。 影响走向不靠喊话，靠落地。今天完成「底線」，再谈别的。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「撤退」。可能是你不再争了，可能是你悄悄放手了。你没告诉他，也没宣布，就是默默退了一步。宝剑七问你：你是真的想退，还是在等他来追？\n\n【心理层面】你怕的是「退了就真的没了」。你退一步，是想看他会不会追上来。但他没追，你慌了。你问「这段关系的本质是什么」，其实你真正想问的是：「我退的时候，他能拉住我吗？」\n\n【根源层面】你从小就会用这招。闹脾气，不说话，看谁先低头。你习惯了用退来试人心，用走来试爱。但宝剑七说：你走多了，就真的没人追了。

【走向与影响】你怕的是「正面冲突」。宝剑七正位提醒你：你真正要的，可能是不硬碰硬。心理层面的突破，是问——我们是在保留实力，还是在逃避该面对的对话？`,
  spiritLayer: `宇宙在等你站住。不退了，也不走了，就站着。你站着，才能看清他是来追你，还是也在退。\n\n核心启示：你怕的不是退，是你怕退了之后，发现他根本没发现你退了。

若问势头卡在哪，多半是「策略」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「底線」的小事：寫下一句「在这段关系里，我的底線是_____」。检查你的「行囊」：宝剑七问你——你保留的，是智慧还是逃避？`,
  masterSummary: `「策略」松一寸，走向就变一寸——真正的撤退不是你偷偷走，是你走了之后，还敢回头看。 第二问那句仍管用：你们之间最大的阻碍，往往是策略里未守住底線。宝剑七说：原則不能丟。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'swords_7', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（宝剑七逆位）想对你说：走向被「策略失效或该面对现实」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 计謀被識破、或迂回太久反而失去先机——与其繼续躲、繼续算，不如直接说清楚、做个了斷。宝剑七逆位说：阻碍是「未面对」；若你一直在用策略逃避该面对的对话或责任，或許是该站出来的時候。 你被抓到了。 把力气花在看得见的一步：今天只做「直接」，做完就停。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「翻车」。可能是你的小把戏被他看穿了，可能是你的谎话被拆穿了。你觉得丢脸，觉得完蛋了。宝剑七逆位问你：你当初用这招的时候，想过后果吗？\n\n【心理层面】你怕的是「被看穿」。你一直藏着掖着，不敢让他知道真正的自己。现在被看穿了，你慌。你问「这段关系的本质是什么」，其实你真正想问的是：「被看穿了之后，他还会要我吗？」\n\n【根源层面】你从小就会藏。藏情绪，藏想法，藏真实的自己。你怕被人看穿，看穿了就不安全了。但宝剑七逆位说：你一直藏，藏到没人认识你。现在被看穿，反而是你们第一次见面。

【走向与影响】你怕的是「攤牌」。宝剑七逆位提醒你：你真正怕的，可能是面对。心理层面的突破，是问——我们躲久了会变成信任危机；该坦誠就坦誠。`,
  spiritLayer: `宇宙在等你被看见一次。不是被看见手段，是被看见真实。那个人看见了，还在，才是真的。\n\n核心启示：你怕的不是被发现，是你怕被发现之后，他不要你了。

就走向而言，两人的气机还绕在「该面对未面对」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「直接」的小事：选一件你一直用策略逃避的事，说一句真话。检查你的「行囊」：宝剑七逆位问你——你站出来的，是勇气还是被迫？`,
  masterSummary: `走向的纽子在「该面对未面对」——真正的见面不是你藏得最好，是你终于敢不藏的时候，他还在。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是该直接時未站出来。宝剑七逆位说：有時直接比迂回有效。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'swords_8', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（宝剑八正位）想对你说：走向不是「没有出口」那种误会式的死局，而是两人的劲还拧在「自己綁住了自己」上，没一起认、也没一起动。 一人被蒙眼綁手周身插滿八剑；最大的阻碍，是你们其中一人或两人感到被束縛、无力、或自我设限——很多綁住你的绳子是你自己綁的；或你早已可以脫身，却因恐惧而不敢动。宝剑八说：阻碍是「自我设限」；區分「真的不能」与「不敢」，从一个小出口试起；你比你想像中自由。 你被绑着，眼睛被蒙着，周围都是剑。 别等对方先示范。今天你先用「小出口」给关系一个可跟的节拍。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「被困住」。你觉得走不掉，离不开，没办法。但宝剑八问你：你试过动一下吗？可能你一动，那绳子根本就没打结。\n\n【心理层面】你怕的是「动了会更糟」。你不敢试，不敢赌，不敢迈一步。你问「这段关系的本质是什么」，其实你真正想问的是：「有没有一条路是绝对安全的？」\n\n【根源层面】你从小就被保护得太好。每一步都有人指路，每一个坑都有人告诉你。现在没人指了，你就不敢走了。但宝剑八说：你绑着自己的那根绳，是你妈系上去的，早该解了。

【走向与影响】你怕的是「一动就崩」。宝剑八正位提醒你：你真正怕的，可能是自由。心理层面的突破，是问——我们是真的不能，还是不敢？你比你想像中自由。`,
  spiritLayer: `宇宙在等你睁眼。你睁眼看看，那些剑离你有多远。可能根本刺不到你。你一直闭着眼，才以为它们是冲你来的。\n\n核心启示：你怕的不是被困住，是你怕挣扎了之后，发现门根本没锁。

能量没有散，是聚在「自我设限」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「小出口」的小事：选一件你一直说「不能」的事，问自己「若我敢，第一步是什么？」只问不逼做。检查你的「行囊」：宝剑八问你——你綁住自己的，是关系还是恐惧？`,
  masterSummary: `想动走势，先认「自我设限」这道结——真正的自由不是你被解开，是你发现从来没被绑过。 对照第二问：你们之间最大的阻碍，往往是自我设限。宝剑八说：你比你想像中自由。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'swords_8', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（宝剑八逆位）想对你说：走向被「开始看见出口、松綁或接受幫助」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 愿意摘下眼罩、看见其实没有那麼多剑，或有人伸手拉你一把——接受幫助不是软弱；试着动一动，有些剑早就松了。宝剑八逆位说：阻碍是「未动」；接受幫助不是软弱。 绳子松了。 你若真想推动走势，就从「动一动」开始——轻，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「醒过来」。可能是你终于想通了，可能是你终于不怕了。你发现以前那些担心的，其实都没发生。宝剑八逆位问你：你现在知道了，然后呢？\n\n【心理层面】你怕的是「知道了也不知道怎么办」。你醒了，但路还在那，你还是要走。你问「这段关系的本质是什么」，其实你真正想问的是：「醒了之后，我往哪走？」\n\n【根源层面】你一直以为自己在笼子里，所以从来没想过出去之后怎么活。现在笼子没了，你反而慌了。但宝剑八逆位说：你不是没地方去，是你还没学会自己走。

【走向与影响】你怕的是「接受幫助等于软弱」。宝剑八逆位提醒你：你真正怕的，可能是依賴。心理层面的突破，是接纳——接受幫助不是软弱；开始看见选项、愿意接受外界支持。`,
  spiritLayer: `宇宙在等你迈第一步。不用想第二步，就迈第一步。迈了，你就会知道，脚踩在地上的感觉，没那么可怕。\n\n核心启示：你怕的不是出不去，是你怕出去之后，发现自己根本不认识路。

若问势头卡在哪，多半是「该动未动」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「动一动」的小事：选一件你一直说「我不行」的事，做一个最小的尝试。检查你的「行囊」：宝剑八逆位问你——你松綁的，是别人幫的还是自己敢的？`,
  masterSummary: `「该动未动」松一寸，走向就变一寸——真正的醒不是你睁眼了，是你睁眼之后，还敢自己走。 第二问那句仍管用：你们之间最大的阻碍，往往是未试着动一动。宝剑八逆位说：接受幫助不是软弱。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'swords_9', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（宝剑九正位）想对你说：走向不是「没有担憂」那种误会式的死局，而是两人的劲还拧在「担憂没有被说出来」上，没一起认、也没一起动。 一人夜半坐床双手掩面身后掛九剑；最大的阻碍，是你们其中一人或两人被深夜的担憂、反芻、对未来的恐惧綁架——很多恐惧是「想出来的」，不是当下真实发生的。宝剑九说：阻碍是「未说出的恐惧」；把担憂寫下来、或跟一个人说，会減轻重量；你已经撐过很多次了，这次也可以。 你从噩梦中醒来，坐在床上，双手抱着头。 你能拧动的开关往往在细节：今天把「寫下来」做实，比分析十句有用。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「折磨」。可能是分手后，可能是吵架后，可能是你自己在脑子里反复重播。你睡不着，吃不下，满脑子都是他。宝剑九问你：你折磨自己的，是他，还是你心里那个声音？\n\n【心理层面】你怕的是「好不了」。你怕这疼会永远跟着你，永远睡不着。你问「这段关系的本质是什么」，其实你真正想问的是：「我什么时候能好？」\n\n【根源层面】你一直是个想很多的人。一件事翻来覆去想，想到睡不着，想到天亮。你太会想了，想得太多，活不下去。但宝剑九说：你不是因为想太多而疼，是因为疼了才想多。

【走向与影响】你怕的是「最壞会成真」。宝剑九正位提醒你：你真正怕的，可能是失控。心理层面的突破，是接纳——很多恐惧是想出来的；把担憂寫下来、找人談，往往会发现没有那麼绝望。`,
  spiritLayer: `宇宙在等你喘口气。不解决问题，不想办法，就喘口气。吸一口气，呼一口气。活着，就行了。\n\n核心启示：你怕的不是疼，是你怕疼了之后，没人知道你在疼。

能量没有散，是聚在「焦慮」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「寫下来」的小事：把「这段关系里我最怕的是_____」寫下来，不逼解决，只让恐惧被看见。检查你的「行囊」：宝剑九问你——你怕的，是当下还是想像？`,
  masterSummary: `想动走势，先认「焦慮」这道结——真正的疼不是你想太多，是你疼的时候，还不敢让人看见。 对照第二问：你们之间最大的阻碍，往往是未把担憂寫下来。宝剑九说：你已经撐过很多次了。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'swords_9', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（宝剑九逆位）想对你说：走向被「恐惧开始減轻未完成」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 寻求支援、转念、或终于愿意把心里的担憂说出来——恐惧会騙人；把担憂具體化、寫下来、找人談，往往会发现没有那麼绝望。宝剑九逆位说：阻碍是「未说出的担憂」；你已经撐过很多次了。 你从床上下来了。 今天用「说出来」替关系试温：你动了，场的流向才会跟着变。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「站起来」。可能是你终于开始正常生活了，可能是你终于不再想他了。你还记得疼，但疼不再控制你。宝剑九逆位问你：你起来了，然后呢？\n\n【心理层面】你怕的是「起来了还会再倒下」。你试过几次，好一阵，又疼一阵。你怕这次也是。你问「这段关系的本质是什么」，其实你真正想问的是：「我能好吗？」\n\n【根源层面】你太清楚自己的弱点了。你知道自己容易倒下，所以不敢站直。但宝剑九逆位说：倒了还能起来，比一直站着更厉害。

【走向与影响】你怕的是「说出来会被笑」。宝剑九逆位提醒你：你真正怕的，可能是脆弱。心理层面的突破，是接纳——愿意说出不安、或发现担憂过度；寻求支援、把担憂化成具體行动方案。`,
  spiritLayer: `宇宙在等你继续走。一步一步走，不用快。走了，你就知道，走的感觉比躺着好。\n\n核心启示：你怕的不是倒下，是你怕倒下了之后，再也没有力气起来了。

若问势头卡在哪，多半是「恐惧減轻中」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「说出来」的小事：选一个你信任的人，说一句「我最近在怕_____」。检查你的「行囊」：宝剑九逆位问你——你減轻的，是真相还是说出来的勇气？`,
  masterSummary: `「恐惧減轻中」松一寸，走向就变一寸——真正的起来不是你站直了，是你倒了之后，还敢再起。 第二问那句仍管用：你们之间最大的阻碍，往往是未把担憂说出来。宝剑九逆位说：恐惧会騙人。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'swords_10', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（宝剑十正位）想对你说：走向不是「没有结束」那种误会式的死局，而是两人的劲还拧在「结束未被允許悲伤」上，没一起认、也没一起动。 一人俯臥背上插滿十剑；最大的阻碍，是你们其中一人或两人没有在关系的某种「结束」時允許自己悲伤、然后慢慢转身——结束是为了新的开始，你已经在谷底了，接下来会是上坡。宝剑十说：阻碍是「未完成的结束」；在结束時允許自己悲伤，然后慢慢转身。 你趴在地上，背上插着十把剑。 你能拧动的开关往往在细节：今天把「悲伤」做实，比分析十句有用。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「结束」。可能是真的分了，可能是真的死了，可能是你终于承认它没了。你以为这是末日，但宝剑十说：这是开始。\n\n【心理层面】你怕的是「死了就没了」。你不知道后面还有什么，所以你怕。你问「这段关系的本质是什么」，其实你真正想问的是：「死了之后，还能活吗？」\n\n【根源层面】你从来没经历过真正的结束。每一次都是没死透，每一次都还有一点希望。所以这次真的死了，你受不了。但宝剑十说：没死透，才难受；死透了，才能重生。

【走向与影响】你怕的是「结束就什么都没了」。宝剑十正位提醒你：你真正要的，可能是解脫。心理层面的突破，是接纳——关系结束、心碎告一段落；在结束時允許自己悲伤，然后慢慢转身。`,
  spiritLayer: `宇宙在等你躺一会儿。不用挣扎，不用想怎么办。就躺着，让血流，让天慢慢亮。亮了，你就知道，你还没死。\n\n核心启示：你怕的不是死，是你怕死了之后，发现自己根本没活过。

若问势头卡在哪，多半是「终点」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「悲伤」的小事：允許自己为「这段关系的结束或某个终点」悲伤十分鐘。检查你的「行囊」：宝剑十问你——你结束的，是关系还是執着？`,
  masterSummary: `「终点」松一寸，走向就变一寸——真正的结束不是你死了，是你终于敢承认，那段日子已经过完了。 第二问那句仍管用：你们之间最大的阻碍，往往是结束時未允許悲伤然后转身。宝剑十说：结束是为了新的开始。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'swords_10', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（宝剑十逆位）想对你说：走向被「结束尚未完全、或伤痛殘留」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 不肯放手、緩慢復原、或该结束的不结束一直在拖——该斷不斷需要给自己時间真正放手；允許自己悲伤，然后慢慢转身，新的阶段才能真正开始。宝剑十逆位说：阻碍是「未放手」；该收尾的收尾，才能轻装迎向下一段。 你从地上爬起来了。 今天用「放手」替关系试温：你动了，场的流向才会跟着变。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「复活」。可能是你终于放下了，可能是你终于原谅了，可能是你终于能走出来了。你还记得疼，但疼不再拦你。宝剑十逆位问你：你活了，然后呢？\n\n【心理层面】你怕的是「活了之后怎么办」。你不知道接下来去哪，不知道还会不会又死一次。你问「这段关系的本质是什么」，其实你真正想问的是：「我该怎么活？」\n\n【根源层面】你一直活在别人的剧本里。爸妈安排，社会规定，他想要。你从来没自己活过。现在死了一次，你自由了，也慌了。但宝剑十逆位说：自由就是，你自己写剧本。

【走向与影响】你怕的是「放手就没了」。宝剑十逆位提醒你：你真正怕的，可能是空。心理层面的突破，是接纳——殘留伤痛、该斷不斷；给自己時间真正放手，新的阶段才能开始。`,
  spiritLayer: `宇宙在等你走一步。不管往哪，走一步。走了，就有路。\n\n核心启示：你怕的不是活不了，是你怕活了之后，发现不知道怎么活。

能量没有散，是聚在「该放手未放手」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「放手」的小事：选一件代表「该结束」的象徵物或习惯，做一个小小的放手儀式。检查你的「行囊」：宝剑十逆位问你——你拖着的，是爱还是不甘？`,
  masterSummary: `想动走势，先认「该放手未放手」这道结——真正的活着不是你从地上爬起来了，是你爬起来之后，还敢往前看。 对照第二问：你们之间最大的阻碍，往往是未给自己時间真正放手。宝剑十逆位说：该收尾的收尾。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'swords_11', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（宝剑侍从正位）想对你说：走向不是「没有好奇」那种误会式的死局，而是两人的劲还拧在「好奇没有用在建设性的探索上」上，没一起认、也没一起动。 手握宝剑站立警觉张望；最大的阻碍，是你们没有一起打听、研究、或把「我们之间卡在哪」查清楚——把好奇心用在有建设性的探索上，篩选訊息来源，专注一两件事，再做出判斷。宝剑侍从说：阻碍是「未探索」；篩选来源，专注再判斷。 你手里拿着剑，眼睛看着远方。 走向听行动。今天只兑现「探索」——让对方看见你在动，而不是在讲。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「洞察」。可能是你能看穿他的心思，可能是你能发现他隐藏的情绪。你像个小侦探，总想找出蛛丝马迹。但宝剑侍从问你：你找的这些线索，是想更了解他，还是想证明自己的猜测是对的？\n\n【心理层面】你怕的是「看错人」。你太想看清了，太想确定了，所以拼命收集信息，拼命分析。但你分析越多，越不敢信。你问「这段关系的本质是什么」，其实你真正想问的是：「我看到的他，是真的他吗？」\n\n【根源层面】你从小就是个聪明的孩子。老师夸你机灵，爸妈说你想得多。你把聪明当成了武器，用来保护自己。但你太聪明了，聪明到把别人的好也能看成坏。宝剑侍从说：你拿着剑，不是为了砍，是为了看清。看清之后，还要不要砍，是你的选择。

【走向与影响】你怕的是「知道太多会破壞」。宝剑侍从正位提醒你：你真正要的，可能是一段可以一起探索的关系。心理层面的突破，是接纳——透过訊息、介紹或共同话题遇緣；篩选来源，专注一两件事再行动。`,
  spiritLayer: `宇宙在等你放下剑一会儿。不分析，不判断，就感受。感受他的温度，感受他的心跳。那比任何分析都准。\n\n核心启示：你怕的不是看不清，是你怕看清了之后，发现自己一直看错了方向。

能量没有散，是聚在「好奇与訊息」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「探索」的小事：对这段关系做一件「打听或研究」的事——问一个你想知道的问题、或查一个你一直没搞清楚的資訊。检查你的「行囊」：宝剑侍从问你——你好奇的，是关系还是控制？`,
  masterSummary: `想动走势，先认「好奇与訊息」这道结——真正的看见不是你用剑指着他，是你放下剑之后，还认得他的脸。 对照第二问：你们之间最大的阻碍，往往是未用好奇心探索。宝剑侍从说：篩选来源，专注再判斷。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'swords_11', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（宝剑侍从逆位）想对你说：走向被「好奇变成散漫、訊息变成八卦或資訊混亂」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 到處听一点却没有整合、或傳递未经证实的消息——把一个想法查清楚，比十个想法半懂不懂更有用。宝剑侍从逆位说：阻碍是「未专注」；篩选訊息来源，专注一两件事；把一个想法查清楚再动。 你的剑掉地上了。 你要影响走向，今天就卡这一格：把「专注」做到底，小不要紧，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「混乱」。可能是你听信了太多传言，可能是你误解了他的意思，可能是你自己把自己绕进去了。你觉得什么都对不上，什么都想不通。宝剑侍从逆位问你：你是真的想不通，还是不想想通？\n\n【心理层面】你怕的是「想通了更难受」。你宁愿乱着，也不愿意面对那个真相。你问「这段关系的本质是什么」，其实你真正想问的是：「能不能别让我想那么清楚？」\n\n【根源层面】你从小就不喜欢面对真相。家里吵架，你躲房间；朋友矛盾，你装不知道。你太会逃避了，逃到自己都信了。但宝剑侍从逆位说：你逃得了一时，逃不了一辈子。真相早晚会来。

【走向与影响】你怕的是「不问就落伍」。宝剑侍从逆位提醒你：你真正怕的，可能是无知。心理层面的突破，是问——我们是在探索还是在逃避？小心听信流言、或只停留在打听不实际接觸。`,
  spiritLayer: `宇宙在等你停下来。不看了，不猜了，不想了。就停下来，问问自己：我最怕知道的是什么？\n\n核心启示：你怕的不是看不见，是你怕看见了之后，再也没理由骗自己了。

就走向而言，两人的气机还绕在「資訊混亂」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「专注」的小事：选一件关于这段关系你「听了很多却没查清楚」的事，查清楚。检查你的「行囊」：宝剑侍从逆位问你——你散漫的，是好奇还是逃避面对？`,
  masterSummary: `走向的纽子在「資訊混亂」——真正的聪明不是你什么都知道，是你不知道的时候，还敢承认。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是未把一个想法查清楚。宝剑侍从逆位说：专注一两件事再动。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'swords_12', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（宝剑騎士正位）想对你说：走向不是「没有冲勁」那种误会式的死局，而是两人的劲还拧在「冲动取代了解决问题」上，没一起认、也没一起动。 全速前进的头脑；最大的阻碍，是你们其中一人或两人用「我要赢」「我对」代替「我们要一起解决什么」——出手前先问自己：我是为了解决问题，还是只想赢？宝剑騎士说：阻碍是「爭鋒取代了连结」；用头脑校准方向，再用行动執行。。 你冲过来了。 你要影响走向，今天就卡这一格：把「校准」做到底，小不要紧，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「急」。可能是你急着确定关系，可能是你急着要结果，可能是你急着往前走。你不想等，不想慢，不想停。宝剑骑士问你：你这么急，是要去哪？\n\n【心理层面】你怕的是「慢下来就没了」。你太怕失去，太怕错过，所以拼命冲，拼命赶。但你越冲，越看不清。你问「这段关系的本质是什么」，其实你真正想问的是：「我能不能在慢下来的时候，还拥有你？」\n\n【根源层面】你从小就是个急性子。什么事都想快点做完，什么结果都想快点得到。你把这个性子带进感情，但感情是慢的，急不得。宝剑骑士说：你冲得太快，会错过路上的风景，也会错过他看你时的温柔。

【走向与影响】你怕的是「一慢就输」。宝剑騎士正位提醒你：你真正要的，可能是一段可以一起冲的关系。心理层面的突破，是问——我们是在解决问题还是在爭赢？把語气放慢、说出真实需求。`,
  spiritLayer: `宇宙在等你勒一下缰绳。不用全停，就慢一点。慢一点，才能看清他的脸，才能听见他说的话。\n\n核心启示：你怕的不是到不了，是你怕到了之后，发现根本不是你想要的那个地方。

若问势头卡在哪，多半是「銳气」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「校准」的小事：在开口或行动前，先问自己「我是为了解决问题，还是只想赢？」检查你的「行囊」：宝剑騎士问你——你冲的，是爱还是勝負？`,
  masterSummary: `「銳气」松一寸，走向就变一寸——真正的速度不是你冲得多快，是你冲的时候，还敢回头看。 第二问那句仍管用：你们之间最大的阻碍，往往是冲动取代了解决问题。宝剑騎士说：为了解决问题，不是为了赢。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'swords_12', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（宝剑騎士逆位）想对你说：走向被「鋒利变成魯莽，速度变成失控」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 说话太冲、没顧及对方感受；或脑中只想着「我要赢」——现在的行动方式，很可能是在「用力证明自己」，而不是真正对事情有幫助。宝剑騎士逆位说：阻碍是「失速」；与其硬冲，不如先停下来校准方向、确认資訊是否完整、情绪是否过热。 你摔了。 走向听行动。今天只兑现「降溫」——让对方看见你在动，而不是在讲。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「翻车」。可能是你太急表白了，结果被拒；可能是你太急推进了，结果他跑了。你觉得委屈，觉得命运不公。宝剑骑士逆位问你：你冲之前，有没有看一眼他是什么反应？\n\n【心理层面】你怕的是「摔了就起不来了」。你太怕失败，所以这一摔，你可能就不敢再跑了。你问「这段关系的本质是什么」，其实你真正想问的是：「我还能再冲一次吗？」\n\n【根源层面】你一直是个冲动的人。想做什么就做，想说就说。你靠这股冲劲得到过很多，也失去过很多。但你从没学会，冲之前要看路。宝剑骑士逆位说：不是不能冲，是冲的时候，要看清楚他是不是也在跑向你。

【走向与影响】你怕的是「一软就输」。宝剑騎士逆位提醒你：你真正怕的，可能是用速度掩蓋方向错誤。心理层面的突破，是问——我们爭的是对错还是被爱？与其爭谁对，不如先把語气放慢、说出真实需求。`,
  spiritLayer: `宇宙在等你站起来。摔了，站起来，拍拍土，看看路。这次你看清楚了，再冲。\n\n核心启示：你怕的不是摔，是你怕摔了之后，发现自己根本跑错了方向。

若问势头卡在哪，多半是「魯莽」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「降溫」的小事：选一件你习惯「立刻反擊」的事，今天先停三十秒再回應。检查你的「行囊」：宝剑騎士逆位问你——你冲的，是问题还是情绪？`,
  masterSummary: `「魯莽」松一寸，走向就变一寸——真正的骑士不是他不摔，是他摔了之后，还敢再骑上马。 第二问那句仍管用：你们之间最大的阻碍，往往是失速。宝剑騎士逆位说：与其硬冲，不如先降溫。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'swords_13', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（宝剑皇后正位）想对你说：走向不是「没有洞察」那种误会式的死局，而是两人的劲还拧在「洞察变成了刺」上，没一起认、也没一起动。 端坐王座一手持剑一手揚起目光銳利；最大的阻碍，是你们其中一人用清晰、界線、理性伤人而非保护——你的洞察力是礼物，用来说真话、保护自己与所爱之人，而非伤人或控制。宝剑皇后说：阻碍是「銳利未留柔软」；在保护自己的同時，留一点柔软给值得的人。 你坐着，手里拿着剑，脸上没有表情。 今天用「真话」替关系试温：你动了，场的流向才会跟着变。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「清醒」。可能是你看得很透，可能是你不抱幻想，可能是你早就知道会这样。你不装傻，不演戏，不骗自己。宝剑王后问你：你这么清醒，快乐吗？\n\n【心理层面】你怕的是「清醒了就快乐不起来了」。你看得太透了，透到连快乐都觉得是假的。你问「这段关系的本质是什么」，其实你真正想问的是：「我能不能糊涂一点，快乐一点？」\n\n【根源层面】你从小就被迫早熟。别人还在玩，你已经在想；别人还在笑，你已经在怕。你太早知道了世界的样子，也忘了自己该有的样子。宝剑王后说：清醒，不是不快乐；快乐，也不是不清醒。你可以又清醒又快乐，那是真的自由。

【走向与影响】你怕的是「柔软会受伤」。宝剑皇后正位提醒你：你真正要的，是一段可以清晰沟通与平等对话的关系。心理层面的突破，是接纳——需要清晰沟通与平等对话；洞察力不需要变成刺，你可以既清晰又溫暖。`,
  spiritLayer: `宇宙在等你把剑放下三分钟。不用一直举着，放下一会儿，感受一下不防御的感觉。也许，他不会伤害你。\n\n核心启示：你怕的不是不醒，是你怕醒了之后，发现自己从来没活过。

若问势头卡在哪，多半是「独立与洞察」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「真话」的小事：选一件你一直没说出口的、关于这段关系的真话，用不伤人的方式说一句。检查你的「行囊」：宝剑皇后问你——你銳利的，是保护还是防衛？`,
  masterSummary: `「独立与洞察」松一寸，走向就变一寸——真正的清醒不是你什么都看透，是你透的时候，还愿意相信一点。 第二问那句仍管用：你们之间最大的阻碍，往往是洞察力未留柔软。宝剑皇后说：别用来伤人。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'swords_13', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（宝剑皇后逆位）想对你说：走向被「清晰变成冷酷、洞察变成多疑或封闭」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 过度防衛、谁也不信，或用尖銳的言語推开他人——洞察力不需要变成刺；你可以既清晰又溫暖，既保护界線又愿意信任。宝剑皇后逆位说：阻碍是「过度防衛」；在保护自己的同時，留一点柔软给值得的人。 你心寒了。 你能拧动的开关往往在细节：今天把「柔软」做实，比分析十句有用。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「冷」。可能是你不再信任了，可能是你不再期待了，可能是你把自己包起来了。你不哭不笑不闹，就看着，冷冷地看。宝剑王后逆位问你：你这样冷，是因为他，还是因为你怕再热一次？\n\n【心理层面】你怕的是「再热还是会冷」。你被烫过太多次，不敢再靠近火。你问「这段关系的本质是什么」，其实你真正想问的是：「我能不热，但也不冷吗？」\n\n【根源层面】你曾经是个特别暖的人。对谁都好，对谁都信。但后来发现，你对别人好，别人不一定对你好。你冷下来了，冷到把自己冻住。但宝剑王后逆位说：你冻住自己，不是为了保护自己，是为了不再感觉。

【走向与影响】你怕的是「一软就被欺」。宝剑皇后逆位提醒你：你真正怕的，可能是信任。心理层面的突破，是问——我们是在保护还是在推开？小心过度理性、冷淡或多疑，让对方感到不被信任。`,
  spiritLayer: `宇宙在等你化一化。不是马上热，就化一点点。比如晒晒太阳，比如喝杯热茶。你化了，才知道，冷不是唯一的选择。\n\n核心启示：你怕的不是冷，是你怕化了之后，发现自己根本不会热了。

能量没有散，是聚在「过度防衛」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「柔软」的小事：选一件你习惯「用銳利回應」的事，今天用一句溫暖的话代替。检查你的「行囊」：宝剑皇后逆位问你——你封闭的，是界線还是恐惧？`,
  masterSummary: `想动走势，先认「过度防衛」这道结——真正的暖不是你没冷过，是你冷了之后，还敢再热。 对照第二问：你们之间最大的阻碍，往往是过度防衛。宝剑皇后逆位说：洞察力不需要变成刺。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'swords_14', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（宝剑国王正位）想对你说：走向不是「没有原則」那种误会式的死局，而是两人的劲还拧在「权威取代了聆听」上，没一起认、也没一起动。 端坐王座手持宝剑目光如炬；最大的阻碍，是你们其中一人用理性、原則、决斷壓制对方——权威来自公正与逻辑，而非专制；在堅持原則時，也聆听不同的觀点，才能让人心服。宝剑国王说：阻碍是「单向的权威」；在堅持原則時，也聆听不同的觀点。 你坐在高高的王座上，手里拿着剑。 你若真想推动走势，就从「聆听」开始——轻，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「决断」。可能是你做决定很快，可能是一旦决定就不回头，可能是你总是那个说了算的人。你习惯了当判官，习惯了下结论。宝剑国王问你：你下的结论，是真相，还是你想要的真相？\n\n【心理层面】你怕的是「判错了」。你太相信自己了，太信自己的判断了。但万一错了呢？你不敢想。你问「这段关系的本质是什么」，其实你真正想问的是：「我能相信我的判断吗？」\n\n【根源层面】你从小就是那个做决定的人。家里的事你拿主意，朋友的事你给建议，关系的事你说了算。你习惯了掌控，习惯了绝对。但你也知道，绝对的人，往往是最怕失控的。宝剑国王说：你的剑，是用来维持秩序的，也是用来砍自己的。

【走向与影响】你怕的是「一让就亂」。宝剑国王正位提醒你：你真正要的，是一段可以理性承诺、公平相待的关系。心理层面的突破，是接纳——傾向理性承诺、公平相待；关系需要对话而非審判。`,
  spiritLayer: `宇宙在等你听一次心。不是分析，不是判断，就听心。它可能不讲道理，但它不会错。\n\n核心启示：你怕的不是判错，是你怕判错了之后，再也没人相信你了。

若问势头卡在哪，多半是「权威与判斷」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「聆听」的小事：选一件你习惯「我来定规矩」的事，今天先问对方「你觉得呢？」检查你的「行囊」：宝剑国王问你——你的权威，是服務公正还是服務 ego？`,
  masterSummary: `「权威与判斷」松一寸，走向就变一寸——真正的国王不是他不犯错，是他犯了错之后，还敢再判。 第二问那句仍管用：你们之间最大的阻碍，往往是权威未聆听。宝剑国王说：权威来自让人心服。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'swords_14', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（宝剑国王逆位）想对你说：走向被「权威变成专制、判斷变成濫权或优柔寡斷」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 听不进意见、用权力壓人，或不敢决策、把责任推给别人——你的判斷是服務公正，还是服務 ego？在该决斷時决斷，在该傾听時傾听；真正的权威来自让人心服，不是让人害怕。宝剑国王逆位说：阻碍是「权威的错用」；真正的权威来自让人心服。 你乱砍了。 别等对方先示范。今天你先用「让权」给关系一个可跟的节拍。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「武断」。可能是你太急着下结论，可能是你不听解释，可能是你一刀切了。你觉得痛快，但也后悔。宝剑国王逆位问你：你砍的时候，想过后果吗？\n\n【心理层面】你怕的是「后悔」。你太怕自己选错了，太怕以后想起来怪自己。但你已经选了，已经砍了，能怎么办？你问「这段关系的本质是什么」，其实你真正想问的是：「我能收回我的剑吗？」\n\n【根源层面】你一直是个果断的人。想就做，做就不后悔。但你发现，不后悔的人，其实最后悔。只是不说。宝剑国王逆位说：你后悔的不是砍错了，是砍之前，没看他的眼睛。

【走向与影响】你怕的是「一软就没权威」。宝剑国王逆位提醒你：你真正怕的，可能是失控。心理层面的突破，是问——我们是在主导还是在壓制？关系需要对话而非審判；在原則与彈性之间取得平衡。`,
  spiritLayer: `宇宙在等你停下来。不砍了，不判了，就停下来。停了，你才能看见，他其实一直在等你回头。\n\n核心启示：你怕的不是砍错，是你怕砍了之后，发现根本没人让你砍。

就走向而言，两人的气机还绕在「专制或优柔寡斷」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「让权」的小事：选一件你习惯「我说了算」的事，今天让对方做决定或一起决定。检查你的「行囊」：宝剑国王逆位问你——你的判斷，是公正还是 ego？`,
  masterSummary: `走向的纽子在「专制或优柔寡斷」——真正的国王不是他不犯错，是他错了之后，还敢认错。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是权威的错用。宝剑国王逆位说：真正的权威来自让人心服。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'pentacles_1', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（钱币一正位）想对你说：走向不是「没有机会」那种误会式的死局，而是两人的劲还拧在「第一顆种子没有一起种」上，没一起认、也没一起动。 雲中手捧钱币、下方繁花拱门；最大的阻碍，是你们没有把「我们要一起打什么基礎」化成具體行动——新緣分、同居或关系进入「一起打基礎」的阶段，需要先把第一个具體行动做出来。钱币一说：阻碍是「起点未成」；先种下种子，才能談收成。 云中伸出一只手，托着一枚金币。 别等对方先示范。今天你先用「种子」给关系一个可跟的节拍。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「实在感」。可能是你们见面了，可能是你们在一起生活了，可能是你们开始计划未来了。不再只是聊天，不再只是想象，是真的在一起。星币王牌问你：你准备好接住这份实在了吗？\n\n【心理层面】你怕的是「太实在了就不浪漫了」。你把爱想得太梦幻，怕一落地就俗了。但星币王牌告诉你：真正的情话，不是「我爱你」，是「今晚吃什么」。你问「这段关系的本质是什么」，其实你真正想问的是：「落地之后，爱还在吗？」\n\n【根源层面】你从小就被童话喂大，觉得爱应该是云上的事。但你忘了，云上的，是神仙；地上的，才是人。你要的是人，不是神仙。星币王牌说：人的爱，就是柴米油盐里的那一点甜。

【走向与影响】你怕的是「基礎不稳」。钱币一正位提醒你：你真正要的，是一段可以一起打基礎的关系。心理层面的突破，是接纳——土元素的力量在累積，先做出一点可见的成果。`,
  spiritLayer: `宇宙在等你把手伸出来。接住那枚金币，接住这份实在。你接了，才能用，才能花，才能变成你生活的一部分。\n\n核心启示：你怕的不是现实，是你怕现实之后，发现梦是假的。

就走向而言，两人的气机还绕在「种子」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「种子」的小事：为这段关系做一件「打基礎」的具體事——一个约定、一次共同计画、或一筆一起存的钱。检查你的「行囊」：钱币一问你——你种的，是两个人的未来还是自己的安全感？`,
  masterSummary: `走向的纽子在「种子」——真正的爱不是你天天说情话，是你天天问他「吃了吗」。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是第一顆种子未一起种。钱币一说：先做出来再談擴张。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'pentacles_1', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（钱币一逆位）想对你说：走向被「机会延迟、错失或准备不足」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 時机未到、資源还没到位，或迟迟不把计画付諸行动——先稳住自己再談承诺；该學的學、该存的存、该练的练，机会会再来。钱币一逆位说：阻碍是「未准备好」；下次要准备好伸手接住。 金币掉地上了。 你若真想推动走势，就从「准备」开始——轻，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「错过」。可能是他给了你机会，你没接；可能是他主动了，你躲了。你以为还会有更好的，但星币王牌逆位问你：你等的那个更好的，真的会来吗？\n\n【心理层面】你怕的是「接了就定了」。你怕一确定，就再也没机会选了。所以你一直拖着，一直等，一直告诉自己「再等等」。你问「这段关系的本质是什么」，其实你真正想问的是：「能不能永远有更好的？」\n\n【根源层面】你从小就被教「不要将就」。将就了，就是委屈自己了。你把这句话用得太狠，狠到连好的都不敢要，怕它不够好。但星币王牌逆位说：你一直不接，就永远没有。最好的，是接住的那个。

【走向与影响】你怕的是「一动就垮」。钱币一逆位提醒你：你真正怕的，可能是还没准备好。心理层面的突破，是问——我们是時机未到，还是不敢动？先把基礎打好。`,
  spiritLayer: `宇宙在等你低头捡起来。它就在你脚边，你低一下头就能看见。你一直抬头看远方，永远看不见脚下的。\n\n核心启示：你怕的不是不够好，是你怕够了之后，就再也不能追更好的了。

能量没有散，是聚在「未准备好」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「准备」的小事：为这段关系列出一件「我们还没准备好的是_____」，並做一个最小的准备动作。检查你的「行囊」：钱币一逆位问你——你等的，是時机还是勇气？`,
  masterSummary: `想动走势，先认「未准备好」这道结——真正的开始不是等最好的，是你敢接住眼前的，然后把它变成最好的。 对照第二问：你们之间最大的阻碍，往往是未先把基礎打好。钱币一逆位说：机会会再来，下次准备好接住。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'pentacles_2', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（钱币二正位）想对你说：走向不是「没有資源」那种误会式的死局，而是两人的劲还拧在「平衡未取舍」上，没一起认、也没一起动。 雜耍者手捧两枚钱币在波浪中求平衡；最大的阻碍，是你们在工作与关系、或两个对象之间摆盪——在取舍時，选「可持续」而非「最多」；专注在少数真正重要的事。钱币二说：阻碍是「未取舍」；专注少数真正重要的事。 你手里有两个金币，在上下翻飞。 你能拧动的开关往往在细节：今天把「取舍」做实，比分析十句有用。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「平衡」。可能是你要平衡他和工作，可能是要平衡爱自己和爱他。你觉得累，但你不能停。星币二问你：你这么转，是为了谁？\n\n【心理层面】你怕的是「掉一个就全没了」。你拼命转，拼命接，不敢停。但越怕掉，越容易掉。你问「这段关系的本质是什么」，其实你真正想问的是：「我能不能只接一个？」\n\n【根源层面】你从小就要做很多事。功课要第一，朋友要维护，爸妈要满意。你学会了转，学会了兼顾，学会了面面俱到。但你不知道，一直转的人，最后会晕。星币二说：你可以放下来一个，歇一会儿。

【走向与影响】你怕的是「选错就没了」。钱币二正位提醒你：你真正要的，可能是在两边之间不失控。心理层面的突破，是接纳——在变动中維持平衡、或正在評估要往哪里分配資源。`,
  spiritLayer: `宇宙在等你放下来。不用一直转，放下来一个，喘口气。喘完再拿起来，它还在。\n\n核心启示：你怕的不是转不动，是你怕一停，就接不住了。

若问势头卡在哪，多半是「取舍」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「取舍」的小事：寫下「这段关系里，我们最不能放弃的两件事是_____」。检查你的「行囊」：钱币二问你——你平衡的，是两边都要还是两边都怕失去？`,
  masterSummary: `「取舍」松一寸，走向就变一寸——真正的平衡不是你一直转，是你敢停的时候，还能稳。 第二问那句仍管用：你们之间最大的阻碍，往往是未在取舍時选可持续。钱币二说：专注少数真正重要的事。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'pentacles_2', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（钱币二逆位）想对你说：走向被「平衡被打破」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 失衡、混亂、或过度貪心——什么都想抓，结果什么都抓不稳；不做选择也是最耗損的选择。钱币二逆位说：阻碍是「未选」；列出优先順序，做出选择；不能什么都要。 你掉了一个。 今天用「选」替关系试温：你动了，场的流向才会跟着变。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「失衡」。可能是顾了工作忘了他，可能是顾了他忘了自己。你觉得对不起这个，又对不起那个。星币二逆位问你：你选哪个？\n\n【心理层面】你怕的是「选了就对不起另一个」。你太想对得起所有人了，结果谁也对不起。你问「这段关系的本质是什么」，其实你真正想问的是：「我能不能都要？」\n\n【根源层面】你从小就是个好孩子。好孩子不让任何人失望。你把这句话带到现在，让谁也不失望的结果，是让你自己失望。星币二逆位说：你失望一次，才知道，失望不会死。

【走向与影响】你怕的是「选了就失去另一边」。钱币二逆位提醒你：你真正怕的，可能是取舍。心理层面的突破，是问——我们是在平衡还是在逃避选？收斂戰線，专注一两个主線。`,
  spiritLayer: `宇宙在等你选一个。不是永远选，就现在选一个。选了，你就知道，另一个不会跑远。\n\n核心启示：你怕的不是选，是你怕选了之后，发现自己选错了。

就走向而言，两人的气机还绕在「该选未选」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「选」的小事：在「工作与关系」或「两个选项」间，选一个今天优先。检查你的「行囊」：钱币二逆位问你——你摆盪的，是两边都爱还是两边都不敢放？`,
  masterSummary: `走向的纽子在「该选未选」——真正的平衡不是你同时接住两个，是你掉了一个之后，还能把那个捡起来。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是未做出取舍。钱币二逆位说：不做选择是最耗損的选择。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'pentacles_3', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（钱币三正位）想对你说：走向不是「没有合作」那种误会式的死局，而是两人的劲还拧在「技能与分工未一起磨」上，没一起认、也没一起动。 工匠在教堂前協力施工；最大的阻碍，是你们没有一起规划未来、共同经营生活、或一方独扛——在专業上持续精进，成果会累積；品质比数量重要。钱币三说：阻碍是「未協力」；一起打磨，关系才有根基。 你在建一座教堂。 走向听行动。今天只兑现「協力」——让对方看见你在动，而不是在讲。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「合作」。可能是你们一起规划未来，可能是你们一起解决问题，可能是你们分工明确，各司其职。你觉得这样挺好，但也怕太分工了就没感情了。星币三问你：你们是合作伙伴，还是爱人？\n\n【心理层面】你怕的是「一起做事会忘了爱」。你怕日子过成了流程，爱过成了任务。你问「这段关系的本质是什么」，其实你真正想问的是：「天天一起做事，还叫谈恋爱吗？」\n\n【根源层面】你从小就觉得爱应该是轻松的，不费力的。但现在发现，爱也要干活，也要一起扛。你把「轻松」当成了标准，但星币三说：一起扛过活的，才分不开。

【走向与影响】你怕的是「合作会失衡」。钱币三正位提醒你：你真正要的，是一段可以一起打磨、一起成长的关系。心理层面的突破，是接纳——土元素不追求速成，而是稳扎稳打的成长。`,
  spiritLayer: `宇宙在等你和他一起砌墙。不是砌给别人看，是砌给你们自己住。砌好了，你们就有家了。\n\n核心启示：你怕的不是一起做事，是你怕做完了事，就没话说了。

就走向而言，两人的气机还绕在「打磨」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「協力」的小事：和对方一起完成一件「需要两人合作」的小事。检查你的「行囊」：钱币三问你——你们磨的，是关系还是各自的成就？`,
  masterSummary: `走向的纽子在「打磨」——真正的合作不是你们一起干活，是干完活之后，还想一起干。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是未一起協力打磨。钱币三说：品质比数量重要。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'pentacles_3', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（钱币三逆位）想对你说：走向被「品质不足、孤軍奮戰或需精进」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 團隊不同心、成品不如预期、或该合作却单打独鬥——需要分工与沟通，不能一方独扛。钱币三逆位说：阻碍是「未分工」；磨练一项核心能力、或找对的人協作。 你一个人在搬砖。 你要影响走向，今天就卡这一格：把「分工」做到底，小不要紧，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「单干」。可能是你一个人扛了太多，可能是他总是不帮忙，可能是你不好意思开口。你一个人撑着，撑得快要倒了。星币三逆位问你：你不说，他怎么知道要帮你？\n\n【心理层面】你怕的是「说了他也不帮」。你太怕失望了，所以干脆不开口。你一个人扛着，心里委屈，但脸上不说。你问「这段关系的本质是什么」，其实你真正想问的是：「我这么累，他看不见吗？」\n\n【根源层面】你从小就是那个「懂事」的。爸妈忙，你自己玩；朋友累，你自己扛。你习惯了不开口，习惯了不说话。但你不知道，不开口的人，没人知道她疼。星币三逆位说：疼了，要说出来。

【走向与影响】你怕的是「依賴对方」。钱币三逆位提醒你：你真正怕的，可能是分工等于失去控制。心理层面的突破，是问——我们是在合作还是一方独扛？加強专業或改善團隊協調。`,
  spiritLayer: `宇宙在等你开一次口。你说「我需要你」，他不会跑，他可能会来。你不说，他永远不知道。\n\n核心启示：你怕的不是他不行，是你怕说了之后，发现他真的不行。

若问势头卡在哪，多半是「未協作好」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「分工」的小事：和对方談一次「我们可以怎麼分工_____」。检查你的「行囊」：钱币三逆位问你——你独扛的，是爱还是不信任？`,
  masterSummary: `「未協作好」松一寸，走向就变一寸——真正的合作不是你一个人扛，是你敢说「帮帮我」的时候，他也敢伸手。 第二问那句仍管用：你们之间最大的阻碍，往往是未一起分工協作。钱币三逆位说：不能一方独扛。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'pentacles_4', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（钱币四正位）想对你说：走向不是「没有稳定」那种误会式的死局，而是两人的劲还拧在「稳固擋住了流动」上，没一起认、也没一起动。 一人稳坐城中头顶脚踏怀抱钱币；最大的阻碍，是你们其中一人或两人过度紧握——安全感、控制、或「我的」——没有留一点流动给机会与人。钱币四说：阻碍是「过度紧握」；在稳固的同時，留一点流动给机会；安全与流动可以並存。 你紧紧抱着四个金币，一个踩在脚下，一个抱在怀里，一个顶在头上，一个攥在手里。 你要影响走向，今天就卡这一格：把「流动」做到底，小不要紧，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「守」。可能是你守着他，可能是你守着这段感情，可能是你守着那点安全感。你不敢松手，不敢放松，不敢给他一点自由。星币四问你：你守的，是他，还是你怕失去他的心？\n\n【心理层面】你怕的是「一松手就没了」。你把这段感情当成了四个金币，抓得死死的，抓到自己都疼。你问「这段关系的本质是什么」，其实你真正想问的是：「我松了，他还在吗？」\n\n【根源层面】你曾经失去过。失去过重要的东西，失去过重要的人。那次之后，你就再也不肯松手了。但你忘了，抓着的东西，也会被你抓死。星币四说：你把手张开，他才能呼吸。

【走向与影响】你怕的是「一流动就没了」。钱币四正位提醒你：你真正要的，是一段可以稳稳握住的关系。心理层面的突破，是接纳——过度紧握可能阻碍流动，適度保留彈性才能让机会与人际自然进门。`,
  spiritLayer: `宇宙在等你松开一根手指。不用全松，就一根。你松了，看看会不会掉。不会掉，就再松一根。\n\n核心启示：你怕的不是失去他，是你怕失去他之后，发现自己手里什么都没有了。

就走向而言，两人的气机还绕在「持有」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「流动」的小事：在「一直紧握」的某件事上，做一个小小的放松。检查你的「行囊」：钱币四问你——你握的，是爱还是恐惧？`,
  masterSummary: `走向的纽子在「持有」——真正的安全感不是你抓得紧，是你松手的时候，他还愿意回来。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是稳固擋住了流动。钱币四说：安全与流动可以並存。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'pentacles_4', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（钱币四逆位）想对你说：走向被「稳固变成吝嗇、僵化或该適度分享」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 难以付出或信任他人、內在安全感不足；或该流动時却紧抓——我是在守护该守的，还是在用控制掩蓋不安？钱币四逆位说：阻碍是「未流动」；在稳固的同時，留一点流动给机会与人。。 你松手了。 走向听行动。今天只兑现「开门」——让对方看见你在动，而不是在讲。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「失控」。可能是他走了，可能是你放手了，可能是你终于不抓了。你看着满地滚的金币，不知道先捡哪个。星币四逆位问你：你捡的是你想要的，还是你舍不得的？\n\n【心理层面】你怕的是「捡不回来了」。你眼睁睁看着金币滚远，觉得再也回不来了。你问「这段关系的本质是什么」，其实你真正想问的是：「我还能不能捡回来？」\n\n【根源层面】你一直以为抓得住的东西才是你的。但现在发现，抓得住的也会跑。你慌了，不知道什么才是真的。但星币四逆位说：跑了的，不是你的；没跑的，才是。

【走向与影响】你怕的是「一给就没了」。钱币四逆位提醒你：你真正怕的，可能是匱乏。心理层面的突破，是问——我们是在守护还是在控制？小心过度掌控、不肯付出或信任不足让对方疏離。`,
  spiritLayer: `宇宙在等你站起来。不捡了，就让它滚。你站起来，看看手，空的。空着，才能接新的。\n\n核心启示：你怕的不是没了，是你怕没了之后，发现自己本来就不该抓。

能量没有散，是聚在「过度紧握」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「开门」的小事：选一件你一直「紧抓不放」的事，做一个小小的分享或信任的动作。检查你的「行囊」：钱币四逆位问你——你紧抓的，是爱还是不安？`,
  masterSummary: `想动走势，先认「过度紧握」这道结——真正的拥有不是你抓住多少，是你松开之后，还能自己站着。 对照第二问：你们之间最大的阻碍，往往是稳固時未留流动。钱币四逆位说：别用控制掩蓋不安。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'pentacles_5', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（钱币五正位）想对你说：走向不是「没有爱」那种误会式的死局，而是两人的劲还拧在「匱乏与困难未被一起面对」上，没一起认、也没一起动。 两人在風雪中经过亮着燈的教堂却未进入；最大的阻碍，是你们其中一人或两人没有在艱难期互相支援、简化需求、或接受幫助——接受幫助不是软弱，先稳住基本盤，相信会好转。钱币五说：阻碍是「未共同度冬」；在困难時接受幫助，並相信会好转。 你在雪地里走，脚破了，衣服薄，肚子饿。 今天用「接受」替关系试温：你动了，场的流向才会跟着变。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「匮乏」。可能是你觉得不够爱，可能是你觉得不够好，可能是你觉得不够多。你站在幸福门外，看着里面的光，但觉得自己不配进去。星币五问你：是他不让你进，还是你自己不敢进？\n\n【心理层面】你怕的是「进去了也被赶出来」。你太怕被拒绝，所以宁可站在外面冷。你问「这段关系的本质是什么」，其实你真正想问的是：「我配被爱吗？」\n\n【根源层面】你从小就被打击惯了。家里说你不配，老师说不配，朋友说你不配。你信了，信到现在，连爱来了都不敢接。但星币五说：那是他们说的，不是真的。

【走向与影响】你怕的是「接受幫助等于弱」。钱币五正位提醒你：你真正要的，是一段可以一起度过寒冬的关系。心理层面的突破，是接纳——如实呈现「当下的难」；简化需求、稳住基本盤，比硬撐更重要。`,
  spiritLayer: `宇宙在等你敲门。门没锁，你一敲就开。里面的人不会赶你，他们也在等你。\n\n核心启示：你怕的不是被拒绝，是你怕敲了门之后，发现根本没人理你。

这条关系的走势，眼下还拴在「寒冬」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「接受」的小事：选一件你一直「自己扛」的事，向对方或外界求一次支援。检查你的「行囊」：钱币五问你——你硬撐的，是爱还是自尊？`,
  masterSummary: `势头绕在「寒冬」上——真正的穷不是你什么都没有，是你有门不敢敲。 第二问早已点破：你们之间最大的阻碍，往往是艱难時未接受幫助。钱币五说：接受幫助不是软弱。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'pentacles_5', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（钱币五逆位）想对你说：走向被「艱难期逐漸改善未完成」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 貴人出现、某个資源到位、或心态转变后看见新的可能——不要因自尊而拒绝援手；最难的時刻会过去，你会比想像中更韌性。钱币五逆位说：阻碍是「未接受幫助」；困难時接受幫助，並相信会好转。 你从雪地里站起来了。 你能拧动的开关往往在细节：今天把「感恩」做实，比分析十句有用。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「被接住」。可能是他终于回应了，可能是他终于给了你想要的。你不再一个人站在外面，你进来了，暖了。星币五逆位问你：你现在还觉得不配吗？\n\n【心理层面】你怕的是「暖了还会冷」。你太怕反复，怕得到又失去。你问「这段关系的本质是什么」，其实你真正想问的是：「这次能一直暖吗？」\n\n【根源层面】你被伤过太多次。每次以为有家了，家又散了。你不敢再信，不敢再暖。但星币五逆位说：这次不一样，因为你学会了敲门。

【走向与影响】你怕的是「依賴会惯性」。钱币五逆位提醒你：你真正怕的，可能是习惯被幫。心理层面的突破，是接纳——最难的已经过去；不要因一時匱乏就否定自己的价值。`,
  spiritLayer: `宇宙在等你暖一会儿。不用想以后，就现在，暖一会儿。暖够了，你才知道，暖的感觉，值得再试一次。\n\n核心启示：你怕的不是不暖，是你怕暖了之后，还要再冷一次。

若问势头卡在哪，多半是「復原中」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「感恩」的小事：对曾经幫助过你们的人或彼此，说一句感谢。检查你的「行囊」：钱币五逆位问你——你走出来的，是接受幫助还是自己硬撐？`,
  masterSummary: `「復原中」松一寸，走向就变一寸——真正的暖不是永远不冷，是你冷的时候，知道有个门可以敲。 第二问那句仍管用：你们之间最大的阻碍，往往是未相信会好转。钱币五逆位说：最难的時刻会过去。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'pentacles_6', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（钱币六正位）想对你说：走向不是「没有给予」那种误会式的死局，而是两人的劲还拧在「施与受未平衡」上，没一起认、也没一起动。 施予者向乞討者分发钱币、天平在手；最大的阻碍，是你们其中一人一直给、一方一直收，或金钱与感情界線混亂——在能力範圍內慷慨，同時允許自己接受；单向的付出或索取久了都会失衡。钱币六说：阻碍是「单向流动」；给予也要接受。 你在给。 你若真想推动走势，就从「接受」开始——轻，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「给与收」。可能是你一直在给，他一直在收。你觉得这就是爱，但你也累了。星币六问你：你给这么多，是想让他爱你，还是想证明你值得被爱？\n\n【心理层面】你怕的是「给了也换不回爱」。你把给当成了交易，以为给够了，他就会爱你。但他一直收，一直不给，你开始慌了。你问「这段关系的本质是什么」，其实你真正想问的是：「我给了这么多，他怎么还不给我？」\n\n【根源层面】你从小就被教育「付出就有回报」。你对这句话深信不疑，一直付出，一直等回报。但感情不是数学，付出不一定有回报。星币六说：你给，是因为你愿意；他不给，也是因为他愿意。你们是两个人，不是一个算式。

【走向与影响】你怕的是「接受等于欠」。钱币六正位提醒你：你真正要的，是一段可以互相给、互相收的关系。心理层面的突破，是接纳——在能力範圍內给予，同時允許自己接受。`,
  spiritLayer: `宇宙在等你收一次。不是收钱，是收爱。他给你的时候，你别推开，接着。接着了，你就知道，收的感觉，比给好。\n\n核心启示：你怕的不是不给，是你怕给了之后，发现自己根本收不到。

这条关系的走势，眼下还拴在「流动」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「接受」的小事：选一件你习惯「只给不收」的事，今天允許自己接受一次。检查你的「行囊」：钱币六问你——你给的，是丰盛还是討爱？`,
  masterSummary: `势头绕在「流动」上——真正的爱不是你一直给，是你敢收的时候，还不觉得自己欠他。 第二问早已点破：你们之间最大的阻碍，往往是施与受未平衡。钱币六说：单向久了都会失衡。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'pentacles_6', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（钱币六逆位）想对你说：走向被「流动被阻斷」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 单向付出却收不到对等回报、債務或界線不清、或用「给予」来控制对方——若你总在给却从不收，檢視是否在回避「被照顧」的脆弱；界線清楚，流动才会健康。钱币六逆位说：阻碍是「施与受失衡」；界線清楚，流动才健康。 你在要。 别等对方先示范。今天你先用「界線」给关系一个可跟的节拍。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「索取」。可能是你一直在等他的消息，等他的回应，等他的爱。你觉得这是你应该得的，但他不给，你就委屈。星币六逆位问你：你等的这些，是他欠你的，还是你想要的？\n\n【心理层面】你怕的是「等不到」。你太想被给了，太想要了，所以一直等。但你越等，越空。你问「这段关系的本质是什么」，其实你真正想问的是：「我什么时候才能等到？」\n\n【根源层面】你从小就被惯坏了。想要什么，有人给；想怎么样，有人让。你习惯了被给，习惯了自己是中心。但现在，他不给，你就不会了。星币六逆位说：你一直等别人给，从来没想过，自己也能给。

【走向与影响】你怕的是「要就掉价」。钱币六逆位提醒你：你真正怕的，可能是被说貪心。心理层面的突破，是问——我们是在流动还是在控制？该爭取的爭取，该签约的签约。`,
  spiritLayer: `宇宙在等你先给一次。不是给他，是给自己。自己给自己一点爱，一点关心。给了，你就知道，你不等别人，也能有。\n\n核心启示：你怕的不是得不到，是你怕得不到之后，发现自己什么也给不了自己。

若问势头卡在哪，多半是「施与受失衡」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「界線」的小事：和对方談一次「我们在金钱／付出上，可以怎麼对等或界線」。检查你的「行囊」：钱币六逆位问你——你单向给的，是爱还是控制？`,
  masterSummary: `「施与受失衡」松一寸，走向就变一寸——真正的拥有不是你等到什么，是你自己就能给自己什么。 第二问那句仍管用：你们之间最大的阻碍，往往是施与受未平衡。钱币六逆位说：界線清楚，流动才健康。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'pentacles_7', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（钱币七正位）想对你说：走向不是「没有投資」那种误会式的死局，而是两人的劲还拧在「等待未同步」上，没一起认、也没一起动。 一人倚杖望树上结实、脚边已有收成；最大的阻碍，是你们对「结果什么時候到」「要等多久」没有共識——在等待時持续做对的事，而非焦慮结果；檢視方向是否正确，若对就繼续。钱币七说：阻碍是「未对齊的等待」；方向对了就繼续。 你站在自己种的树前面。 把力气花在看得见的一步：今天只做「檢視」，做完就停。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「等待期」。可能是你们在一起很久了，但还是没结果；可能是你付出了很多，但还是没回报。你开始怀疑，开始动摇。星币七问你：你等的，是那个结果，还是等自己死心？\n\n【心理层面】你怕的是「白等了」。你怕付出了那么多，最后一场空。你问「这段关系的本质是什么」，其实你真正想问的是：「我还能等到吗？」\n\n【根源层面】你是个有耐心的人。从小就等，等长大，等毕业，等工作。你相信等就会有结果。但感情不是这样，等不一定有结果，可能只是让你看清单行线。星币七说：你再等，树也不会长快。你要的，是树，还是果子？

【走向与影响】你怕的是「等不到」。钱币七正位提醒你：你真正要的，是一段经得起等待的关系。心理层面的突破，是接纳——在等待時持续做对的事，比焦慮结果更有力量。`,
  spiritLayer: `宇宙在等你决定。不是决定等不等，是决定要不要这棵树。如果要，就继续浇水；如果不要，就砍了种别的。你站着不动，树不会变。\n\n核心启示：你怕的不是等不到，是你怕等到了之后，发现不是你想要的。

若问势头卡在哪，多半是「播种后等待」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「檢視」的小事：寫下一句「这段关系我们已经种下的是_____；我们在等的是_____」。检查你的「行囊」：钱币七问你——你等的，是收成还是奇蹟？`,
  masterSummary: `「播种后等待」松一寸，走向就变一寸——真正的等待不是你一直站着，是你站着的时候，还在浇水。 第二问那句仍管用：你们之间最大的阻碍，往往是等待未同步。钱币七说：方向对了就繼续。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'pentacles_7', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（钱币七逆位）想对你说：走向被「等待变成怀疑、放弃或策略错誤」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 开始怀疑自己的投入是否值得、或方向从头就错了却一直硬撐——檢視方向是否正确；若对保持耐心，若不对調整策略再投。钱币七逆位说：阻碍是「未檢視方向」；错了就調整策略。 你等不下去了。 影响走向不靠喊话，靠落地。今天完成「决定」，再谈别的。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「想放弃」。可能是你累了，可能是你不想再等了，可能是你觉得不值得。你想走，但又怕走错了。星币七逆位问你：你放弃的，是这段关系，还是你自己？\n\n【心理层面】你怕的是「放弃也错」。你怕走也是错，留也是错。你卡在中间，不知道该往哪边。你问「这段关系的本质是什么」，其实你真正想问的是：「我该不该放手？」\n\n【根源层面】你太容易放弃了。从小到大，一难就撤，一累就停。你从来没学会坚持，也从来没学会放手。你只是躲。星币七逆位说：你不砍不浇，就站着看，树会死的。

【走向与影响】你怕的是「一收就没了」。钱币七逆位提醒你：你真正怕的，可能是收成不如预期。心理层面的突破，是问——我们等的方向对吗？该止損就止損，该收成就收成。`,
  spiritLayer: `宇宙在等你选一边。不是选对，是选。选了，你就往前走；不选，你就永远卡着。\n\n核心启示：你怕的不是选错，是你怕选了之后，发现自己根本没种过。

这条关系的走势，眼下还拴在「策略或時机」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「决定」的小事：对「这段关系我们要繼续等还是調整」做一个小决定。检查你的「行囊」：钱币七逆位问你——你硬撐的，是爱还是沉没成本？`,
  masterSummary: `势头绕在「策略或時机」上——真正的放弃不是你走了，是你走了之后，还不后悔自己来过。 第二问早已点破：你们之间最大的阻碍，往往是未檢視方向。钱币七逆位说：错了就調整策略。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'pentacles_8', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（钱币八正位）想对你说：走向不是「没有努力」那种误会式的死局，而是两人的劲还拧在「努力未一起磨」上，没一起认、也没一起动。 工匠专注雕琢钱币；最大的阻碍，是你们没有把「我们要一起磨什么」拆成小步驟、一步步做——以实际行动经营关系、一起努力；成果来自重复与紀律，休息是为了对准目标再出发。钱币八说：阻碍是「未拆步驟」；把大目标拆成小步驟，一步步做。 你在刻金币。 影响走向不靠喊话，靠落地。今天完成「小步驟」，再谈别的。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「经营」。可能是你一直在努力，一直在付出，一直在打磨。你觉得自己很认真，很投入。但星币八问你：你经营得这么好，是为了他，还是为了证明自己？\n\n【心理层面】你怕的是「白经营了」。你怕自己这么努力，他却不领情。你问「这段关系的本质是什么」，其实你真正想问的是：「我这么认真，他能看见吗？」\n\n【根源层面】你从小就是个努力的人。努力就有回报，这是你的人生信条。你把这个信条带进感情，以为努力了，他就会更爱你。但星币八说：感情不是工作，努力不一定有回报。

【走向与影响】你怕的是「一停就前功尽弃」。钱币八正位提醒你：你真正要的，是一段可以一起努力、一起磨的关系。心理层面的突破，是接纳——倦怠時休息，但不要放弃对准的目标。`,
  spiritLayer: `宇宙在等你抬头看一眼。你看他，他在干嘛？是在看你刻的，还是在刻他自己的？你抬头看了，就知道了。\n\n核心启示：你怕的不是不努力，是你怕努力了之后，发现根本没人在看。

若问势头卡在哪，多半是「精进」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「小步驟」的小事：把「这段关系我们要磨的是_____」拆成一个今天就能做的小步驟，並完成它。检查你的「行囊」：钱币八问你——你们磨的，是关系还是各自的事業？`,
  masterSummary: `「精进」松一寸，走向就变一寸——真正的经营不是你一直刻，是你刻的时候，知道有人会用。 第二问那句仍管用：你们之间最大的阻碍，往往是未把大目标拆成小步驟。钱币八说：休息是为了再出发。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'pentacles_8', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（钱币八逆位）想对你说：走向被「勤奮变成倦怠、敷衍或方向错誤」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 Burnout、做白工、或一直在磨一把错的刀——只忙工作忽略伴侶、或关系中有一方敷衍了事；若方向对了，適度休息再繼续；若方向错了，停下来重新对焦。钱币八逆位说：阻碍是「未对焦」；不要在不对的路上死撐。 你刻不下去了。 把力气花在看得见的一步：今天只做「休息或对焦」，做完就停。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「迷失」。可能是你不知道为什么还要继续，可能是你不知道爱他什么了。你还在做那些事，但心已经不在。星币八逆位问你：你在做的这些，是为了什么？\n\n【心理层面】你怕的是「不知道为了什么」。你一直做，一直做，做到现在，突然发现自己不知道在干嘛。你问「这段关系的本质是什么」，其实你真正想问的是：「我还在干什么？」\n\n【根源层面】你太会按部就班了。别人怎么做，你就怎么做；以前怎么做，现在就怎么做。你从来没想过，自己到底想要什么。星币八逆位说：你不知道，是因为你从来没问过自己。

【走向与影响】你怕的是「一停就被说不爱」。钱币八逆位提醒你：你真正怕的，可能是被说不努力。心理层面的突破，是问——我们是在努力还是在逃避？该調整就調整，该休息就休息。`,
  spiritLayer: `宇宙在等你停下来。不刻了，不做了，就停着。停了，你才能听见自己的声音。\n\n核心启示：你怕的不是不刻了，是你怕停了之后，发现自己根本不想要这个金币。

若问势头卡在哪，多半是「过勞或方向错誤」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「休息或对焦」的小事：选一件你一直「硬撐」的事，要麼休息，要麼重新对焦。检查你的「行囊」：钱币八逆位问你——你磨的，是对的刀还是错的刀？`,
  masterSummary: `「过勞或方向错誤」松一寸，走向就变一寸——真正的停不是你放弃了，是你停了之后，还能想清楚要不要继续。 第二问那句仍管用：你们之间最大的阻碍，往往是未休息或未对焦。钱币八逆位说：不要在不对的路上死撐。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'pentacles_9', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（钱币九正位）想对你说：走向不是「没有丰盛」那种误会式的死局，而是两人的劲还拧在「丰盛未分享」上，没一起认、也没一起动。 一人立于丰饒园中手腕停鷹；最大的阻碍，是你们其中一人或两人「什么都有」却不愿与对方分享——关系稳定、物质无虞，但富足若只囤積不流动，会变成孤島。钱币九说：阻碍是「孤島」；在丰盛時感恩，並考慮与人分享。 你站在自己的花园里。 别等对方先示范。今天你先用「分享」给关系一个可跟的节拍。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「独立」。可能是你能自己照顾自己，可能是你不靠他养，可能是你有自己的空间。你觉得这样很好，但也怕太独立了就不需要他了。星币九问你：你能一个人，还需要他吗？\n\n【心理层面】你怕的是「不需要他了，他就会走」。你一直觉得，需要他，他才会在。但现在你发现自己也能活，你慌了。你问「这段关系的本质是什么」，其实你真正想问的是：「我不需要他，他还爱我吗？」\n\n【根源层面】你从小就被教「要独立」。自己赚钱，自己生活，自己解决问题。你做到了，但你发现，太独立了，就没人陪了。星币九说：独立和陪伴，不是反的。你能独立，才能选人，不是等人选你。

【走向与影响】你怕的是「一分享就没了」。钱币九正位提醒你：你真正要的，是一段可以既自足又连结的关系。心理层面的突破，是接纳——与人分享会加倍丰盛。`,
  spiritLayer: `宇宙在等你享受自己的花园。你种的花，你自己看；你养的鸟，你自己陪。你满了，才能溢出来给他。你不满，给的都是渴。\n\n核心启示：你怕的不是一个人，是你怕一个人之后，发现自己根本不需要他。

这条关系的走势，眼下还拴在「收成」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「分享」的小事：在这段关系里做一件「把丰盛分享给对方」的事。检查你的「行囊」：钱币九问你——你的富足，是拿来囤的还是拿来用的？`,
  masterSummary: `势头绕在「收成」上——真正的独立不是你不需要任何人，是你需要的时候，还能选。 第二问早已点破：你们之间最大的阻碍，往往是丰盛未分享。钱币九说：富足不流动会成孤島。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'pentacles_9', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（钱币九逆位）想对你说：走向被「富足变成不安、貪婪或孤独」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 什么都有却不快樂、或过度紧抓資源不肯流动——「什么都有却没有溫度」，需要把資源与情感分享给伴侶；丰盛是拿来用的，不是拿来囤的。钱币九逆位说：阻碍是「未流动」；与人分享会加倍丰盛。 你的花园荒了。 你若真想推动走势，就从「流动」开始——轻，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「荒芜」。可能是你们很久没好好说话了，可能是你们很久没见面了，可能是你们的心离得越来越远。你觉得没什么，但花都谢了。星币九逆位问你：你多久没浇过水了？\n\n【心理层面】你怕的是「还能不能救」。你看着荒了的花园，不知道还来不来得及。你问「这段关系的本质是什么」，其实你真正想问的是：「还能活吗？」\n\n【根源层面】你一直以为关系会自己长。不用管，不用顾，不用费心。但你忘了，任何关系都要浇水，都要施肥，都要晒太阳。你一直没给，它当然枯了。星币九逆位说：你现在浇，还来得及。

【走向与影响】你怕的是「分享等于失去」。钱币九逆位提醒你：你真正怕的，可能是匱乏。心理层面的突破，是问——我们是在享受还是在囤積？忌囤積不流动，佈施或投資未来会带动更多丰盛。`,
  spiritLayer: `宇宙在等你拿起水壶。不用浇太多，就浇一点。你浇了，它就会开始绿。\n\n核心启示：你怕的不是荒了，是你怕浇了之后，发现根本不想让它活。

就走向而言，两人的气机还绕在「孤島」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「流动」的小事：选一件你一直「囤着不分享」的，做一个小小的流动。检查你的「行囊」：钱币九逆位问你——你囤的，是丰盛还是恐惧？`,
  masterSummary: `走向的纽子在「孤島」——真正的花园不是你一直有，是你荒了之后，还敢回去种。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是丰盛未流动。钱币九逆位说：丰盛是拿来用的，不是拿来囤的。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'pentacles_10', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（钱币十正位）想对你说：走向不是「没有傳承」那种误会式的死局，而是两人的劲还拧在「傳承的定义未对齊」上，没一起认、也没一起动。 累積已滿、进入傳承阶段；最大的阻碍，是你们对「我们要守护什么」「家族方向」「长期藍图」没有共識——一起经营长远未来、討論结婚、買房或共同資產；適合规划长远藍图，而不是追求短期刺激。钱币十说：阻碍是「未对齊的傳承」；规划长远藍图。 你站在一棵大树下，树上有十枚金币。 走向听行动。今天只兑现「傳承」——让对方看见你在动，而不是在讲。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「传承」。可能是你们见家长了，可能是你们谈婚论嫁了，可能是你们计划要孩子了。你不再只是你，你是「我们」的一部分。星币十问你：你准备好成为「我们」了吗？\n\n【心理层面】你怕的是「失去自己」。你怕融进一个家族之后，就再也找不到自己了。你问「这段关系的本质是什么」，其实你真正想问的是：「我还是我吗？」\n\n【根源层面】你从小就是一个人。一个人长大，一个人决定，一个人负责。现在突然要和别人绑在一起，你不习惯。但星币十说：绑在一起，不是绑死，是绑成一个更大的人。

【走向与影响】你怕的是「傳承会斷」。钱币十正位提醒你：你真正要的，是一段可以一起傳承的关系。心理层面的突破，是接纳——你較像一位「守护者」，正在維繫既有的安全感与稳定。`,
  spiritLayer: `宇宙在等你接住那枚金币。不是接住钱，是接住那些爱、那些责任、那些传承。你接了，你就有根了。\n\n核心启示：你怕的不是没有自己，是你怕有了根之后，就再也飞不起来了。

这条关系的走势，眼下还拴在「傳承」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「傳承」的小事：和对方談一次「我们想留给这段关系／家庭的是_____」。检查你的「行囊」：钱币十问你——你们守护的，是真心想守的根基还是习惯？`,
  masterSummary: `势头绕在「傳承」上——真正的传承不是你被绑住了，是你绑住之后，还能飞得更高。 第二问早已点破：你们之间最大的阻碍，往往是傳承的定义未对齊。钱币十说：规划长远藍图。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'pentacles_10', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（钱币十逆位）想对你说：走向被「根基正在松动」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 家庭结構、事業方向、与家人的金钱价值觀、或你对成功的定义——外表稳定、內心已经疲累，可能为了家庭期待維持一段没有溫度的关系；哪些责任、傳統或角色其实早已过期？钱币十逆位说：阻碍是「未重新定义」；当你愿意重新定义「什么才是我要的家、我要的安全感」，旧的模式会瓦解，才能建立屬于自己的根基。。 家散了。 你要影响走向，今天就卡这一格：把「誠实」做到底，小不要紧，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「分离」。可能是分手了，可能是离婚了，可能是家人反对。你失去的不只是他，还有一个家，一个未来，一个梦。星币十逆位问你：没了这些，你还知道自己是谁吗？\n\n【心理层面】你怕的是「一个人怎么办」。你习惯了有他，有家，有未来。现在都没了，你问「这段关系的本质是什么」，其实你真正想问的是：「我一个人，能行吗？」\n\n【根源层面】你一直活在关系里。爸妈的关系，朋友的关系，他的关系。你从来没自己活过，所以现在一个人，你慌。但星币十逆位说：自己活，不是没人要，是你要学会要自己。

【走向与影响】你怕的是「一松就全垮」。钱币十逆位提醒你：你真正怕的，可能是失去既有。心理层面的突破，是问——我们想守护的，是表面體面还是彼此真实的幸福？坦誠沟通。`,
  spiritLayer: `宇宙在等你重新种一棵树。不是种给别人，是种给自己。你种了，你就有根了。\n\n核心启示：你怕的不是没人要，是你怕要了自己之后，发现自己根本不值。

若问势头卡在哪，多半是「根基松动」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「誠实」的小事：寫下一句「我们一直在維持的_____，其实我／我们已经_____」。检查你的「行囊」：钱币十逆位问你——你維持的，是爱还是包袱？`,
  masterSummary: `「根基松动」松一寸，走向就变一寸——真正的家不是别人给你的，是你一个人也能盖的。 第二问那句仍管用：你们之间最大的阻碍，往往是未重新定义家与安全感。钱币十逆位说：旧模式会瓦解，才能建立屬于自己的根基。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'pentacles_11', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（钱币侍从正位）想对你说：走向不是「没有學习」那种误会式的死局，而是两人的劲还拧在「學习未化成行动」上，没一起认、也没一起动。 手捧钱币专注端詳；最大的阻碍，是你们对关系的「一起打基礎」停留在计画阶段——以实际行动经营关系、一起學习或规划未来；把學到的东西立刻用一个小专案练手，不必等完美，先做出一点可见的成果。钱币侍从说：阻碍是「未练手」；先开始做。 你捧着一枚金币，认真地看着。 你要影响走向，今天就卡这一格：把「练手」做到底，小不要紧，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「新鲜感」。可能是刚认识，可能是刚在一起，可能是还有很多东西你不知道。你好奇，想知道他的一切，想了解他的喜好、他的过去、他的未来。星币侍从问你：你喜欢的是他，还是了解他的过程？\n\n【心理层面】你怕的是「了解完了就没了」。你怕一旦全知道了，就没新鲜感了，就不爱了。你问「这段关系的本质是什么」，其实你真正想问的是：「了解完之后，我还爱你吗？」\n\n【根源层面】你是个好奇的人。什么都想了解，什么都想知道。但你也知道，了解完了，就会失去兴趣。你把这套用在感情上，怕了解完就不爱了。但星币侍从说：真正的爱，是了解了还爱。

【走向与影响】你怕的是「做不好」。钱币侍从正位提醒你：你真正要的，是一段可以一起學、一起练的关系。心理层面的突破，是接纳——侍从的力量在「开始做」，不在「准备好」。`,
  spiritLayer: `宇宙在等你慢慢了解。不用急，慢慢看，慢慢学。学不完的，因为他也在变。你们一起变，就永远有新鲜感。\n\n核心启示：你怕的不是了解，是你怕了解了之后，发现他不是你想的那样。

能量没有散，是聚在「學徒」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「练手」的小事：为这段关系做一件「小专案」——一个共同计画的第一步、一次一起學的东西。检查你的「行囊」：钱币侍从问你——你们學的，是关系还是逃避？`,
  masterSummary: `想动走势，先认「學徒」这道结——真正的了解不是你全知道了，是你知道了还愿意继续知道。 对照第二问：你们之间最大的阻碍，往往是未用小专案练手。钱币侍从说：先开始做。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'pentacles_11', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（钱币侍从逆位）想对你说：走向被「學习变成拖延、实踐变成纸上談兵」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 计画一堆却迟迟不开工、或只说不做、迟迟不愿给出承诺与具體投入——今天就把一个小步驟做出来，不必大，先动；与其追求完美的计画，不如先有一个不完美但真实的开始。钱币侍从逆位说：阻碍是「未开始」；先动，不必完美。 你玩腻了。 走向听行动。今天只兑现「第一步」——让对方看见你在动，而不是在讲。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「急于求成」。可能是你想快点结婚，快点稳定，快点有结果。你不耐烦慢慢来，不想了解细节，只想快点到终点。星币侍从逆位问你：终点到了之后，你干什么？\n\n【心理层面】你怕的是「慢了就没了」。你太想抓结果了，太怕时间耗着耗着就没了。你问「这段关系的本质是什么」，其实你真正想问的是：「能不能快点给我答案？」\n\n【根源层面】你从小就是个急性子。什么事都想快点做完，什么结果都想快点得到。你把这个性子带进感情，但感情是慢的，急不得。星币侍从逆位说：你越急，越看不清。

【走向与影响】你怕的是「一做就错」。钱币侍从逆位提醒你：你真正怕的，可能是失败。心理层面的突破，是问——我们是在准备还是在拖延？本周就做第一步，避免只停留在计画阶段。`,
  spiritLayer: `宇宙在等你慢下来。慢下来，才能看见细节，才能闻见花香，才能听见他呼吸。你一直跑，永远在终点。\n\n核心启示：你怕的不是慢，是你怕慢了之后，发现根本到不了。

就走向而言，两人的气机还绕在「未开始」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「第一步」的小事：选一件你一直「在计画」的关于这段关系的事，今天做最小的一步。检查你的「行囊」：钱币侍从逆位问你——你拖延的，是完美主义还是恐惧？`,
  masterSummary: `走向的纽子在「未开始」——真正的长大不是你快了，是你慢的时候，还能不着急。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是未做第一步。钱币侍从逆位说：不完美但真实的开始，勝过完美计画。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'pentacles_12', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（钱币騎士正位）想对你说：走向不是「没有稳健」那种误会式的死局，而是两人的劲还拧在「稳健未兌现」上，没一起认、也没一起动。 稳健前行的騎士；最大的阻碍，是你们其中一人或两人答應了却没做到、或一直「在准备」却从不出发——按部就班、可靠、把承诺落实；可靠比浪漫更重要，兌现比承诺更重要。钱币騎士说：阻碍是「未兌现」；一步一脚印，不抄捷徑。 你骑着马，慢慢地走。 今天用「兌现」替关系试温：你动了，场的流向才会跟着变。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「稳」。可能是你们在一起很久了，可能是你们不折腾了，可能是你们一步一个脚印地走。你不急，他也不急，你们就这样往前走。星币骑士问你：你稳，是因为不想要更多，还是不敢要更多？\n\n【心理层面】你怕的是「要多了会乱」。你太珍惜现在了，怕一要，就乱；一乱，就没了。你问「这段关系的本质是什么」，其实你真正想问的是：「一直这样，够了吗？」\n\n【根源层面】你是个踏实的人。一步一步走，稳稳当当活。你相信慢慢来才稳，慢慢来才不会摔。但你不知道，太稳了，也会错过风景。星币骑士说：稳是好的，但稳的时候，也要记得看路边的花。

【走向与影响】你怕的是「慢会输」。钱币騎士正位提醒你：你真正要的，是一段可以一起稳稳走的关系。心理层面的突破，是接纳——用实际行动与耐心经营关系。`,
  spiritLayer: `宇宙在等你慢慢骑。不用快，也不用停，就慢慢骑。骑着骑着，你就到了。\n\n核心启示：你怕的不是不稳，是你怕稳了之后，发现生活也就这样了。

这条关系的走势，眼下还拴在「稳健」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「兌现」的小事：选一件你曾经答應过对方的事，今天做一步或完成它。检查你的「行囊」：钱币騎士问你——你走的，是稳健还是逃避速度？`,
  masterSummary: `势头绕在「稳健」上——真正的稳不是你一直走，是你走的时候，还不怕停下来。 第二问早已点破：你们之间最大的阻碍，往往是稳健未兌现。钱币騎士说：可靠比浪漫更重要。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'pentacles_12', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（钱币騎士逆位）想对你说：走向被「稳健变成僵化、迟滯或只说不做」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 过度保守、不敢承诺、或拖延迟到答應了却没做到——可靠不是慢，是说到做到；若你一直在「准备」却从不出发，或許是该迈出第一步的時候。钱币騎士逆位说：阻碍是「未出发」；可靠是说到做到。 你走不动了。 你能拧动的开关往往在细节：今天把「出发」做实，比分析十句有用。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「负担」。可能是你扛了太多责任，可能是你担心太多未来，可能是你放不下太多过去。你被压得喘不过气，走不动道。星币骑士逆位问你：你带的这些，有多少是他让你带的，有多少是你自己背的？\n\n【心理层面】你怕的是「放下来就散了」。你以为你扛着一切，关系才能维持。但你不知道，你扛的太多，他已经看不见你了。你问「这段关系的本质是什么」，其实你真正想问的是：「我放下来，他还会在吗？」\n\n【根源层面】你从小就是个会扛事的人。家里的事你扛，朋友的事你扛，他的事你也扛。你扛惯了，忘了有些东西不该你扛。星币骑士逆位说：你把不该你扛的放下来，才能看见该你扛的是什么。

【走向与影响】你怕的是「一动就错」。钱币騎士逆位提醒你：你真正怕的，可能是承诺。心理层面的突破，是问——我们是在稳健还是拖延？该动就动，该承诺就承诺。`,
  spiritLayer: `宇宙在等你放一件。不用全放，就放一件。你放了，看看会不会散。\n\n核心启示：你怕的不是走不动，是你怕放下来之后，发现自己背的都是别人的。

能量没有散，是聚在「未动」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「出发」的小事：选一件你一直「在准备」的事，今天做一个「出发」的动作。检查你的「行囊」：钱币騎士逆位问你——你停滯的，是稳健还是恐惧？`,
  masterSummary: `想动走势，先认「未动」这道结——真正的骑士不是一直扛着走，是他知道什么时候该放下。 对照第二问：你们之间最大的阻碍，往往是未出发。钱币騎士逆位说：可靠是说到做到。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'pentacles_13', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（钱币皇后正位）想对你说：走向不是「没有滋养」那种误会式的死局，而是两人的劲还拧在「滋养变成控制」上，没一起认、也没一起动。 坐拥丰饒手捧钱币；最大的阻碍，是你们其中一人用物质或付出綁住对方、或没有先照顧好自己就试图填滿对方——把資源转化成安全感与照顧，让关系有物质与情感的双重根基；你的丰盛是拿来用的，不是拿来炫耀的。钱币皇后说：阻碍是「未健康滋养」；先照顧好自己，再照顧身边人。 你坐在自己的花园里，怀里抱着一枚金币。 你若真想推动走势，就从「滋养」开始——轻，但要真。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「丰盛」。可能是你们什么都有了，可能是你觉得自己已经很幸福了，可能是你不再想要更多。你满足，你快乐，你觉得这样就挺好。星币王后问你：你是真的满足，还是不敢再要了？\n\n【心理层面】你怕的是「要了会破坏现在」。你太珍惜现在的一切，怕一伸手，就打破了平衡。你问「这段关系的本质是什么」，其实你真正想问的是：「我能不贪心，但能一直这样吗？」\n\n【根源层面】你是个容易知足的人。有饭吃，有衣穿，有人爱，你就觉得够了。你从不贪，从不争，从不抢。但你也知道，不争，也会失去。星币王后说：知足，不是不争取；是不强求。

【走向与影响】你怕的是「不给就不被爱」。钱币皇后正位提醒你：你真正要的，是一段可以相互滋养的关系。心理层面的突破，是接纳——先照顧好自己，再照顧对方。`,
  spiritLayer: `宇宙在等你享受你的花园。不用给别人看，就自己享受。你享受了，才知道，你有多少。\n\n核心启示：你怕的不是没有，是你怕有了之后，还会失去。

能量没有散，是聚在「土元素女性」上打转；你愿意先松一处、先认一点，走向才会开始拐弯。`,
  actionPath: `今天做一件「滋养」的小事：用一件具體的事「滋养」这段关系——一頓飯、一筆共同儲蓄、或一个让家更稳的决定。检查你的「行囊」：钱币皇后问你——你给的，是丰盛还是討爱？`,
  masterSummary: `想动走势，先认「土元素女性」这道结——真正的满足不是你什么都有，是你有的，你都很喜欢。 对照第二问：你们之间最大的阻碍，往往是滋养未健康流动。钱币皇后说：丰盛是拿来用的。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'pentacles_13', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（钱币皇后逆位）想对你说：走向被「滋养变成控制、或丰盛变成匱乏感」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 用物质或付出綁住对方、或觉得自己给得太多收得太少——滋养是让对方成长，不是让对方依賴；在照顧的同時，留一点空间给对方自由；你的价值不在你给了多少，而在你是谁。钱币皇后逆位说：阻碍是「控制」；你的价值不在你给了多少。 你的花园乱套了。 别等对方先示范。今天你先用「放手」给关系一个可跟的节拍。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「焦虑」。可能是你觉得不够好，可能是你觉得他还不够爱你，可能是你觉得你们的未来还不够确定。你拼命想要更多，但越要越累。星币王后逆位问你：你要的，是他能给的，还是你自己心里那个洞？\n\n【心理层面】你怕的是「不够」。你太怕不够了，所以一直要，一直要，要到自己都累。你问「这段关系的本质是什么」，其实你真正想问的是：「到底多少才算够？」\n\n【根源层面】你从小就在「不够」里长大。钱不够，时间不够，爱不够。你习惯了不够，习惯了要。但你要了这么多年，也没填满那个洞。星币王后逆位说：洞不是填满的，是看见的。你看见了，就不需要填了。

【走向与影响】你怕的是「一松就没人需要我」。钱币皇后逆位提醒你：你真正怕的，可能是被取代。心理层面的突破，是问——我们是在滋养还是在控制？在照顧的同時，留空间给对方自由。`,
  spiritLayer: `宇宙在等你停下来。不弄了，不整了，就坐一会儿。坐了，你会发现，乱也有乱的美。\n\n核心启示：你怕的不是不够，是你怕够了之后，发现自己根本不认识那个不想要的人。

若问势头卡在哪，多半是「控制或匱乏感」还没被两个人一起摊开；你先从自己这一侧动一下，比等对方顿悟快。`,
  actionPath: `今天做一件「放手」的小事：选一件你习惯「用付出綁住」的事，今天少做一点，让对方有空间。检查你的「行囊」：钱币皇后逆位问你——你给的，是滋养还是控制？`,
  masterSummary: `「控制或匱乏感」松一寸，走向就变一寸——真正的满足不是你终于够了，是你敢在不够的时候，还说「没事」。 第二问那句仍管用：你们之间最大的阻碍，往往是滋养变成控制。钱币皇后逆位说：你的价值不在你给了多少。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'pentacles_14', true, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（钱币国王正位）想对你说：走向不是「没有稳固」那种误会式的死局，而是两人的劲还拧在「权威取代了柔软」上，没一起认、也没一起动。 坐鎮宝座脚踩野豬手握钱币；最大的阻碍，是你们其中一人用「我来定规矩」「我来負责」壓过对方的声音——稳健的領导，但領导是服務关系的稳定，不是服務 ego；在稳固的同時，留一点柔软给身边的人。钱币国王说：阻碍是「单向的权威」；在稳固時留一点柔软。 你坐在王座上，手里拿着权杖，面前是一堆金币。 把力气花在看得见的一步：今天只做「柔软」，做完就停。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「滋养」。可能是你让他变好了，可能是他让你更稳了。你们在一起，不是消耗，是互相滋养。星币国王问你：你滋养他的时候，自己也在长吗？\n\n【心理层面】你怕的是「光滋养别人，把自己耗干了」。你一直在给，一直在帮，一直在带。但你也会累，也会需要人带。你问「这段关系的本质是什么」，其实你真正想问的是：「我给他这么多，谁给我？」\n\n【根源层面】你是个好领袖。工作带人，生活带人，感情也带人。你习惯了走在前面，习惯了让别人靠。但你忘了，领袖也需要人靠。星币国王说：你让他靠，也得让他知道你也会累。

【走向与影响】你怕的是「一软就亂」。钱币国王正位提醒你：你真正要的，是一段可以一起稳稳統治的关系。心理层面的突破，是接纳——能提供物质与结構上的安全感；权威来自稳健与照顧，不是来自控制。`,
  spiritLayer: `宇宙在等你收一次。不是收钱，是收爱。他给你的时候，你别推，接着。你接了，才知道，你也是人，不是神。\n\n核心启示：你怕的不是给不了，是你怕给了之后，发现自己也需要。

这条关系的走势，眼下还拴在「土元素最高显化」上；你改一个小动作、一句真话或一次退让，场里都会有回音。`,
  actionPath: `今天做一件「柔软」的小事：选一件你习惯「我来定规矩」的事，今天问对方「你觉得呢？」检查你的「行囊」：钱币国王问你——你的权威，是服務关系还是服務 ego？`,
  masterSummary: `势头绕在「土元素最高显化」上——真正的国王不是他一个人撑着，是他撑的时候，也有人撑他。 第二问早已点破：你们之间最大的阻碍，往往是权威未留柔软。钱币国王说：領导是服務稳定。`,
});
register(感情婚姻, 我们目前的关系能量走向如何我可以做什么来影响它, 'pentacles_14', false, {
  cardSpeaking: `你问我们目前的关系能量走向如何、我可以做什么来影响它——我（钱币国王逆位）想对你说：走向被「权威变成专制、稳固变成僵化或貪婪」拖住了；不是没路，是这股力一直没被你们摊开来说、更没约好怎么分担。 用金钱或資源控制对方、或只顧累積不顧关系品质——稳固是为了让关系与家人过得好，不是为了证明自己有多強；在堅持原則時，留一点彈性给爱与意外；真正的富有，是身边有人愿意与你一起守护。钱币国王逆位说：阻碍是「专制或僵化」；真正的富有是有人愿意一起守护。 你守着自己的金币，谁都不给。 影响走向不靠喊话，靠落地。今天完成「彈性」，再谈别的。`,
  psychologyLayer: `【关系现状】你们的关系里有一种「守财奴」。可能是你舍不得付出，可能是你怕给太多会吃亏，可能是你一直在算账。你算来算去，算得感情都没了。星币国王逆位问你：你守的，是感情，还是你的安全感？\n\n【心理层面】你怕的是「给了就没了」。你把感情当成了有限的，给了就少一点。所以你一直收着，收着，收到对方都冷了。你问「这段关系的本质是什么」，其实你真正想问的是：「我给出去，他会不会跑？」\n\n【根源层面】你曾经给过，然后被伤了。那次之后，你就再也不肯给了。你把自己包起来，以为这样就安全了。但你不知道，包着的人，也出不去了。星币国王逆位说：你不给，他也不给，你们就抱着金币一起冷。

【走向与影响】你怕的是「一让就失控」。钱币国王逆位提醒你：你真正怕的，可能是失去控制。心理层面的突破，是问——我们是在守护还是在控制？在堅持原則時，留一点彈性给爱。`,
  spiritLayer: `宇宙在等你给一次。不用给多，就一次。给了，你会发现，他也会给。你们给着给着，就热了。\n\n核心启示：你怕的不是没有，是你怕给了之后，发现自己根本收不到。

就走向而言，两人的气机还绕在「专制或僵化」上；你这边一动诚实、一松手或一立界，这条线都会跟着颤。`,
  actionPath: `今天做一件「彈性」的小事：选一件你习惯「按规矩来」的事，今天做一个小小的例外，为关系而非为规矩。检查你的「行囊」：钱币国王逆位问你——你堅持的，是原則还是控制？`,
  masterSummary: `走向的纽子在「专制或僵化」——真正的国王不是他守得住，是他敢给的时候，还不怕没有。 要推动它，记着第二问那句：你们之间最大的阻碍，往往是权威未留彈性。钱币国王逆位说：真正的富有是有人愿意一起守护。`,
});
